    category: AdhkarCategory.quranicDuas,
    titleAr: r'''سورة الفاتحة''',
    titleEn: r'''Surah al-Fatiha (The Opening)''',
    arabicText: r'''أَعُوذُ بِاللَّهِ مِنَ الشَّيطَانِ الرَّجِيمِ — بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ
ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ ﴿١﴾ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ﴿٢﴾ مَٰلِكِ يَوْمِ ٱلدِّينِ ﴿٣﴾ إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ﴿٤﴾ ٱهْدِنَا ٱلصِّرَٰطَ ٱلْمُسْتَقِيمَ ﴿٥﴾ صِرَٰطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِمْ وَلَا ٱلضَّآلِّينَ ﴿٦﴾ . ( آمين )''',
    transliteration: r'''A'udhu billahi mina-sh-shaytani-r-rajim. Bismillahi-r-Rahmani-r-Rahim. Al-hamdu lillahi Rabbi-l-'alamin. Ar-Rahmani-r-Rahim. Maliki yawmi-d-din. Iyyaka na'budu wa iyyaka nasta'in. Ihdina-s-sirata-l-mustaqim. Sirata-lladhina an'amta 'alayhim, ghayri-l-maghdubi 'alayhim wa la-d-dallin. (Amin)''',
    translationEn: r'''I seek refuge in Allah from Satan, the accursed. In the name of Allah, the Entirely Merciful, the Especially Merciful. All praise is due to Allah, Lord of the worlds — the Entirely Merciful, the Especially Merciful, Sovereign of the Day of Recompense. It is You we worship and You we ask for help. Guide us to the straight path — the path of those upon whom You have bestowed favor, not of those who have evoked Your anger or of those who are astray. (Ameen)''',
    sourceReference: r'''Qur'an, Surah al-Fatiha 1-7''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''quran_baqarah_1_5''',
    category: AdhkarCategory.quranicDuas,
    titleAr: r'''مطلع سورة البقرة''',
    titleEn: r'''Opening of Surah al-Baqarah''',
    arabicText: r'''بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ
الٓمٓ ﴿١﴾ ذَٰلِكَ ٱلْكِتَٰبُ لَا رَيْبَ فِيهِ هُدًى لِّلْمُتَّقِينَ ﴿٢﴾ ٱلَّذِينَ يُؤْمِنُونَ بِٱلْغَيْبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ ﴿٣﴾ وَٱلَّذِينَ يُؤْمِنُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ وَبِٱلْءَاخِرَةِ هُمْ يُوقِنُونَ ﴿٤﴾ أُو۟لَٰٓئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ ﴿٥﴾''',
    transliteration: r'''Bismillahi-r-Rahmani-r-Rahim. Alif-Lam-Mim. Dhalika-l-kitabu la rayba fih, hudan lil-muttaqin. Alladhina yu'minuna bil-ghaybi wa yuqimuna-s-salata wa mimma razaqnahum yunfiqun. Wa-lladhina yu'minuna bima unzila ilayka wa ma unzila min qablik, wa bil-akhirati hum yuqinun. Ula'ika 'ala hudan mir-rabbihim, wa ula'ika humu-l-muflihun.''',
    translationEn: r'''In the name of Allah, the Entirely Merciful, the Especially Merciful. Alif, Lam, Meem. This is the Book about which there is no doubt, a guidance for those conscious of Allah — who believe in the unseen, establish prayer, and spend out of what We have provided for them; and who believe in what has been revealed to you and what was revealed before you, and are certain of the Hereafter. Those are upon guidance from their Lord, and it is those who are successful.''',
    sourceReference: r'''Qur'an, Surah al-Baqarah 1-5''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''quran_baqarah_163''',
    category: AdhkarCategory.quranicDuas,
    titleAr: r'''آية الوحدانية''',
    titleEn: r'''Verse of Allah's Oneness''',
    arabicText: r'''وَإِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ لَّآ إِلَٰهَ إِلَّا هُوَ ٱلرَّحْمَٰنُ ٱلرَّحِيمُ''',
    transliteration: r'''Wa ilahukum ilahun wahid, la ilaha illa huwa-r-Rahmanu-r-Rahim.''',
