  AdhkarEntry(
    id: r'''quran_ayat_al_kursi''',
    category: AdhkarCategory.quranicDuas,
    titleAr: r'''آية الكرسي''',
    titleEn: r'''The Throne Verse (Ayat al-Kursi)''',
    arabicText: r'''ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ وَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ''',
    transliteration: r'''Allahu la ilaha illa huwa-l-Hayyu-l-Qayyum, la ta'khudhuhu sinatun wa la nawm, lahu ma fi-s-samawati wa ma fi-l-ard, man dha-lladhi yashfa'u 'indahu illa bi-idhnih, ya'lamu ma bayna aydihim wa ma khalfahum, wa la yuhituna bishay'im-min 'ilmihi illa bima sha', wasi'a kursiyyuhu-s-samawati wal-ard, wa la ya'uduhu hifdhuhuma, wa huwa-l-'Aliyyu-l-'Adhim.''',
    translationEn: r'''Allah — there is no deity except Him, the Ever-Living, the Sustainer of all existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is before them and what will be after them, and they encompass nothing of His knowledge except what He wills. His Throne extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great.''',
    sourceReference: r'''Qur'an, Surah al-Baqarah 255''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''quran_baqarah_285_286''',
    category: AdhkarCategory.quranicDuas,
    titleAr: r'''خواتيم سورة البقرة''',
    titleEn: r'''The Closing Verses of Surah al-Baqarah''',
    arabicText: r'''ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيْهِ مِن رَّبِّهِۦ وَٱلْمُؤْمِنُونَ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِۦ وَقَالُوا۟ سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ ٱلْمَصِيرُ ﴿٢٨٥﴾ لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا ٱكْتَسَبَتْ رَبَّنَا لَا تُؤَاخِذْنَآ إِن نَّسِينَآ أَوْ أَخْطَأْنَا رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَآ إِصْرًا كَمَا حَمَلْتَهُۥ عَلَى ٱلَّذِينَ مِن قَبْلِنَا رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِۦ وَٱعْفُ عَنَّا وَٱغْفِرْ لَنَا وَٱرْحَمْنَآ أَنتَ مَوْلَىٰنَا فَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ ﴿٢٨٦﴾''',
    transliteration: r'''Amana-r-rasulu bima unzila ilayhi mir-rabbihi wal-mu'minun, kullun amana billahi wa mala'ikatihi wa kutubihi wa rusulih, la nufarriqu bayna ahadim-mir-rusulih, wa qalu sami'na wa ata'na ghufranaka rabbana wa ilayka-l-masir. La yukallifullahu nafsan illa wus'aha, laha ma kasabat wa 'alayha ma-ktasabat. Rabbana la tu'akhidhna in nasina aw akhta'na. Rabbana wa la tahmil 'alayna isran kama hamaltahu 'ala-lladhina min qablina. Rabbana wa la tuhammilna ma la taqata lana bih, wa'fu 'anna, wa-ghfir lana, wa-rhamna, anta mawlana fa-nsurna 'ala-l-qawmi-l-kafirin.''',
    translationEn: r'''The Messenger has believed in what was revealed to him from his Lord, and so have the believers. All of them have believed in Allah, His angels, His books, and His messengers, saying, "We make no distinction between any of His messengers." And they say, "We hear and we obey. Your forgiveness, our Lord, and to You is the final destination." Allah does not charge a soul except with that within its capacity. It will have what it has earned, and it will bear what it has earned. "Our Lord, do not impose blame upon us if we have forgotten or erred. Our Lord, lay not upon us a burden like that which You laid upon those before us. Our Lord, burden us not with what we have no ability to bear. Pardon us, forgive us, and have mercy upon us. You are our Protector, so give us victory over the disbelieving people."''',
    sourceReference: r'''Qur'an, Surah al-Baqarah 285-286''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''quran_aal_imran_1_6''',
    category: AdhkarCategory.quranicDuas,
    titleAr: r'''مطلع سورة آل عمران''',
    titleEn: r'''Opening of Surah Aal 'Imran''',
    arabicText: r'''بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ
الٓمٓ ﴿١﴾ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ ﴿٢﴾ نَزَّلَ عَلَيْكَ ٱلْكِتَٰبَ بِٱلْحَقِّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ وَأَنزَلَ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ ﴿٣﴾ مِن قَبْلُ هُدًى لِّلنَّاسِ وَأَنزَلَ ٱلْفُرْقَانَ إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ لَهُمْ عَذَابٌ شَدِيدٌ وَٱللَّهُ عَزِيزٌ ذُو ٱنتِقَامٍ ﴿٤﴾ إِنَّ ٱللَّهَ لَا يَخْفَىٰ عَلَيْهِ شَىْءٌ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ ﴿٥﴾ هُوَ ٱلَّذِى يُصَوِّرُكُمْ فِى ٱلْأَرْحَامِ كَيْفَ يَشَآءُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ ﴿٦﴾''',
    transliteration: r'''Bismillahi-r-Rahmani-r-Rahim. Alif-Lam-Mim. Allahu la ilaha illa huwa-l-Hayyu-l-Qayyum. Nazzala 'alayka-l-kitaba bil-haqqi musaddiqal-lima bayna yadayhi wa anzala-t-Tawrata wal-Injil. Min qablu hudal-linnasi wa anzala-l-Furqan. Inna-lladhina kafaru bi-ayatillahi lahum 'adhabun shadid, wallahu 'azizun dhu-ntiqam. Innallaha la yakhfa 'alayhi shay'un fil-ardi wa la fis-sama'. Huwa-lladhi yusawwirukum fil-arhami kayfa yasha', la ilaha illa huwa-l-'Azizu-l-Hakim.''',
    translationEn: r'''In the name of Allah, the Entirely Merciful, the Especially Merciful. Alif, Lam, Meem. Allah — there is no deity except Him, the Ever-Living, the Sustainer of existence. He has sent down upon you the Book in truth, confirming what was before it, and He revealed the Torah and the Gospel before, as guidance for the people, and He revealed the Criterion. Indeed, those who disbelieve in the verses of Allah will have a severe punishment, and Allah is Exalted in Might, the Owner of Retribution. Indeed, from Allah nothing is hidden in the earth nor in the heaven. It is He who forms you in the wombs however He wills. There is no deity except Him, the Exalted in Might, the Wise.''',
    sourceReference: r'''Qur'an, Surah Aal 'Imran 1-6''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''quran_aal_imran_18''',
    category: AdhkarCategory.quranicDuas,
    titleAr: r'''آية شهد الله''',
    titleEn: r'''Verse of Allah's Testimony (Shahida Allah)''',
    arabicText: r'''شَهِدَ ٱللَّهُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا هُوَ وَٱلْمَلَٰٓئِكَةُ وَأُو۟لُوا۟ ٱلْعِلْمِ قَآئِمًۢا بِٱلْقِسْطِ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ''',
    transliteration: r'''Shahida-llahu annahu la ilaha illa huwa, wal-mala'ikatu wa ulu-l-'ilmi qa'imam-bil-qist, la ilaha illa huwa-l-'Azizu-l-Hakim.''',
    translationEn: r'''Allah bears witness that there is no deity except Him — and so do the angels and those of knowledge — maintaining creation in justice. There is no deity except Him, the Exalted in Might, the Wise.''',
    sourceReference: r'''Qur'an, Surah Aal 'Imran 18''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''quran_aal_imran_26_28''',
    category: AdhkarCategory.quranicDuas,
    titleAr: r'''دعاء قل اللهم مالك الملك''',
    titleEn: r'''"Say, O Allah, Owner of Sovereignty..."''',
    arabicText: r'''قُلِ ٱللَّهُمَّ مَٰلِكَ ٱلْمُلْكِ تُؤْتِى ٱلْمُلْكَ مَن تَشَآءُ وَتَنزِعُ ٱلْمُلْكَ مِمَّن تَشَآءُ وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن تَشَآءُ بِيَدِكَ ٱلْخَيْرُ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ ﴿٢٦﴾ تُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَتُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَتُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَتُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ وَتَرْزُقُ مَن تَشَآءُ بِغَيْرِ حِسَابٍ ﴿٢٧﴾ لَا يَتَّخِذِ ٱلْمُؤْمِنُونَ ٱلْكَٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ وَمَن يَفْعَلْ ذَٰلِكَ فَلَيْسَ مِنَ ٱللَّهِ فِى شَىْءٍ إِلَّآ أَن تَتَّقُوا۟ مِنْهُمْ تُقَىٰةً وَيُحَذِّرُكُمُ ٱللَّهُ نَفْسَهُۥ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ ﴿٢٨﴾''',
    transliteration: r'''Quli-llahumma malika-l-mulki tu'ti-l-mulka man tasha'u wa tanzi'u-l-mulka mimman tasha', wa tu'izzu man tasha'u wa tudhillu man tasha', biyadika-l-khayr, innaka 'ala kulli shay'in qadir. Tulijul-layla fin-nahari wa tulijun-nahara fil-layl, wa tukhrijul-hayya minal-mayyiti wa tukhrijul-mayyita minal-hayy, wa tarzuqu man tasha'u bighayri hisab. La yattakhidhil-mu'minuna-l-kafirina awliya' min duni-l-mu'minin, wa may-yaf'al dhalika falaysa minallahi fi shay'in illa an tattaqu minhum tuqah, wa yuhadhdhirukumullahu nafsah, wa ilallahi-l-masir.''',
    translationEn: r'''Say, "O Allah, Owner of Sovereignty, You give sovereignty to whom You will and You take sovereignty away from whom You will; You honor whom You will and You humble whom You will. In Your hand is all good. Indeed, You are over all things competent. You cause the night to enter the day, and You cause the day to enter the night; and You bring the living out of the dead, and You bring the dead out of the living. And You give provision to whom You will without account." Let not believers take disbelievers as allies rather than believers — whoever does that has nothing with Allah, except when guarding against them out of fear. And Allah warns you of Himself, and to Allah is the final destination.''',
    sourceReference: r'''Qur'an, Surah Aal 'Imran 26-28''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''quran_araf_54_55''',
    category: AdhkarCategory.quranicDuas,
    titleAr: r'''آية ادعوا ربكم''',
    titleEn: r'''"Call Upon Your Lord in Humility"''',
    arabicText: r'''إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ يُغْشِى ٱلَّيْلَ ٱلنَّهَارَ يَطْلُبُهُۥ حَثِيثًا وَٱلشَّمْسَ وَٱلْقَمَرَ وَٱلنُّجُومَ مُسَخَّرَٰتٍۭ بِأَمْرِهِۦٓ أَلَا لَهُ ٱلْخَلْقُ وَٱلْأَمْرُ تَبَارَكَ ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ ﴿٥٤﴾ ٱدْعُوا۟ رَبَّكُمْ تَضَرُّعًا وَخُفْيَةً إِنَّهُۥ لَا يُحِبُّ ٱلْمُعْتَدِينَ ﴿٥٥﴾''',
    transliteration: r'''Inna rabbakumullahu-lladhi khalaqas-samawati wal-arda fi sittati ayyamin thumma-stawa 'alal-'arsh, yughshil-laylan-nahara yatlubuhu hathithan, wash-shamsa wal-qamara wan-nujuma musakhkharatim bi-amrih, ala lahul-khalqu wal-amr, tabarakallahu rabbul-'alamin. Ud'u rabbakum tadarru'an wa khufyah, innahu la yuhibbul-mu'tadin.''',
    translationEn: r'''Indeed, your Lord is Allah, who created the heavens and earth in six days and then established Himself above the Throne. He covers the night with the day, another night chasing it rapidly; and He created the sun, the moon, and the stars, subjected by His command. Unquestionably, His is the creation and the command; blessed is Allah, Lord of the worlds. Call upon your Lord in humility and privately; indeed, He does not like transgressors.''',
    sourceReference: r'''Qur'an, Surah al-A'raf 54-55''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''quran_tawbah_129''',
    category: AdhkarCategory.quranicDuas,
    titleAr: r'''آية حسبي الله''',
    titleEn: r'''"Sufficient for Me Is Allah" (Hasbiya Allah)''',
    arabicText: r'''حَسْبِىَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ''',
    transliteration: r'''Hasbiyallahu la ilaha illa huwa, 'alayhi tawakkaltu wa huwa Rabbul-'arshil-'Azim.''',
    translationEn: r'''Sufficient for me is Allah; there is no deity except Him. On Him I have relied, and He is the Lord of the Great Throne.''',
    sourceReference: r'''Qur'an, Surah at-Tawbah 129''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''quran_muminun_115_118''',
    category: AdhkarCategory.quranicDuas,
    titleAr: r'''آية أفحسبتم''',
    titleEn: r'''"Did You Think We Created You Uselessly?"''',
    arabicText: r'''أَفَحَسِبْتُمْ أَنَّمَا خَلَقْنَٰكُمْ عَبَثًا وَأَنَّكُمْ إِلَيْنَا لَا تُرْجَعُونَ ﴿١١٥﴾ فَتَعَٰلَى ٱللَّهُ ٱلْمَلِكُ ٱلْحَقُّ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلْعَرْشِ ٱلْكَرِيمِ ﴿١١٦﴾ وَمَن يَدْعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ لَا بُرْهَٰنَ لَهُۥ بِهِۦ فَإِنَّمَا حِسَابُهُۥ عِندَ رَبِّهِۦٓ إِنَّهُۥ لَا يُفْلِحُ ٱلْكَٰفِرُونَ ﴿١١٧﴾ وَقُل رَّبِّ ٱغْفِرْ وَٱرْحَمْ وَأَنتَ خَيْرُ ٱلرَّٰحِمِينَ ﴿١١٨﴾''',
    transliteration: r'''Afahasibtum annama khalaqnakum 'abathan wa annakum ilayna la turja'un. Fata'alallahu-l-Maliku-l-Haqq, la ilaha illa huwa, Rabbu-l-'Arshi-l-Karim. Wa may-yad'u ma'allahi ilahan akhara la burhana lahu bih, fa-innama hisabuhu 'inda rabbih, innahu la yuflihu-l-kafirun. Wa qur-rabbi-ghfir warham wa anta khayru-r-rahimin.''',
    translationEn: r'''Then did you think that We created you uselessly and that to Us you would not be returned? So exalted is Allah, the Sovereign, the Truth; there is no deity except Him, Lord of the Noble Throne. And whoever invokes besides Allah another god for which he has no proof — then his account is only with his Lord. Indeed, the disbelievers will not succeed. And say, "My Lord, forgive and have mercy, and You are the best of the merciful."''',
    sourceReference: r'''Qur'an, Surah al-Mu'minun 115-118''',
    repetitionCount: 3,
    repetitionNote: r'''ثلاثًا (three times)''',
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''quran_rum_17_19''',
    category: AdhkarCategory.quranicDuas,
    titleAr: r'''آية فسبحان الله''',
    titleEn: r'''"So Exalted Is Allah When You Reach the Evening"''',
    arabicText: r'''فَسُبْحَٰنَ ٱللَّهِ حِينَ تُمْسُونَ وَحِينَ تُصْبِحُونَ ﴿١٧﴾ وَلَهُ ٱلْحَمْدُ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَعَشِيًّا وَحِينَ تُظْهِرُونَ ﴿١٨﴾ يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَيُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ وَيُحْىِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا وَكَذَٰلِكَ تُخْرَجُونَ ﴿١٩﴾''',
    transliteration: r'''Fasubhanallahi hina tumsuna wa hina tusbihun. Wa lahul-hamdu fis-samawati wal-ardi wa 'ashiyyaw-wa hina tudhhirun. Yukhrijul-hayya minal-mayyiti wa yukhrijul-mayyita minal-hayyi wa yuhyil-arda ba'da mawtiha, wa kadhalika tukhrajun.''',
    translationEn: r'''So exalted is Allah when you reach the evening and when you reach the morning. And to Him is due all praise throughout the heavens and the earth, and in the late afternoon and when you are at noon. He brings the living out of the dead and brings the dead out of the living and gives life to the earth after its lifelessness. And thus will you be brought out.''',
    sourceReference: r'''Qur'an, Surah ar-Rum 17-19''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''quran_saffat_1_11''',
    category: AdhkarCategory.quranicDuas,
    titleAr: r'''مطلع سورة الصافات''',
    titleEn: r'''Opening of Surah as-Saffat''',
    arabicText: r'''بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ
وَٱلصَّٰٓفَّٰتِ صَفًّا ﴿١﴾ فَٱلزَّٰجِرَٰتِ زَجْرًا ﴿٢﴾ فَٱلتَّٰلِيَٰتِ ذِكْرًا ﴿٣﴾ إِنَّ إِلَٰهَكُمْ لَوَٰحِدٌ ﴿٤﴾ رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا وَرَبُّ ٱلْمَشَٰرِقِ ﴿٥﴾ إِنَّا زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِزِينَةٍ ٱلْكَوَاكِبِ ﴿٦﴾ وَحِفْظًا مِّن كُلِّ شَيْطَٰنٍ مَّارِدٍ ﴿٧﴾ لَّا يَسَّمَّعُونَ إِلَى ٱلْمَلَإِ ٱلْأَعْلَىٰ وَيُقْذَفُونَ مِن كُلِّ جَانِبٍ ﴿٨﴾ دُحُورًا وَلَهُمْ عَذَابٌ وَاصِبٌ ﴿٩﴾ إِلَّا مَنْ خَطِفَ ٱلْخَطْفَةَ فَأَتْبَعَهُۥ شِهَابٌ ثَاقِبٌ ﴿١٠﴾ فَٱسْتَفْتِهِمْ أَهُمْ أَشَدُّ خَلْقًا أَم مَّنْ خَلَقْنَآ إِنَّا خَلَقْنَٰهُم مِّن طِينٍ لَّازِبٍۭ ﴿١١﴾''',
    transliteration: r'''Bismillahi-r-Rahmani-r-Rahim. Was-saffati saffa. Faz-zajirati zajra. Fat-taliyati dhikra. Inna ilahakum lawahid. Rabbus-samawati wal-ardi wa ma baynahuma wa Rabbul-mashariq. Inna zayyanna-s-sama'ad-dunya bizinatinil-kawakib. Wa hifzam-min kulli shaytanim-marid. La yassamma'una ilal-mala'il-a'la wa yuqdhafuna min kulli janib. Duhuranw-wa lahum 'adhabun wasib. Illa man khatifal-khatfata fa-atba'ahu shihabun thaqib. Fastaftihim ahum ashaddu khalqan am man khalaqna, inna khalaqnahum min tinil-lazib.''',
    translationEn: r'''In the name of Allah, the Entirely Merciful, the Especially Merciful. By those lined up in rows, and those who drive powerfully, and those who recite the message, indeed your God is One — Lord of the heavens and the earth and that between them, and Lord of the sunrises. Indeed, We have adorned the nearest heaven with an adornment of stars, and as protection against every rebellious devil, so they may not listen to the exalted assembly and are pelted from every side, repelled; and for them is a constant punishment — except one who snatches a word by theft, but he is pursued by a piercing flame. So ask them: are they a stronger creation, or those We have created? Indeed, We created them from sticky clay.''',
    sourceReference: r'''Qur'an, Surah as-Saffat 1-11''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''quran_ghafir_1_3''',
    category: AdhkarCategory.quranicDuas,
    titleAr: r'''مطلع سورة غافر''',
    titleEn: r'''Opening of Surah Ghafir''',
    arabicText: r'''بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ
حمٓ ﴿١﴾ تَنزِيلُ ٱلْكِتَٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْعَلِيمِ ﴿٢﴾ غَافِرِ ٱلذَّنۢبِ وَقَابِلِ ٱلتَّوْبِ شَدِيدِ ٱلْعِقَابِ ذِى ٱلطَّوْلِ لَآ إِلَٰهَ إِلَّا هُوَ إِلَيْهِ ٱلْمَصِيرُ ﴿٣﴾''',
    transliteration: r'''Bismillahi-r-Rahmani-r-Rahim. Ha-Mim. Tanzilul-kitabi minallahi-l-'Azizi-l-'Alim. Ghafiridh-dhanbi wa qabilit-tawbi shadidil-'iqabi dhit-tawl, la ilaha illa huwa ilayhil-masir.''',
    translationEn: r'''In the name of Allah, the Entirely Merciful, the Especially Merciful. Ha, Meem. The revelation of the Book is from Allah, the Exalted in Might, the Knowing — the Forgiver of sin, Acceptor of repentance, severe in punishment, Owner of abundance. There is no deity except Him; to Him is the final destination.''',
    sourceReference: r'''Qur'an, Surah Ghafir 1-3''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''quran_rahman_33_35''',
    category: AdhkarCategory.quranicDuas,
    titleAr: r'''آية يا معشر الجن والإنس''',
    titleEn: r'''"O Company of Jinn and Mankind..."''',
    arabicText: r'''يَٰمَعْشَرَ ٱلْجِنِّ وَٱلْإِنسِ إِنِ ٱسْتَطَعْتُمْ أَن تَنفُذُوا۟ مِنْ أَقْطَارِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ فَٱنفُذُوا۟ لَا تَنفُذُونَ إِلَّا بِسُلْطَٰنٍ ﴿٣٣﴾ فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٣٤﴾ يُرْسَلُ عَلَيْكُمَا شُوَاظٌ مِّن نَّارٍ وَنُحَاسٌ فَلَا تَنتَصِرَانِ ﴿٣٥﴾''',
    transliteration: r'''Ya ma'sharal-jinni wal-insi ini-stata'tum an tanfudhu min aqtaris-samawati wal-ardi fanfudhu, la tanfudhuna illa bisultan. Fabi-ayyi ala'i rabbikuma tukadhdhiban. Yursalu 'alaykuma shuwazum-min narinw-wa nuhasun fala tantasiran.''',
    translationEn: r'''O company of jinn and mankind, if you are able to pass beyond the regions of the heavens and the earth, then pass; you will not pass except by authority from Allah. So which of the favors of your Lord would you deny? There will be sent against you a flame of fire and smoke, and you will not be victorious.''',
    sourceReference: r'''Qur'an, Surah ar-Rahman 33-35''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''quran_hashr_22_24''',
    category: AdhkarCategory.quranicDuas,
    titleAr: r'''خواتيم سورة الحشر''',
    titleEn: r'''The Closing Verses of Surah al-Hashr''',
    arabicText: r'''هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ هُوَ ٱلرَّحْمَٰنُ ٱلرَّحِيمُ ﴿٢٢﴾ هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ ﴿٢٣﴾ هُوَ ٱللَّهُ ٱلْخَٰلِقُ ٱلْبَارِئُ ٱلْمُصَوِّرُ لَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ يُسَبِّحُ لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ ﴿٢٤﴾''',
    transliteration: r'''Huwallahu-lladhi la ilaha illa huwa, 'alimul-ghaybi wash-shahadah, huwar-Rahmanu-r-Rahim. Huwallahu-lladhi la ilaha illa huwa, al-Maliku-l-Quddusu-s-Salamu-l-Mu'minu-l-Muhayminu-l-'Azizu-l-Jabbaru-l-Mutakabbir, subhanallahi 'amma yushrikun. Huwallahu-l-Khaliqu-l-Bari'u-l-Musawwiru lahul-asma'ul-husna, yusabbihu lahu ma fis-samawati wal-ardi wa huwal-'Azizul-Hakim.''',
    translationEn: r'''He is Allah, other than whom there is no deity, Knower of the unseen and the witnessed. He is the Entirely Merciful, the Especially Merciful. He is Allah, other than whom there is no deity, the Sovereign, the Pure, the Perfection, the Grantor of security, the Overseer, the Exalted in Might, the Compeller, the Superior. Exalted is Allah above whatever they associate with Him. He is Allah, the Creator, the Inventor, the Fashioner; to Him belong the best names. Whatever is in the heavens and earth is exalting Him, and He is the Exalted in Might, the Wise.''',
    sourceReference: r'''Qur'an, Surah al-Hashr 22-24''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''quran_jinn_3_7''',
    category: AdhkarCategory.quranicDuas,
    titleAr: r'''آيات من سورة الجن''',
    titleEn: r'''Verses from Surah al-Jinn''',
    arabicText: r'''وَأَنَّهُۥ تَعَٰلَىٰ جَدُّ رَبِّنَا مَا ٱتَّخَذَ صَٰحِبَةً وَلَا وَلَدًا ﴿٣﴾ وَأَنَّهُۥ كَانَ يَقُولُ سَفِيهُنَا عَلَى ٱللَّهِ شَطَطًا ﴿٤﴾ وَأَنَّا ظَنَنَّآ أَن لَّن تَقُولَ ٱلْإِنسُ وَٱلْجِنُّ عَلَى ٱللَّهِ كَذِبًا ﴿٥﴾ وَأَنَّهُۥ كَانَ رِجَالٌ مِّنَ ٱلْإِنسِ يَعُوذُونَ بِرِجَالٍ مِّنَ ٱلْجِنِّ فَزَادُوهُمْ رَهَقًا ﴿٦﴾ وَأَنَّهُمْ ظَنُّوا۟ كَمَا ظَنَنتُمْ أَن لَّن يَبْعَثَ ٱللَّهُ أَحَدًا ﴿٧﴾''',
    transliteration: r'''Wa annahu ta'ala jaddu rabbina ma-ttakhadha sahibataw-wa la walada. Wa annahu kana yaqulu safihuna 'alallahi shatata. Wa anna zananna al-lan taqula-l-insu wal-jinnu 'alallahi kadhiba. Wa annahu kana rijalum-minal-insi ya'udhuna birijalim-minal-jinni fazaduhum rahaqa. Wa annahum zannu kama zanantum al-lay-yab'athallahu ahada.''',
    translationEn: r'''And exalted is the nobleness of our Lord — He has not taken a wife or a son. And the foolish among us used to speak about Allah an excessive falsehood. And we had thought that mankind and the jinn would never speak a lie about Allah. And there were men from mankind who sought refuge in men from the jinn, so they only increased them in burden. And they had thought, as you had thought, that Allah would never send anyone as a messenger.''',
    sourceReference: r'''Qur'an, Surah al-Jinn 3-7''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''quran_baqarah_127''',
    category: AdhkarCategory.quranicDuas,
    titleAr: r'''دعاء ربنا تقبل منا''',
    titleEn: r'''"Our Lord, Accept This from Us"''',
    arabicText: r'''رَبَّنَا تَقَبَّلْ مِنَّآ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلْعَلِيمُ''',
    transliteration: r'''Rabbana taqabbal minna, innaka anta-s-Sami'u-l-'Alim.''',
    translationEn: r'''Our Lord, accept this from us. Indeed, You are the Hearing, the Knowing.''',
    sourceReference: r'''Qur'an, Surah al-Baqarah 127''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
