    titleAr: r'''دعاء وتب علينا''',
    titleEn: r'''"And Accept Our Repentance"''',
    arabicText: r'''وَتُبْ عَلَيْنَآ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ''',
