  AdhkarEntry(
    id: r'''quran_aal_imran_8_9''',
    category: AdhkarCategory.quranicDuas,
    titleAr: r'''دعاء ربنا لا تزغ قلوبنا''',
    titleEn: r'''"Our Lord, Let Not Our Hearts Deviate"''',
    arabicText: r'''رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً إِنَّكَ أَنتَ ٱلْوَهَّابُ ﴿٨﴾ رَبَّنَآ إِنَّكَ جَامِعُ ٱلنَّاسِ لِيَوْمٍ لَّا رَيْبَ فِيهِ إِنَّ ٱللَّهَ لَا يُخْلِفُ ٱلْمِيعَادَ''',
    transliteration: r'''Rabbana la tuzigh qulubana ba'da idh hadaytana wa hab lana mil-ladunka rahmah, innaka anta-l-Wahhab. Rabbana innaka jami'un-nasi liyawmil-la rayba fih, innallaha la yukhliful-mi'ad.''',
    translationEn: r'''Our Lord, let not our hearts deviate after You have guided us, and grant us from Yourself mercy. Indeed, You are the Bestower. Our Lord, indeed You are the Gatherer of the people for a Day about which there is no doubt. Indeed, Allah does not fail in His promise.''',
    sourceReference: r'''Qur'an, Surah Aal 'Imran 8-9''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
