  ),
  AdhkarEntry(
    id: r'''quran_aal_imran_189_194''',
    category: AdhkarCategory.quranicDuas,
    titleAr: r'''دعاء ربنا ما خلقت هذا باطلا''',
    titleEn: r'''"Our Lord, You Did Not Create This Without Purpose"''',
    arabicText: r'''وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ ﴿١٨٩﴾ إِنَّ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ لَءَايَٰتٍ لِّأُو۟لِى ٱلْأَلْبَٰبِ ﴿١٩٠﴾ ٱلَّذِينَ يَذْكُرُونَ ٱللَّهَ قِيَٰمًا وَقُعُودًا وَعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ رَبَّنَا مَا خَلَقْتَ هَٰذَا بَٰطِلًا سُبْحَٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ ﴿١٩١﴾ رَبَّنَآ إِنَّكَ مَن تُدْخِلِ ٱلنَّارَ فَقَدْ أَخْزَيْتَهُۥ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍ ﴿١٩٢﴾ رَّبَّنَآ إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِى لِلْإِيمَٰنِ أَنْ ءَامِنُوا۟ بِرَبِّكُمْ فَـَٔامَنَّا رَبَّنَا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلْأَبْرَارِ ﴿١٩٣﴾ رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ ٱلْقِيَٰمَةِ إِنَّكَ لَا تُخْلِفُ ٱلْمِيعَادَ ﴿١٩٤﴾''',
    transliteration: r'''Wa lillahi mulkus-samawati wal-ard, wallahu 'ala kulli shay'in qadir. Inna fi khalqis-samawati wal-ardi wakhtilafil-layli wan-nahari la-ayatil-li'ulil-albab. Alladhina yadhkurunallaha qiyamaw-wa qu'udaw-wa 'ala junubihim wa yatafakkaruna fi khalqis-samawati wal-ard, rabbana ma khalaqta hadha batila, subhanaka faqina 'adhaban-nar. Rabbana innaka man tudkhilin-nara faqad akhzaytah, wa ma liz-zalimina min ansar. Rabbana innana sami'na munadiyaw-yunadi lil-imani an aminu birabbikum fa-amanna, rabbana faghfir lana dhunubana wa kaffir 'anna sayyi'atina wa tawaffana ma'al-abrar. Rabbana wa atina ma wa'adtana 'ala rusulika wa la tukhzina yawmal-qiyamah, innaka la tukhliful-mi'ad.''',
    translationEn: r'''And to Allah belongs the dominion of the heavens and the earth, and Allah is over all things competent. Indeed, in the creation of the heavens and the earth and the alternation of the night and the day are signs for those of understanding — who remember Allah while standing or sitting or lying on their sides and give thought to the creation of the heavens and the earth, "Our Lord, You did not create this aimlessly; exalted are You, so protect us from the punishment of the Fire. Our Lord, indeed whoever You admit to the Fire — You have disgraced him, and for the wrongdoers there are no helpers. Our Lord, indeed we have heard a caller calling to faith, 'Believe in your Lord,' and we have believed. Our Lord, so forgive us our sins and remove from us our misdeeds and cause us to die with the righteous. Our Lord, grant us what You promised us through Your messengers and do not disgrace us on the Day of Resurrection. Indeed, You do not fail in Your promise."''',
    sourceReference: r'''Qur'an, Surah Aal 'Imran 189-194''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
