  AdhkarEntry(
    id: r'''quran_hud_47''',
    category: AdhkarCategory.quranicDuas,
    titleAr: r'''دعاء رب إني أعوذ بك''',
    titleEn: r'''"My Lord, I Seek Refuge in You"''',
    arabicText: r'''رَبِّ إِنِّىٓ أَعُوذُ بِكَ أَنْ أَسْـَٔلَكَ مَا لَيْسَ لِى بِهِۦ عِلْمٌ وَإِلَّا تَغْفِرْ لِى وَتَرْحَمْنِىٓ أَكُن مِّنَ ٱلْخَٰسِرِينَ''',
    transliteration: r'''Rabbi inni a'udhu bika an as'alaka ma laysa li bihi 'ilm, wa illa taghfir li wa tarhamni akun minal-khasirin.''',
    translationEn: r'''My Lord, I seek refuge in You from asking that of which I have no knowledge. And unless You forgive me and have mercy upon me, I will be among the losers.''',
    sourceReference: r'''Qur'an, Surah Hud 47''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
