  AdhkarEntry(
    id: r'''quran_naml_19''',
    category: AdhkarCategory.quranicDuas,
    titleAr: r'''دعاء رب أوزعني أن أشكر نعمتك''',
    titleEn: r'''"My Lord, Enable Me to Be Grateful for Your Favor"''',
    arabicText: r'''رَبِّ أَوْزِعْنِىٓ أَنْ أَشْكُرَ نِعْمَتَكَ ٱلَّتِىٓ أَنْعَمْتَ عَلَىَّ وَعَلَىٰ وَٰلِدَىَّ وَأَنْ أَعْمَلَ صَٰلِحًا تَرْضَىٰهُ وَأَدْخِلْنِى بِرَحْمَتِكَ فِى عِبَادِكَ ٱلصَّٰلِحِينَ''',
    transliteration: r'''Rabbi awzi'ni an ashkura ni'mataka-llati an'amta 'alayya wa 'ala walidayya wa an a'mala salihan tardahu wa adkhilni birahmatika fi 'ibadika-s-salihin.''',
    translationEn: r'''My Lord, enable me to be grateful for Your favor which You have bestowed upon me and upon my parents, and to do righteousness of which You approve, and admit me by Your mercy into the ranks of Your righteous servants.''',
    sourceReference: r'''Qur'an, Surah an-Naml 19''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
