    transliteration: r'''Rabbana wasi'ta kulla shay'ir-rahmataw-wa 'ilman faghfir lilladhina tabu wattaba'u sabilaka wa qihim 'adhabal-jahim.''',
    translationEn: r'''Our Lord, You have encompassed all things in mercy and knowledge, so forgive those who repent and follow Your way and protect them from the punishment of the Blazing Fire.''',
