  AdhkarEntry(
    id: r'''quran_nuh_28''',
    category: AdhkarCategory.quranicDuas,
    titleAr: r'''دعاء رب اغفر لي ولوالدي''',
    titleEn: r'''"My Lord, Forgive Me and My Parents"''',
    arabicText: r'''رَبِّ ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِمَن دَخَلَ بَيْتِىَ مُؤْمِنًا وَلِلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ وَلَا تَزِدِ ٱلظَّٰلِمِينَ إِلَّا تَبَارًا''',
    transliteration: r'''Rabbi-ghfir li wa liwalidayya wa liman dakhala baytiya mu'minaw-wa lil-mu'minina wal-mu'minati wa la tazidiz-zalimina illa tabara.''',
    translationEn: r'''My Lord, forgive me and my parents and whoever enters my house a believer, and the believing men and believing women. And do not increase the wrongdoers except in destruction.''',
    sourceReference: r'''Qur'an, Surah Nuh 28''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''prophetic_taawwudh_hamzihi_nafkhihi_nafthihi''',
    category: AdhkarCategory.protection,
    titleAr: r'''التعوذ من همز الشيطان ونفخه ونفثه''',
    titleEn: r'''Seeking Refuge from Satan's Prompting, Pride, and Poetry''',
    arabicText: r'''أَعُوذُ بِاللَّهِ السَّمِيعِ العَلِيمِ مِنَ الشَّيْطَانِ الرَّجِيمِ مِنْ هَمْزِهِ وَنَفْخِهِ وَنَفْثِهِ ( ثلاثًا ) .''',
    transliteration: r'''A'udhu billahi-s-Sami'i-l-'Alimi mina-sh-shaytani-r-rajimi min hamzihi wa nafkhihi wa nafthih. (Thalathan)''',
    translationEn: r'''I seek refuge in Allah, the All-Hearing, the All-Knowing, from Satan the accursed — from his prompting to madness, his arrogance, and his evil incitement. (Three times)''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 3,
    repetitionNote: r'''ثلاثًا (three times)''',
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''quran_al_ikhlas''',
    category: AdhkarCategory.quranicDuas,
    titleAr: r'''سورة الإخلاص''',
    titleEn: r'''Surah al-Ikhlas (The Sincerity)''',
    arabicText: r'''بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ
قُلْ هُوَ ٱللَّهُ أَحَدٌ ﴿١﴾ ٱللَّهُ ٱلصَّمَدُ ﴿٢﴾ لَمْ يَلِدْ وَلَمْ يُولَدْ ﴿٣﴾ وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ ﴿٤﴾''',
    transliteration: r'''Bismillahi-r-Rahmani-r-Rahim. Qul huwallahu ahad. Allahus-samad. Lam yalid wa lam yulad. Wa lam yakul-lahu kufuwan ahad.''',
    translationEn: r'''In the name of Allah, the Entirely Merciful, the Especially Merciful. Say, "He is Allah, who is One, Allah, the Eternal Refuge. He neither begets nor is born, nor is there to Him any equivalent."''',
    sourceReference: r'''Qur'an, Surah al-Ikhlas 1-4''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''quran_al_falaq''',
    category: AdhkarCategory.quranicDuas,
    titleAr: r'''سورة الفلق''',
    titleEn: r'''Surah al-Falaq (The Daybreak)''',
    arabicText: r'''بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ
قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ ﴿١﴾ مِن شَرِّ مَا خَلَقَ ﴿٢﴾ وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ ﴿٣﴾ وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِى ٱلْعُقَدِ ﴿٤﴾ وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ ﴿٥﴾''',
    transliteration: r'''Bismillahi-r-Rahmani-r-Rahim. Qul a'udhu birabbil-falaq. Min sharri ma khalaq. Wa min sharri ghasiqin idha waqab. Wa min sharrin-naffathati fil-'uqad. Wa min sharri hasidin idha hasad.''',
    translationEn: r'''In the name of Allah, the Entirely Merciful, the Especially Merciful. Say, "I seek refuge in the Lord of daybreak, from the evil of that which He created, and from the evil of darkness when it settles, and from the evil of the blowers in knots, and from the evil of an envier when he envies."''',
    sourceReference: r'''Qur'an, Surah al-Falaq 1-5''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''quran_an_nas''',
    category: AdhkarCategory.quranicDuas,
    titleAr: r'''سورة الناس''',
    titleEn: r'''Surah an-Nas (Mankind)''',
    arabicText: r'''بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ
قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ ﴿١﴾ مَلِكِ ٱلنَّاسِ ﴿٢﴾ إِلَٰهِ ٱلنَّاسِ ﴿٣﴾ مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ ﴿٤﴾ ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ ﴿٥﴾ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ ﴿٦﴾''',
    transliteration: r'''Bismillahi-r-Rahmani-r-Rahim. Qul a'udhu birabbin-nas. Malikin-nas. Ilahin-nas. Min sharril-waswasil-khannas. Alladhi yuwaswisu fi sudurin-nas. Minal-jinnati wan-nas.''',
    translationEn: r'''In the name of Allah, the Entirely Merciful, the Especially Merciful. Say, "I seek refuge in the Lord of mankind, the Sovereign of mankind, the God of mankind, from the evil of the retreating whisperer — who whispers into the breasts of mankind — from among the jinn and mankind."''',
    sourceReference: r'''Qur'an, Surah an-Nas 1-6''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''prophetic_bismillahi_alladhi_la_yadurru''',
    category: AdhkarCategory.protection,
    titleAr: r'''بسم الله الذي لا يضر مع اسمه شيء''',
    titleEn: r'''"In the Name of Allah With Whose Name Nothing Can Harm"''',
    arabicText: r'''بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ
بِسْمِ اللَّهِ الَّذِي لا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الأَرْضِ وَلا فِي السَّمَاءِ وَهُوَ السَّمِيعُ العَلِيمُ ( ثلاثًا ) .''',
    transliteration: r'''Bismillahi-r-Rahmani-r-Rahim. Bismillahi-lladhi la yadurru ma'a-smihi shay'un fil-ardi wa la fis-sama'i wa huwas-Sami'ul-'Alim. (Thalathan)''',
    translationEn: r'''In the name of Allah, the Entirely Merciful, the Especially Merciful. In the name of Allah, with whose name nothing on earth or in heaven can cause harm, and He is the All-Hearing, the All-Knowing. (Three times)''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 3,
    repetitionNote: r'''ثلاثًا (three times)''',
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''prophetic_bismillahi_dhi_shan''',
    category: AdhkarCategory.protection,
    titleAr: r'''بسم الله ذي الشأن''',
    titleEn: r'''"In the Name of Allah, Possessor of Majesty"''',
    arabicText: r'''بِسْمِ اللَّهِ ذِي الشَّأنِ ، عَظِيمِ السُّلْطَانِ ، شَدِيدِ البُرْهَانِ ، قَوِيِّ الأَرْكَانِ ، مَا شَاءَ اللَّهُ كَانَ . أَعُوذُ بِاللَّهِ مِن كُلِّ شَيْطَانٍ ، إِنْسٍ وَجَانٍّ ( ثلاثًا ) .''',
    transliteration: r'''Bismillahi dhish-sha'n, 'azimis-sultan, shadidil-burhan, qawiyyil-arkan. Ma sha'allahu kan. A'udhu billahi min kulli shaytanin, insiw-wa jann. (Thalathan)''',
    translationEn: r'''In the name of Allah, Possessor of majesty, of tremendous authority, of mighty proof, of powerful foundations. Whatever Allah wills comes to be. I seek refuge in Allah from every devil, human and jinn. (Three times)''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 3,
    repetitionNote: r'''ثلاثًا (three times)''',
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''prophetic_audhu_bikalimatillah_al_tammat''',
    category: AdhkarCategory.protection,
    titleAr: r'''أعوذ بكلمات الله التامات''',
    titleEn: r'''"I Seek Refuge in the Perfect Words of Allah"''',
    arabicText: r'''أَعوذُ بكلماتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ ما خَلَقَ ( ثلاثًا ) .''',
    transliteration: r'''A'udhu bikalimatillahi-t-tammati min sharri ma khalaq. (Thalathan)''',
    translationEn: r'''I seek refuge in the perfect words of Allah from the evil of what He has created. (Three times)''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 3,
    repetitionNote: r'''ثلاثًا (three times)''',
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''prophetic_audhu_biwajhillah_al_azim''',
    category: AdhkarCategory.protection,
    titleAr: r'''أعوذ بوجه الله العظيم''',
    titleEn: r'''"I Seek Refuge in the Mighty Face of Allah"''',
    arabicText: r'''أَعوذُ بوجهِ اللَّه العظيمِ الذي ليس شيءٌ أعظمَ منه، وبكلماتِ اللَّه التَّامَّاتِ التي لا يُجاوِزُهُنَّ بَرٌّ ولا فاجِرٌ : من شَرِّ ما خَلَقَ ، وذَرَأَ وبَرَأَ ، ومن شَرِّ ما يَنزِلُ من السَّماءِ وما يَعْرُجُ فيها ، ومن شَرِّ ما يَلِجُ في الأرضِ وما يخرجُ منها ، ومن شَرِّ طوارقِ اللَّيلِ والنَّهارِ إلَّا طارقًا يَطْرُقُ بخيرٍ يا رَحْمَٰنُ .''',
    transliteration: r'''A'udhu biwajhillahi-l-'azimi-lladhi laysa shay'un a'zama minh, wa bikalimatillahi-t-tammatillati la yujawizuhunna barrun wa la fajir, min sharri ma khalaqa, wa dhara'a wa bara'a, wa min sharri ma yanzilu minas-sama'i wa ma ya'ruju fiha, wa min sharri ma yaliju fil-ardi wa ma yakhruju minha, wa min sharri tawariqil-layli wan-nahari illa tariqay-yatruqu bikhayrin ya Rahman.''',
    translationEn: r'''I seek refuge in the Mighty Face of Allah, than which there is nothing more mighty, and in the perfect words of Allah which neither the righteous nor the sinful can transgress, from the evil of what He has created, spread forth, and brought into being, and from the evil of what descends from the sky and what ascends into it, and from the evil of what enters into the earth and what emerges from it, and from the evils of the visitations of night and day, except a visitor who comes with good, O Most Merciful.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''prophetic_asbahna_wa_asbaha_al_mulku_lillahi_al_wahid''',
    category: AdhkarCategory.generalDhikr,
    titleAr: r'''أصبحنا وأصبح الملك لله الواحد القهار''',
    titleEn: r'''"We Have Reached the Morning, and Dominion Belongs to Allah"''',
    arabicText: r'''أَصْبَحْنَا وَأَصْبَحَ المُلْكُ لِلَّهِ الوَاحِدِ القَهَّارِ ، والحَمْدُ لِلَّهِ لا إله إلَّا اللَّه وَحْدَهُ لا شَريكَ لَهُ ، لَهُ المُلْكُ وَلَهُ الحَمْدُ وَهُوَ عَلى كُلِّ شَيءٍ قَدِيرٌ .''',
    transliteration: r'''Asbahna wa asbahal-mulku lillahil-Wahidil-Qahhar, wal-hamdu lillah, la ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamdu wa huwa 'ala kulli shay'in qadir.''',
    translationEn: r'''We have reached the morning, and with it all dominion belongs to Allah, the One, the Subjugator. Praise be to Allah. There is no deity except Allah, alone, without partner. His is the dominion, and His is the praise, and He is over all things competent.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''prophetic_rabbi_asaluka_khayra_hadha_al_yawm''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''رب أسألك خير هذا اليوم''',
    titleEn: r'''"My Lord, I Ask You for the Good of This Day"''',
    arabicText: r'''رَبِّ أَسْأَلُكَ خَيْرَ هَذَا اليَوْمِ وخَيْرَ ما بَعْدَهُ ، وَأَعُوذُ بِكَ من شَرِّه وشَرِّ ما بَعْدَهُ .''',
    transliteration: r'''Rabbi as'aluka khayra hadhal-yawmi wa khayra ma ba'dahu, wa a'udhu bika min sharrihi wa sharri ma ba'dah.''',
    translationEn: r'''My Lord, I ask You for the good of this day and the good of what follows it, and I seek refuge in You from its evil and the evil of what follows it.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
