    titleAr: r'''اللهم إني أسألك خير هذا اليوم فتحه ونصره''',
    titleEn: r'''"O Allah, I Ask You for This Day's Opening, Help, and Light"''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَسأَلُكَ خَيْرَ هَذا اليومِ : فَتْحَهُ وَنَصْرَهُ ، وَنُورَهُ وَبَرَكَتَهُ وَهُدَاهُ ، وَأَعُوذُ بِكَ من شَرِّ ما بَعدَهُ .''',
    transliteration: r'''Allahumma inni as'aluka khayra hadhal-yawm: fathahu wa nasrahu, wa nurahu wa barakatahu wa hudahu, wa a'udhu bika min sharri ma ba'dah.''',
    translationEn: r'''O Allah, I ask You for the good of this day: its opening to good, its help, its light, its blessing, and its guidance, and I seek refuge in You from the evil of what follows it.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''prophetic_allahumma_bika_asbahna_wa_bika_amsayna''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم بك أصبحنا وبك أمسينا''',
    titleEn: r'''"O Allah, By You We Reach Morning and Evening"''',
    arabicText: r'''اللَّهُمَّ بِكَ أَصْبَحْنَا وَبِكَ أَمْسَيْنَا ، وَبِكَ نَحْيَا وَبِكَ نَمُوتُ ، وَإِلَيْكَ النُّشُورُ .''',
    transliteration: r'''Allahumma bika asbahna wa bika amsayna, wa bika nahya wa bika namutu, wa ilaykan-nushur.''',
    translationEn: r'''O Allah, by You we reach the morning and by You we reach the evening; by You we live and by You we die, and to You is the resurrection.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
