  AdhkarEntry(
    id: r'''prophetic_asbahna_wa_asbaha_al_mulku_lillahi_la_sharika''',
    category: AdhkarCategory.generalDhikr,
    titleAr: r'''أصبحنا وأصبح الملك لله لا شريك له''',
    titleEn: r'''"We Have Reached the Morning, Dominion Belongs to Allah Alone"''',
    arabicText: r'''أَصْبَحْنَا وَأَصْبَحَ المُلْكُ لِلَّهِ ، وَالحَمْدُ لِلَّهِ لا شَرِيكَ لَهُ ، لا إِلٰه إِلَّا هُوَ إِلَيهِ النُّشُورُ .''',
    transliteration: r'''Asbahna wa asbahal-mulku lillah, wal-hamdu lillahi la sharika lah, la ilaha illa huwa ilayhin-nushur.''',
    translationEn: r'''We have reached the morning, and with it all dominion belongs to Allah, and praise be to Allah, who has no partner. There is no deity except Him, and to Him is the resurrection.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
