  AdhkarEntry(
    id: r'''prophetic_allahumma_fatir_as_samawati_wal_ard''',
    category: AdhkarCategory.protection,
    titleAr: r'''اللهم فاطر السماوات والأرض''',
    titleEn: r'''"O Allah, Originator of the Heavens and the Earth"''',
    arabicText: r'''اللَّهُمَّ فَاطِرَ السَّمَاوَاتِ وَالأَرضِ ، عَالِمَ الغَيبِ وَالشَّهَادَةِ ، رَبَّ كُلِّ شَيءٍ وَمَلِيكَهُ : أَشْهَدُ أَنْ لا إِلٰهَ إِلَّا أَنْتَ . أَعُوذُ بِكَ من شَرِّ نَفْسِي ، ومِن شَرِّ الشَّيْطَانِ وشِرْكِهِ ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءًا أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ .''',
    transliteration: r'''Allahumma Fatiras-samawati wal-ard, 'Alimal-ghaybi wash-shahadah, Rabba kulli shay'iw-wa malikah, ashhadu al-la ilaha illa ant. A'udhu bika min sharri nafsi, wa min sharrish-shaytani wa shirkih, wa an aqtarifa 'ala nafsi su'an aw ajurrahu ila muslim.''',
    translationEn: r'''O Allah, Originator of the heavens and the earth, Knower of the unseen and the seen, Lord and Sovereign of all things — I bear witness that there is no deity except You. I seek refuge in You from the evil of my own soul, and from the evil of Satan and his association of partners with You, and from bringing evil upon myself or leading it toward any Muslim.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''prophetic_allahumma_inni_asbahtu_ushhiduka''',
    category: AdhkarCategory.generalDhikr,
    titleAr: r'''اللهم إني أصبحت أشهدك''',
    titleEn: r'''"O Allah, I Have Reached the Morning Calling You to Witness"''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَصْبَحْتُ أُشْهِدُكَ وَأُشْهِدُ حَمَلَةَ عَرْشِكَ ، وَمَلَائِكَتَكَ ، وَجَمِيعَ خَلْقِكَ ، أَنَّكَ أَنتَ اللَّه لا إله إلَّا أنتَ وحدَكَ لا شريكَ لَكَ ، وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ . ( ثلاثًا ) .''',
    transliteration: r'''Allahumma inni asbahtu ushhiduka wa ushhidu hamalata 'arshik, wa mala'ikatak, wa jami'a khalqik, annaka anta Allahu la ilaha illa anta wahdaka la sharika lak, wa anna Muhammadan 'abduka wa Rasuluk. (Thalathan)''',
    translationEn: r'''O Allah, I have reached the morning calling You to witness, and calling to witness the bearers of Your Throne, Your angels, and all of Your creation, that You are Allah, there is no deity except You, alone, without partner, and that Muhammad is Your servant and Your Messenger. (Three times)''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 3,
    repetitionNote: r'''ثلاثًا (three times)''',
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''prophetic_allahumma_asaluka_al_afwa_wal_afiyah''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم إني أسألك العفو والعافية''',
    titleEn: r'''"O Allah, I Ask You for Pardon and Well-Being"''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَسْأَلُكَ العَفْوَ وَالعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي ، وَمَالِي .''',
    transliteration: r'''Allahumma inni as'alukal-'afwa wal-'afiyata fi dini wa dunyaya wa ahli, wa mali.''',
    translationEn: r'''O Allah, I ask You for pardon and well-being in my religion, my worldly life, my family, and my wealth.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
