  AdhkarEntry(
    id: r'''prophetic_allahumma_ustur_awrati''',
    category: AdhkarCategory.protection,
    titleAr: r'''اللهم استر عوراتي وآمن روعاتي''',
    titleEn: r'''"O Allah, Conceal My Faults and Calm My Fears"''',
    arabicText: r'''اللَّهُمَّ اسْتُرْ عَوْرَاتِي ، وَآمِنْ رَوْعَاتِي ، اللَّهُمَّ احْفَظْنِي مِن بَينِ يَدَيَّ وَمِنْ خَلْفِي ، وَعَنْ يَمِينِي وَعَنْ شِمَالِي ، وَمِنْ فَوْقِي ، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِن تَحْتِي .''',
    transliteration: r'''Allahumma-stur 'awrati, wa amin raw'ati. Allahumma-hfazni mim bayni yadayya wa min khalfi, wa 'an yamini wa 'an shimali, wa min fawqi, wa a'udhu bi'azamatika an ughtala min tahti.''',
    translationEn: r'''O Allah, conceal my faults and calm my fears. O Allah, guard me from before me and from behind me, and from my right and from my left, and from above me, and I seek refuge in Your greatness from being taken unawares from beneath me.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''prophetic_la_ilaha_illallah_wahdahu_lahul_mulk''',
    category: AdhkarCategory.generalDhikr,
    titleAr: r'''لا إله إلا الله وحده لا شريك له''',
    titleEn: r'''"There Is No Deity Except Allah, Alone"''',
    arabicText: r'''لا إِلٰهَ إِلَّا اللَّهُ وَحْدَهُ لا شَرِيكَ لَهُ ، لَهُ المُلْكُ وَلَهُ الحَمْدُ وَهُوَ عَلى كُلِّ شَيءٍ قَدِيرٌ .''',
    transliteration: r'''La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamdu wa huwa 'ala kulli shay'in qadir.''',
    translationEn: r'''There is no deity except Allah, alone, without partner. His is the dominion, and His is the praise, and He is over all things competent.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''prophetic_raditu_billahi_rabban''',
    category: AdhkarCategory.generalDhikr,
    titleAr: r'''رضيت بالله ربا''',
    titleEn: r'''"I Am Pleased with Allah as Lord"''',
    arabicText: r'''رَضِيتُ بِاللَّه رَبًّا ، وَبِالإِسْلامِ دِينًا ، وَبِمُحَمَّدٍ ﷺ نَبِيًّا وَرَسُولًا .''',
    transliteration: r'''Raditu billahi rabban, wa bil-Islami dinan, wa bi-Muhammadin (sallallahu 'alayhi wa sallam) nabiyyaw-wa rasula.''',
    translationEn: r'''I am pleased with Allah as Lord, with Islam as religion, and with Muhammad (peace and blessings be upon him) as Prophet and Messenger.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
