  AdhkarEntry(
    id: r'''prophetic_allahumma_ma_asbaha_bi_min_nimah''',
    category: AdhkarCategory.generalDhikr,
    titleAr: r'''اللهم ما أصبح بي من نعمة''',
    titleEn: r'''"O Allah, Whatever Blessing Has Reached Me"''',
    arabicText: r'''اللَّهُمَّ مَا أَصْبَحَ بِي مِن نِعْمَةٍ ، أَوْ بِأَحَدٍ مِن خَلْقِكَ ، فَمِنْكَ وَحْدَكَ لا شَرِيكَ لَكَ ، فَلَكَ الحَمْدُ وَلَكَ الشُّكْرُ .''',
    transliteration: r'''Allahumma ma asbaha bi min ni'matin, aw bi-ahadin min khalqik, faminka wahdaka la sharika lak, falakal-hamdu wa lakash-shukr.''',
    translationEn: r'''O Allah, whatever blessing has reached me, or reached any of Your creation, is from You alone, without partner; so to You belongs all praise and to You belongs all thanks.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''prophetic_salawat_ibrahimiyyah''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''الصلاة الإبراهيمية''',
    titleEn: r'''The Ibrahimic Blessing upon the Prophet''',
    arabicText: r'''اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ ، وَعَلَى آلِ مُحَمَّدٍ ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ ، إِنَّكَ حَمِيدٌ مَجِيدٌ ، وَبَارِكْ عَلَى مُحَمَّدٍ ، وَعَلَى آلِ مُحَمَّدٍ ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ ، إِنَّكَ حَمِيدٌ مَجِيدٌ .''',
    transliteration: r'''Allahumma salli 'ala Muhammadin, wa 'ala ali Muhammad, kama sallayta 'ala Ibrahima wa 'ala ali Ibrahim, innaka Hamidum-Majid. Wa barik 'ala Muhammadin, wa 'ala ali Muhammad, kama barakta 'ala Ibrahima wa 'ala ali Ibrahim, innaka Hamidum-Majid.''',
    translationEn: r'''O Allah, send blessings upon Muhammad and upon the family of Muhammad, as You sent blessings upon Ibrahim and upon the family of Ibrahim; indeed, You are Praiseworthy, Glorious. And send favor upon Muhammad and upon the family of Muhammad, as You sent favor upon Ibrahim and upon the family of Ibrahim; indeed, You are Praiseworthy, Glorious.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''prophetic_allahumma_afini_fi_badani''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم عافني في بدني''',
    titleEn: r'''"O Allah, Grant Me Health in My Body"''',
    arabicText: r'''اللَّهُمَّ عَافِنِي فِي بَدَنِي ، اللَّهُمَّ عَافِنِي فِي سَمْعِي ، اللَّهُمَّ عَافِنِي فِي بَصَرِي . لا إِلٰهَ إِلَّا أَنْتَ . ( ثلاثًا ) .''',
    transliteration: r'''Allahumma 'afini fi badani, Allahumma 'afini fi sam'i, Allahumma 'afini fi basari, la ilaha illa ant. (Thalathan)''',
    translationEn: r'''O Allah, grant me health in my body. O Allah, grant me health in my hearing. O Allah, grant me health in my sight. There is no deity except You. (Three times)''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 3,
