  AdhkarEntry(
    id: r'''prophetic_subhanallahi_wa_bihamdihi_la_quwwata_illa_billah''',
    category: AdhkarCategory.generalDhikr,
    titleAr: r'''سبحان الله وبحمده لا قوة إلا بالله''',
    titleEn: r'''"Glory Be to Allah and Praise Him; There Is No Power Except by Allah"''',
    arabicText: r'''سُبْحَانَ اللَّه وَبِحَمْدِهِ ، لا قُوَّةَ إِلَّا بِاللَّه ، مَا شَاءَ اللَّهُ كَانَ ، وَمَا لَمْ يَشَأْ لَمْ يَكُنْ ، أَعْلَمُ أَنَّ اللَّهَ عَلَى كُلِّ شَيءٍ قَدِيرٌ ، وَأَنَّ اللَّهَ قَدْ أَحَاطَ بِكُلِّ شَيءٍ عِلْمًا .''',
    transliteration: r'''Subhanallahi wa bihamdih, la quwwata illa billah, ma sha'allahu kan, wa ma lam yasha' lam yakun, a'lamu annallaha 'ala kulli shay'in qadir, wa annallaha qad ahata bikulli shay'in 'ilma.''',
    translationEn: r'''Glory be to Allah and praise be to Him. There is no power except by Allah. Whatever Allah wills comes to be, and whatever He does not will does not come to be. I know that Allah is over all things competent, and that Allah has encompassed all things in knowledge.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
