    category: AdhkarCategory.generalDhikr,
    titleAr: r'''أصبحنا على فطرة الإسلام''',
    titleEn: r'''"We Have Reached the Morning upon the Nature of Islam"''',
    arabicText: r'''أَصْبَحْنَا عَلَى فِطْرَةِ الإِسْلَامِ ، وَكَلِمَةِ الإِخْلَاصِ ، وَدِينِ نَبِيِّنَا مُحَمَّدٍ ﷺ ، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ حَنِيفًا مُسْلِمًا وَمَا كَانَ مِنَ المُشْرِكِينَ .''',
    transliteration: r'''Asbahna 'ala fitratil-Islam, wa kalimatil-ikhlas, wa dini nabiyyina Muhammadin (sallallahu 'alayhi wa sallam), wa 'ala millati abina Ibrahima hanifam-musliman wa ma kana minal-mushrikin.''',
    translationEn: r'''We have reached the morning upon the natural disposition of Islam, the word of sincerity, the religion of our Prophet Muhammad (peace and blessings be upon him), and the way of our father Ibrahim — a person of pure faith and submission, and he was not among those who associate partners with Allah.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''prophetic_ya_hayyu_ya_qayyum''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''يا حي يا قيوم برحمتك أستغيث''',
    titleEn: r'''"O Ever-Living, O Sustainer, By Your Mercy I Seek Relief"''',
    arabicText: r'''يَا حَيُّ يَا قَيُّومُ يَا بَدِيعَ السَّمَاوَاتِ وَالأَرْضِ ، وَيَا ذَا الجَلَالِ وَالإِكْرَامِ ، لا إِلٰهَ إِلَّا أَنْتَ ، بِرَحْمَتِكَ أَسْتَغِيثُ ، أَصْلِحْ لِي شَأنِي كُلَّهُ ، وَلا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ .''',
    transliteration: r'''Ya Hayyu ya Qayyumu ya Badi'as-samawati wal-ard, wa ya Dhal-Jalali wal-Ikram, la ilaha illa ant, birahmatika astaghith, aslih li sha'ni kullah, wa la takilni ila nafsi tarfata 'ayn.''',
    translationEn: r'''O Ever-Living, O Sustainer, O Originator of the heavens and the earth without precedent, O Possessor of majesty and honor, there is no deity except You. By Your mercy I seek relief; set right all of my affairs, and do not entrust me to myself even for the blink of an eye.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''prophetic_du_a_sayyid_al_istighfar''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''سيد الاستغفار''',
    titleEn: r'''The Master Supplication for Forgiveness''',
    arabicText: r'''اللَّهُمَّ أَنْتَ رَبِّي لا إِلٰهَ إِلَّا أَنْتَ ، خَلَقْتَنِي وَأَنَا عَبْدُكَ ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ ، أَعُوذُ بِكَ مِن شَرِّ مَا صَنَعْتُ ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ ، وَأَبُوءُ بِذَنْبِي ، فَاغْفِرْ لِي ، فَإِنَّهُ لا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ .''',
    transliteration: r'''Allahumma anta Rabbi la ilaha illa ant, khalaqtani wa ana 'abduk, wa ana 'ala 'ahdika wa wa'dika mastata't, a'udhu bika min sharri ma sana't, abu'u laka bini'matika 'alayya, wa abu'u bidhanbi, faghfir li, fa-innahu la yaghfirudh-dhunuba illa ant.''',
    translationEn: r'''O Allah, You are my Lord; there is no deity except You. You created me and I am Your servant, and I remain true to Your covenant and promise as much as I am able. I seek refuge in You from the evil of what I have done. I acknowledge Your favor upon me, and I acknowledge my sin, so forgive me — for none forgives sins except You.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''dua_noor_wajhika''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''أسأل بنور وجهك''',
    titleEn: r'''By the Light of Your Face''',
    arabicText: r'''وَالدِّينُ مَا شَرَعْتَ ، وَالخَلْقُ خَلْقُكَ وَالعَبْدُ عَبْدُكَ ، وَأَنتَ اللَّهُ الرَّؤُوفُ الرَّحِيمُ ، أَسْأَلُكَ بِنُورِ وَجْهِكَ الَّذِي أَشْرَقَتْ لَهُ السَّمَاوَاتُ وَالأَرْضُ ، وَبِكُلِّ حَقٍّ هُوَ لَكَ ، وَبِحَقِّ السَّائِلِينَ عَلَيكَ : أَنْ تَقْبَلَنِي فِي هذِهِ الغَدَاةِ ، وَأَنْ تُجِيرَنِي مِنَ النَّارِ بِقُدرَتِكَ .''',
    transliteration: r'''Wa-d-dīnu mā shara'ta, wa-l-khalqu khalquka wa-l-'abdu 'abduka, wa anta Allāhu ar-Ra'ūfu ar-Raḥīm. As'aluka bi-nūri wajhika alladhī ashraqat lahu as-samāwātu wa-l-arḍ, wa bi-kulli ḥaqqin huwa laka, wa bi-ḥaqqi as-sā'ilīna 'alayka: an taqbalanī fī hādhihi al-ghadāh, wa an tujīranī mina an-nāri bi-qudratika.''',
    translationEn: r'''Religion is what You have legislated, creation is Your creation, and the servant is Your servant, and You are Allah, the Most Kind, the Most Merciful. I ask You by the light of Your Face for which the heavens and the earth were illuminated, and by every right that is due to You, and by the right of those who ask of You: that You accept me this morning, and that You save me from the Fire by Your power.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''hasbiya_allah_tawbah_129''',
    category: AdhkarCategory.quranicDuas,
    titleAr: r'''حسبي الله لا إله إلا هو''',
    titleEn: r'''Sufficiency of Allah (At-Tawbah 129)''',
    arabicText: r'''﴿ حَسْبِيَ اللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ۖ عَلَيْهِ تَوَكَّلْتُ ۖ وَهُوَ رَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ ﴾ [التوبة: ١٢٩]''',
    transliteration: r'''Ḥasbiya Allāhu lā ilāha illā huwa, 'alayhi tawakkaltu wa huwa Rabbu al-'Arshi al-'Aẓīm.''',
    translationEn: r'''Allah is sufficient for me; there is no deity except Him. On Him I have relied, and He is the Lord of the Great Throne.''',
    sourceReference: r'''Qur'an, Surah At-Tawbah 129''',
    repetitionCount: 7,
    repetitionNote: r'''سبع مرات (seven times)''',
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''tahlil_la_ilaha_illallah''',
    category: AdhkarCategory.generalDhikr,
    titleAr: r'''لا إله إلا الله وحده''',
    titleEn: r'''Declaration of Allah's Oneness''',
    arabicText: r'''لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ ، لَهُ المُلْكُ وَلَهُ الحَمْدُ ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ .''',
    transliteration: r'''Lā ilāha illā Allāhu waḥdahu lā sharīka lah, lahu al-mulku wa lahu al-ḥamd, wa huwa 'alā kulli shay'in qadīr.''',
    translationEn: r'''There is no god but Allah, alone, without partner. His is the dominion and His is all praise, and He is omnipotent over all things.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''salawat_ibrahimiyyah_1''',
    category: AdhkarCategory.generalDhikr,
    titleAr: r'''الصلاة الإبراهيمية''',
    titleEn: r'''The Ibrahimic Blessing (Salawat)''',
    arabicText: r'''اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَآلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ . وَبَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَآلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ .''',
    transliteration: r'''Allāhumma ṣalli 'alā Muḥammadin wa 'alā āli Muḥammad, kamā ṣallayta 'alā Ibrāhīma wa āli Ibrāhīm, innaka Ḥamīdun Majīd. Wa bārik 'alā Muḥammadin wa 'alā āli Muḥammad, kamā bārakta 'alā Ibrāhīma wa āli Ibrāhīm, innaka Ḥamīdun Majīd.''',
    translationEn: r'''O Allah, send blessings upon Muhammad and upon the family of Muhammad, as You sent blessings upon Ibrahim and the family of Ibrahim; indeed You are Praiseworthy, Glorious. And bless Muhammad and the family of Muhammad, as You blessed Ibrahim and the family of Ibrahim; indeed You are Praiseworthy, Glorious.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''istiadhah_hamm_hazan''',
    category: AdhkarCategory.protection,
    titleAr: r'''التعوذ من الهم والحزن''',
    titleEn: r'''Refuge from Anxiety and Grief''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الهَمِّ وَالحَزَنِ ، وَأَعُوذُ بِكَ مِنَ العَجْزِ وَالكَسَلِ [ وَمِنَ البُخْلِ وَالجُبْنِ ] ، وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ .''',
    transliteration: r'''Allāhumma innī a'ūdhu bika mina al-hammi wa-l-ḥazan, wa a'ūdhu bika mina al-'ajzi wa-l-kasal [wa mina al-bukhli wa-l-jubn], wa a'ūdhu bika min ghalabati ad-dayni wa qahri ar-rijāl.''',
    translationEn: r'''O Allah, I seek refuge in You from anxiety and grief, and I seek refuge in You from incapacity and laziness [and from miserliness and cowardice], and I seek refuge in You from being overcome by debt and overpowered by men.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''asbahna_wa_asbaha_almulk''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''أصبحنا وأصبح الملك لله''',
    titleEn: r'''Morning Dhikr of Dominion''',
    arabicText: r'''أَصْبَحْنَا وَأَصْبَحَ المُلْكُ لِلَّهِ ، وَالكِبْرِيَاءُ وَالعَظَمَةُ وَالخَلْقُ وَالأَمْرُ وَاللَّيْلُ وَالنَّهَارُ وَمَا يَضْحَى فِيهِمَا لِلَّهِ وَحْدَهُ .''',
    transliteration: r'''Aṣbaḥnā wa aṣbaḥa al-mulku lillāh, wa-l-kibriyā'u wa-l-'aẓamatu wa-l-khalqu wa-l-amru wa-l-laylu wa-n-nahāru wa mā yaḍḥā fīhimā lillāhi waḥdah.''',
    translationEn: r'''We have entered the morning, and the dominion has entered the morning belonging to Allah, and majesty, greatness, creation, and command, and the night and the day, and whatever appears within them, belong to Allah alone.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''dua_awwal_hadha_alyawm''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء أول اليوم''',
    titleEn: r'''Dua for the Start of the Day''',
    arabicText: r'''اللهم اجْعَلْ أَوَّلَ هَذَا اليَوْمِ صَلَاحًا ، وَأَوْسَطَهُ فَلَاحًا ، وَآخِرَهُ نَجَاحًا . أَسْأَلُكَ خَيْرَ الدُّنْيَا وَالآخِرَةِ يَا أَرْحَمَ الرَّاحِمِينَ .''',
    transliteration: r'''Allāhumma ij'al awwala hādhā al-yawmi ṣalāḥan, wa awsaṭahu falāḥan, wa ākhirahu najāḥan. As'aluka khayra ad-dunyā wa-l-ākhirati yā Arḥama ar-Rāḥimīn.''',
    translationEn: r'''O Allah, make the beginning of this day righteousness, its middle success, and its end triumph. I ask You for the good of this world and the Hereafter, O Most Merciful of the merciful.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''labbayka_allahumma_labbayk''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''لبيك اللهم لبيك''',
    titleEn: r'''Here I Am at Your Service''',
    arabicText: r'''لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ وَسَعْدَيْكَ ، وَالخَيْرُ فِي يَدَيْكَ وَمِنْكَ وَإِلَيْكَ .''',
    transliteration: r'''Labbayka Allāhumma labbayka wa sa'dayk, wa-l-khayru fī yadayka wa minka wa ilayk.''',
    translationEn: r'''Here I am, O Allah, here I am at Your service, and at Your continued service; all good is in Your hands, and it is from You and to You.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''dua_ma_qultu_min_qawl''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء ما قلت من قول''',
    titleEn: r'''Dua for Words, Oaths, and Vows''',
    arabicText: r'''اللَّهُمَّ مَا قُلْتُ مِنْ قَوْلٍ ، أَوْ حَلَفْتُ مِنْ حَلِفٍ ، أَوْ نَذَرْتُ مِنْ نَذْرٍ ، فَمَشِيئَتُكَ بَيْنَ يَدَيْ ذَلِكَ كُلِّهِ ، مَا شِئْتَ كَانَ ، وَمَا لَمْ تَشَأْ لَمْ يَكُنْ ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِكَ .''',
    transliteration: r'''Allāhumma mā qultu min qawlin, aw ḥalaftu min ḥalifin, aw nadhartu min nadhrin, fa-mashī'atuka bayna yaday dhālika kullih, mā shi'ta kāna, wa mā lam tasha' lam yakun, wa lā ḥawla wa lā quwwata illā bik.''',
    translationEn: r'''O Allah, whatever word I have said, or oath I have sworn, or vow I have made, Your will stands before all of that. Whatever You will comes to be, and whatever You do not will does not come to be, and there is no power and no strength except through You.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''dua_ma_sallaytu_min_salat''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء ما صليت من صلاة''',
    titleEn: r'''Dua on Blessings and Curses''',
    arabicText: r'''اللَّهُمَّ مَا صَلَّيْتُ مِنْ صَلَاةٍ فَعَلَى مَنْ صَلَّيْتُ ، وَمَا لَعَنْتُ مِنْ لَعْنٍ فَعَلَى مَنْ لَعَنْتُ ، أَنتَ وَلِيِّي فِي الدُّنْيَا وَالآخِرَةِ ، تَوَفَّنِي مُسْلِمًا وَأَلْحِقْنِي بِالصَّالِحِينَ .''',
    transliteration: r'''Allāhumma mā ṣallaytu min ṣalātin fa-'alā man ṣallayt, wa mā la'antu min la'nin fa-'alā man la'ant, anta waliyyī fī ad-dunyā wa-l-ākhirah, tawaffanī muslimān wa alḥiqnī bi-ṣ-ṣāliḥīn.''',
    translationEn: r'''O Allah, any prayer for blessing I have made, let it fall upon whomever I prayed for; and any curse I have uttered, let it fall upon whomever I cursed. You are my Protector in this world and the Hereafter; cause me to die as a Muslim, and join me with the righteous.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''dua_rida_bada_alqada''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء الرضا بعد القضاء''',
    titleEn: r'''Dua for Contentment After the Decree''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَسْأَلُكَ الرِّضَى بَعدَ القَضَاءِ ، وَبَرْدَ العَيْشِ بَعْدَ المَوْتِ ، وَلَذَّةَ النَّظَرِ إِلَى وَجْهِكَ الكَرِيمِ ، وَالشَّوقَ إِلَى لِقَائِكَ ، فِي غَيْرِ ضَرَّاءَ مُضِرَّةٍ ، وَلَا فِتْنَةٍ مُضِلَّةٍ ، وَأَعُوذُ بِكَ أَنْ أَظْلِمَ أَوْ أُظلَمَ ، أَوْ أَعْتَدِيَ أَوْ يُعْتَدَى عَلَيَّ ، أَوْ أَكْتَسِبَ خَطِيئَةً ، أَوْ ذَنْبًا لَا تَغْفِرُهُ .''',
    transliteration: r'''Allāhumma innī as'aluka ar-riḍā ba'da al-qaḍā', wa barda al-'ayshi ba'da al-mawt, wa ladhdhata an-naẓari ilā wajhika al-karīm, wa-sh-shawqa ilā liqā'ik, fī ghayri ḍarrā'a muḍirratin wa lā fitnatin muḍillah, wa a'ūdhu bika an aẓlima aw uẓlam, aw a'tadiya aw yu'tadā 'alayya, aw aktasiba khaṭī'atan aw dhanban lā taghfiruh.''',
    translationEn: r'''O Allah, I ask You for contentment after the decree, for the coolness of life after death, for the sweetness of gazing upon Your noble Face, and for the longing to meet You, without harmful adversity or misguiding trial. And I seek refuge in You from wronging or being wronged, from transgressing or being transgressed against, or from committing a sin or an offense that You do not forgive.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
