  AdhkarEntry(
    id: r'''dua_shahada_wal_ahd''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء الشهادة والعهد''',
    titleEn: r'''Dua of Testimony and Covenant''',
    arabicText: r'''اللهمَّ فَاطِرَ السَّمَاوَاتِ وَالأَرضِ ، عَالِمَ الغَيْبِ وَالشَّهَادَةِ ، ذَا الجَلَالِ وَالإِكْرَامِ ، إِنِّي أَعهَدُ إِلَيكَ فِي هذِهِ الحَيَاةِ الدُّنْيَا ، وَأُشْهِدُكَ وَكَفَى بِكَ شَهِيدًا : إِنِّي أَشْهَدُ أَن لَّا إِلَهَ إِلَا أَنتَ وَحدَكَ لَا شَرِيكَ لَكَ ، وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ . وَأَشْهَدُ أَنَّ وَعْدَكَ حَقٌّ ، وَلِقَاءَكَ حَقٌّ ، وَالجَنَّةَ حَقٌّ ، وَالنَّارَ حَقٌّ ، وَأَنَّ السَّاعَةَ آتِيَةٌ لَا رَيْبَ فِيهَا ، وَأَنَّكَ تَبْعَثُ مَنْ فِي القُبُورِ ، وَأَنَّكَ إِنْ تَكِلْنِي إِلَى نَفْسِي تَكِلْنِي إِلَى ضَعْفٍ وَعَوْرَةٍ وَذَنْبٍ وَخَطِيئَةٍ ، وَأَنِّي لَا أَثِقُ إِلَّا بِرَحْمَتِكَ ؛ فَاغْفِرْ لِي ذُنُوبِي كُلَّهَا وَتُبْ عَلَيَّ إِنَّكَ أَنتَ التَّوَّابُ الرَّحِيمُ .''',
    transliteration: r'''Allāhumma Fāṭira as-samāwāti wa-l-arḍ, 'Ālima al-ghaybi wa-sh-shahādah, Dhā al-Jalāli wa-l-Ikrām, innī a'hadu ilayka fī hādhihi al-ḥayāti ad-dunyā, wa ushhiduka wa kafā bika shahīdā: innī ashhadu an lā ilāha illā anta waḥdaka lā sharīka lak, wa anna Muḥammadan 'abduka wa rasūluk. Wa ashhadu anna wa'daka ḥaqq, wa liqā'aka ḥaqq, wa-l-jannata ḥaqq, wa-n-nāra ḥaqq, wa anna as-sā'ata ātiyatun lā rayba fīhā, wa annaka tab'athu man fī al-qubūr, wa annaka in takilnī ilā nafsī takilnī ilā ḍa'fin wa 'awratin wa dhanbin wa khaṭī'ah, wa annī lā athiqu illā bi-raḥmatik; fa-ghfir lī dhunūbī kullahā wa tub 'alayya innaka anta at-Tawwābu ar-Raḥīm.''',
    translationEn: r'''O Allah, Originator of the heavens and the earth, Knower of the unseen and the witnessed, Possessor of Majesty and Honor, I make my covenant with You in this worldly life, and I call You to witness — and You suffice as a Witness — that I bear witness there is no god but You alone, without partner, and that Muhammad is Your servant and Messenger. And I bear witness that Your promise is true, that meeting You is true, that Paradise is true, that the Fire is true, that the Hour is coming with no doubt about it, and that You will resurrect those who are in the graves; and that if You entrust me to myself, You entrust me to weakness, exposure to fault, sin, and error, and that I trust only in Your mercy; so forgive me all my sins and turn to me in acceptance, for indeed You are the Ever-Relenting, the Most Merciful.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''istiadhah_sharri_kulli_shay''',
    category: AdhkarCategory.protection,
    titleAr: r'''التعوذ من شر كل شيء''',
    titleEn: r'''Refuge from the Evil of All Things''',
    arabicText: r'''اللَّهُمَّ رَبَّ السَّمَاوَاتِ وَالأَرْضِ وَرَبَّ العَرْشِ العَظِيمِ ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ ، فَالِقَ الحَبِّ وَالنَّوَى ، مُنَزِّلَ التَّوْرَاةِ وَالإِنجِيلِ وَالفُرْقَانِ ، أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنتَ آخِذٌ بِنَاصِيَتِهِ ، أَنتَ الأَوَّلُ فَلَيسَ قَبْلَكَ شَيْءٌ . وَأَنتَ الآخِرُ فَلَيسَ بَعْدَكَ شَيْءٌ . وَأَنتَ الظَّاهِرُ فَلَيسَ فَوقَكَ شَيْءٌ . وَأَنتَ البَاطِنُ فَلَيسَ دُونَكَ شَيْءٌ ، اقْضِ عَنِّي الدَّيْنَ ، وَأَغْنِنِي مِنَ الفَقْرِ .''',
    transliteration: r'''Allāhumma Rabba as-samāwāti wa-l-arḍ, wa Rabba al-'Arshi al-'Aẓīm, Rabbanā wa Rabba kulli shay', Fāliqa al-ḥabbi wa-n-nawā, Munazzila at-Tawrāti wa-l-Injīli wa-l-Furqān, a'ūdhu bika min sharri kulli shay'in anta ākhidhun bi-nāṣiyatih. Anta al-Awwalu fa-laysa qablaka shay'. Wa anta al-Ākhiru fa-laysa ba'daka shay'. Wa anta aẓ-Ẓāhiru fa-laysa fawqaka shay'. Wa anta al-Bāṭinu fa-laysa dūnaka shay'. Iqḍi 'annī ad-dayn, wa aghninī mina al-faqr.''',
    translationEn: r'''O Allah, Lord of the heavens and the earth, and Lord of the Mighty Throne, our Lord and the Lord of all things, Splitter of the grain and the date-stone, Revealer of the Torah, the Gospel, and the Criterion, I seek refuge in You from the evil of everything whose forelock You hold. You are the First, so nothing precedes You. You are the Last, so nothing succeeds You. You are the Manifest, so nothing is above You. You are the Hidden, so nothing is beneath You. Settle my debt on my behalf, and enrich me against poverty.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''istiadhah_ardhal_umur''',
    category: AdhkarCategory.protection,
    titleAr: r'''التعوذ من أرذل العمر''',
    titleEn: r'''Refuge from Decrepit Old Age''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ أَنْ أُرَدَّ إِلَى أَرذَلِ العُمُرِ .''',
    transliteration: r'''Allāhumma innī a'ūdhu bika min an uradda ilā ardhali al-'umur.''',
    translationEn: r'''O Allah, I seek refuge in You from being returned to the most decrepit age.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''dua_ihdini_liahsan_alamal''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء الهداية لأحسن الأعمال''',
    titleEn: r'''Dua for Guidance to Good Deeds and Character''',
    arabicText: r'''اللَّهُمَّ اهْدِنِي لِأَحْسَنِ الأَعْمَالِ وَالأَخْلَاقِ ، لَا يَهدِي لِأَحْسَنِهَا إِلَّا أَنتَ ، وَاصرِفْ عَنِّي سَيِّئَهَا ، لَا يَصرِفُ عَنِّي سَيِّئَهَا إِلَّا أَنتَ .''',
    transliteration: r'''Allāhumma ihdinī li-aḥsani al-a'māli wa-l-akhlāq, lā yahdī li-aḥsanihā illā ant, wa-ṣrif 'annī sayyi'ahā, lā yaṣrifu 'annī sayyi'ahā illā ant.''',
    translationEn: r'''O Allah, guide me to the best of deeds and character, for none guides to the best of them but You, and turn away from me their worst, for none turns away their worst from me but You.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''dua_aslih_li_dini_dari_rizqi''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء إصلاح الدين والدار والرزق''',
    titleEn: r'''Dua for Setting Right Religion, Home, and Provision''',
    arabicText: r'''اللَّهُمَّ أَصلِحْ لِي دِينِي ، وَوَسِّعْ لِي فِي دَارِي ، وَبَارِكْ لِي فِي رِزْقِي .''',
    transliteration: r'''Allāhumma aṣliḥ lī dīnī, wa wassi' lī fī dārī, wa bārik lī fī rizqī.''',
    translationEn: r'''O Allah, set right my religion for me, expand my dwelling for me, and bless my provision for me.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''istiadhah_qaswah_wal_ghaflah''',
    category: AdhkarCategory.protection,
    titleAr: r'''التعوذ من القسوة والغفلة''',
    titleEn: r'''Refuge from Hard-Heartedness and Heedlessness''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ القَسْوَةِ وَالغَفْلَةِ وَالذِّلَّةِ وَالمَسْكَنَةِ ، وَأَعُوذُ بِكَ مِنَ الكُفرِ وَالفُسُوقِ وَالشِّقَاقِ ، وَالسُّمعَةِ وَالرِّيَاءِ ، وَأَعُوذُ بِكَ مِنَ الصَّمَمِ وَالبَكَمِ وَالجُنُونِ وَالجُذَامِ وَسَيِّئِ الأَسْقَامِ .''',
    transliteration: r'''Allāhumma innī a'ūdhu bika mina al-qaswati wa-l-ghaflati wa-dh-dhillati wa-l-maskanah, wa a'ūdhu bika mina al-kufri wa-l-fusūqi wa-sh-shiqāq, wa-s-sum'ati wa-r-riyā', wa a'ūdhu bika mina aṣ-ṣamami wa-l-bakami wa-l-junūni wa-l-judhāmi wa sayyi'i al-asqām.''',
    translationEn: r'''O Allah, I seek refuge in You from hard-heartedness, heedlessness, abasement, and destitution, and I seek refuge in You from disbelief, defiance, and discord, and from seeking reputation and showing off, and I seek refuge in You from deafness, dumbness, madness, leprosy, and evil afflictions.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''dua_ati_nafsi_taqwaha''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء تقوى النفس وتزكيتها''',
    titleEn: r'''Dua for Piety and Purification of the Soul''',
    arabicText: r'''اللَّهُمَّ آتِ نَفْسِي تَقْوَاهَا ، وَزَكِّهَا أَنتَ خَيْرُ مَنْ زَكَّاهَا ، أَنتَ وَلِيُّهَا وَمَوْلَاهَا .''',
    transliteration: r'''Allāhumma āti nafsī taqwāhā, wa zakkihā anta khayru man zakkāhā, anta waliyyuhā wa mawlāhā.''',
    translationEn: r'''O Allah, grant my soul its God-consciousness, and purify it, for You are the best of those who purify it; You are its Guardian and its Master.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
