  ),
  AdhkarEntry(
    id: r'''istiadhah_ilm_la_yanfa''',
    category: AdhkarCategory.protection,
    titleAr: r'''التعوذ من علم لا ينفع''',
    titleEn: r'''Refuge from Unbeneficial Knowledge''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ ، وَقَلْبٍ لَا يَخْشَعُ ، وَنَفْسٍ لَا تَشْبَعُ ، وَدَعْوَةٍ لَا يُسْتَجَابُ لَهَا .''',
    transliteration: r'''Allāhumma innī a'ūdhu bika min 'ilmin lā yanfa', wa qalbin lā yakhsha', wa nafsin lā tashba', wa da'watin lā yustajābu lahā.''',
    translationEn: r'''O Allah, I seek refuge in You from knowledge that does not benefit, a heart that does not humble itself, a soul that is not satisfied, and a supplication that is not answered.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''istiadhah_sharri_ma_amiltu''',
    category: AdhkarCategory.protection,
    titleAr: r'''التعوذ من شر ما عملت''',
    titleEn: r'''Refuge from Evil Deeds Known and Unknown''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا عَمِلْتُ ، وَمِنْ شَرِّ مَا لَمْ أَعْمَلْ ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا عَلِمْتُ ، وَمِنْ شَرِّ مَا لَمْ أَعْلَمْ .''',
    transliteration: r'''Allāhumma innī a'ūdhu bika min sharri mā 'amiltu, wa min sharri mā lam a'mal, wa a'ūdhu bika min sharri mā 'alimtu, wa min sharri mā lam a'lam.''',
    translationEn: r'''O Allah, I seek refuge in You from the evil of what I have done, and from the evil of what I have not done, and I seek refuge in You from the evil of what I know, and from the evil of what I do not know.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''istiadhah_zawal_nimah''',
    category: AdhkarCategory.protection,
    titleAr: r'''التعوذ من زوال النعمة''',
    titleEn: r'''Refuge from the Loss of Blessing''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ ، وَتَحَوُّلِ عَافِيَتِكَ ، وَفُجَاءَةِ نِقْمَتِكَ ، وَجَمِيعِ سَخَطِكَ .''',
    transliteration: r'''Allāhumma innī a'ūdhu bika min zawāli ni'matik, wa taḥawwuli 'āfiyatik, wa fujā'ati niqmatik, wa jamī'i sakhaṭik.''',
    translationEn: r'''O Allah, I seek refuge in You from the departure of Your blessing, the passing of Your well-being, the suddenness of Your vengeance, and the whole of Your displeasure.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''istiadhah_hadm_wa_taraddi''',
    category: AdhkarCategory.protection,
    titleAr: r'''التعوذ من الهدم والتردي''',
    titleEn: r'''Refuge from Ruin and Calamity''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الهَدْمِ وَالتَّرَدِّي ، وَمِنَ الغَرَقِ وَالحَرَقِ وَالهَرَمِ ، وَأَعُوذُ بِكَ مِنْ أَنْ يَتَخَبَّطَنِي الشَّيْطَانُ عِندَ المَوْتِ ، وَأَعُوذُ بِكَ مِنْ أَنْ أَمُوتَ لَدِيغًا . وَأَعُوذُ بِكَ مِنْ طَمَعٍ يَهْدِي إِلَى طَبَعٍ .''',
    transliteration: r'''Allāhumma innī a'ūdhu bika mina al-hadmi wa-t-taraddī, wa mina al-gharaqi wa-l-ḥaraqi wa-l-haram, wa a'ūdhu bika min an yatakhabbaṭanī ash-shayṭānu 'inda al-mawt, wa a'ūdhu bika min an amūta ladīghā. Wa a'ūdhu bika min ṭama'in yahdī ilā ṭaba'.''',
    translationEn: r'''O Allah, I seek refuge in You from being crushed under a collapse and from falling into ruin, and from drowning, burning, and decrepit old age, and I seek refuge in You from the devil afflicting me with confusion at death, and I seek refuge in You from dying from a sting or bite. And I seek refuge in You from greed that leads to a vicious disposition.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''salawat_ibrahimiyyah_2''',
    category: AdhkarCategory.generalDhikr,
    titleAr: r'''الصلاة الإبراهيمية''',
    titleEn: r'''The Ibrahimic Blessing (Salawat)''',
    arabicText: r'''اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَآلِ إِبْرَاهِيمَ ، إِنَّكَ حَمِيدٌ مَجِيدٌ . وَبَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَآلِ إِبْرَاهِيمَ ، إِنَّكَ حَمِيدٌ مَجِيدٌ .''',
    transliteration: r'''Allāhumma ṣalli 'alā Muḥammadin wa 'alā āli Muḥammad, kamā ṣallayta 'alā Ibrāhīma wa āli Ibrāhīm, innaka Ḥamīdun Majīd. Wa bārik 'alā Muḥammadin wa 'alā āli Muḥammad, kamā bārakta 'alā Ibrāhīma wa āli Ibrāhīm, innaka Ḥamīdun Majīd.''',
    translationEn: r'''O Allah, send blessings upon Muhammad and upon the family of Muhammad, as You sent blessings upon Ibrahim and the family of Ibrahim; indeed You are Praiseworthy, Glorious. And bless Muhammad and the family of Muhammad, as You blessed Ibrahim and the family of Ibrahim; indeed You are Praiseworthy, Glorious.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''istiadhah_munkarat_alakhlaq''',
    category: AdhkarCategory.protection,
    titleAr: r'''التعوذ من منكرات الأخلاق''',
    titleEn: r'''Refuge from Evil Character and Deeds''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ مُنكَرَاتِ الأَخْلَاقِ وَالأَعْمَالِ وَالأَهْوَاءِ وَالأَدْوَاءِ . وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ ، وَقَهْرِ العَدُوِّ ، وَشَمَاتَةِ العِبَادِ .''',
    transliteration: r'''Allāhumma innī a'ūdhu bika min munkarāti al-akhlāqi wa-l-a'māli wa-l-ahwā'i wa-l-adwā'. Wa a'ūdhu bika min ghalabati ad-dayn, wa qahri al-'aduww, wa shamātati al-'ibād.''',
    translationEn: r'''O Allah, I seek refuge in You from evil character, deeds, desires, and diseases. And I seek refuge in You from being overcome by debt, overpowered by the enemy, and gloated over by people.''',
