  AdhkarEntry(
    id: r'''dua_aslih_li_dini_alladhi''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء إصلاح الدين والدنيا والآخرة''',
    titleEn: r'''Dua for Setting Right Religion, World, and Hereafter''',
    arabicText: r'''اللَّهُمَّ أَصْلِحْ لِي دِينِي الَّذِي هُوَ عِصْمَةُ أَمْرِي ، وَأَصْلِحْ لِي دُنْيَايَ الَّتِي فِيهَا مَعَاشِي ، وَأَصْلِحْ لِي آخِرَتِي الَّتِي إِلَيهَا مَعَادِي ، وَاجْعَلِ الحَيَاةَ زِيَادَةً لِي فِي كُلِّ خَيْرٍ ، وَاجْعَلِ المَوْتَ رَاحَةً لِي مِنْ كُلِّ شَرٍّ .''',
    transliteration: r'''Allāhumma aṣliḥ lī dīnī alladhī huwa 'iṣmatu amrī, wa aṣliḥ lī dunyāya allatī fīhā ma'āshī, wa aṣliḥ lī ākhiratī allatī ilayhā ma'ādī, wa ij'ali al-ḥayāta ziyādatan lī fī kulli khayr, wa ij'ali al-mawta rāḥatan lī min kulli sharr.''',
    translationEn: r'''O Allah, set right for me my religion, which is the safeguard of my affairs, and set right for me my worldly life, in which is my livelihood, and set right for me my Hereafter, to which is my return. Make life an increase for me in all good, and make death a relief for me from all evil.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
