    titleEn: r'''Lord, Help Me and Not Against Me''',
    arabicText: r'''رَبِّ أَعِنِّي وَلَا تُعِنْ عَلَيَّ ، وَانصُرْنِي وَلَا تَنصُرْ عَلَيَّ ، وَاهْدِنِي وَيَسِّرِ الهُدَى لِي .''',
    transliteration: r'''Rabbi a'innī wa lā tu'in 'alayya, wa-nṣurnī wa lā tanṣur 'alayya, wa-hdinī wa yassiri al-hudā lī.''',
    translationEn: r'''My Lord, help me and do not help against me, grant me victory and do not grant victory against me, guide me and make guidance easy for me.''',
