  AdhkarEntry(
    id: r'''dua_ijalni_dhakkaran''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم اجعلني ذكارا لك''',
    titleEn: r'''Dua to Be Ever-Remembering and Grateful''',
    arabicText: r'''اللَّهُمَّ اجْعَلْنِي ذَكَّارًا لَكَ ، شَكَّارًا لَكَ ، مُخْبِتًا إِلَيكَ ، أَوَّاهًا مُنِيبًا .''',
    transliteration: r'''Allāhumma ij'alnī dhakkāran lak, shakkāran lak, mukhbitan ilayk, awwāhan munībā.''',
    translationEn: r'''O Allah, make me one who remembers You often, thanks You much, is humbly submissive to You, and is a devoted, penitent supplicant.''',
