  AdhkarEntry(
    id: r'''dua_rabbi_taqabbal_tawbati''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''رب تقبل توبتي''',
    titleEn: r'''Lord, Accept My Repentance''',
    arabicText: r'''رَبِّ تَقَبَّلْ تَوْبَتِي ، وَاغْسِلْ حَوْبَتِي ، وَأَجِبْ دَعْوَتِي ، وَثَبِّتْ حُجَّتِي ، وَاهْدِ قَلْبِي ، وَسَدِّدْ لِسَانِي ، وَاسْلُلْ سَخِيمَةَ صَدْرِي .''',
    transliteration: r'''Rabbi taqabbal tawbatī, wa-ghsil ḥawbatī, wa ajib da'watī, wa thabbit ḥujjatī, wa-hdi qalbī, wa saddid lisānī, wa-slul sakhīmata ṣadrī.''',
    translationEn: r'''My Lord, accept my repentance, wash away my sin, answer my supplication, make firm my proof, guide my heart, make truthful my tongue, and draw out the rancor of my breast.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''dua_thabat_fil_amr''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء الثبات على الأمر''',
    titleEn: r'''Dua for Steadfastness and Sound Faith''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَسْأَلُكَ الثَّبَاتَ فِي الأَمرِ ، وَالعَزِيمَةَ عَلَى الرُّشْدِ ، وَأَسْأَلُكَ شُكْرَ نِعْمَتِكَ ، وَحُسْنَ عِبَادَتِكَ ، وَأَسْأَلُكَ قَلْبًا سَلِيمًا ، وَلِسَانًا صَادِقًا ، وَأَسْأَلُكَ مِنْ خَيْرِ مَا تَعْلَمُ ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا تَعْلَمُ ، وَأَسْتَغْفِرُكَ لِمَا تَعْلَمُ وَأَنتَ عَلَّامُ الغُيُوبِ .''',
    transliteration: r'''Allāhumma innī as'aluka ath-thabāta fī al-amr, wa-l-'azīmata 'alā ar-rushd, wa as'aluka shukra ni'matik, wa ḥusna 'ibādatik, wa as'aluka qalban salīmā, wa lisānan ṣādiqā, wa as'aluka min khayri mā ta'lam, wa a'ūdhu bika min sharri mā ta'lam, wa astaghfiruka limā ta'lamu wa anta 'Allāmu al-ghuyūb.''',
    translationEn: r'''O Allah, I ask You for steadfastness in the matter, and resolve upon right guidance. I ask You for gratitude for Your blessing and excellence in worshipping You. I ask You for a sound heart and a truthful tongue. I ask You for the good that You know, and I seek refuge in You from the evil that You know, and I ask Your forgiveness for what You know, for You are the Knower of the unseen.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
