    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء فعل الخيرات وترك المنكرات''',
    titleEn: r'''Dua for Doing Good and Avoiding Evil''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَسْأَلُكَ فِعْلَ الخَيْرَاتِ ، وَتَرْكَ المُنكَرَاتِ ، وَحُبَّ المَسَاكِينِ ، وَأَنْ تَغْفِرَ لِي وَتَرْحَمَنِي ، وَإِذَا أَرَدْتَ بِعِبَادِكَ فِتْنَةً فَتَوَفَّنِي إِلَيكَ غَيرَ مَفْتُونٍ .''',
    transliteration: r'''Allāhumma innī as'aluka fi'la al-khayrāt, wa tarka al-munkarāt, wa ḥubba al-masākīn, wa an taghfira lī wa tarḥamanī, wa idhā aradta bi-'ibādika fitnatan fa-tawaffanī ilayka ghayra maftūn.''',
    translationEn: r'''O Allah, I ask You for the doing of good deeds, the abandonment of evil deeds, and love of the poor; and that You forgive me and have mercy on me. And if You intend to try Your servants with a trial, then take me to You unafflicted by it.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
