    titleEn: r'''Dua for the Love of Allah''',
    arabicText: r'''اللَّهُمَّ أَسْأَلُكَ حُبَّكَ ، وَحُبَّ مَنْ يُحِبُّكَ ، وَحُبَّ كُلِّ عَمَلٍ يُقَرِّبُنِي إِلَى حُبِّكَ .''',
    transliteration: r'''Allāhumma as'aluka ḥubbak, wa ḥubba man yuḥibbuk, wa ḥubba kulli 'amalin yuqarribunī ilā ḥubbik.''',
    translationEn: r'''O Allah, I ask You for Your love, and the love of those who love You, and the love of every deed that draws me closer to Your love.''',
