    titleEn: r'''Dua for Allah's Love Above All''',
    arabicText: r'''اللَّهُمَّ اجْعَلْ حُبَّكَ أَحَبَّ إِلَيَّ مِنْ نَفْسِي وَأَهْلِي ، وَمَالِي وَوَلَدِي ، وَمِنَ المَاءِ البَارِدِ عَلَى الظَّمَأِ .''',
    transliteration: r'''Allāhumma ij'al ḥubbaka aḥabba ilayya min nafsī wa ahlī, wa mālī wa waladī, wa mina al-mā'i al-bāridi 'alā aẓ-ẓama'.''',
