    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء سعة الرزق عند الكبر''',
    titleEn: r'''Dua for Abundant Provision in Old Age''',
    arabicText: r'''اللَّهُمَّ اجْعَلْ أَوْسَعَ رِزْقِي عِنْدَ كِبَرِ سِنِّي ، وَانْقِطَاعِ عُمْرِي .''',
    transliteration: r'''Allāhumma ij'al awsa'a rizqī 'inda kibari sinnī, wa-nqiṭā'i 'umrī.''',
    translationEn: r'''O Allah, make my provision most abundant at the time of my old age and the ending of my life.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''dua_khayr_almasalah''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء خير المسألة والدعاء''',
    titleEn: r'''Dua for the Best of Asking and Supplication''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ المَسْأَلَةِ ، وَخَيْرَ الدُّعَاءِ ، وَخَيْرَ النَّجَاحِ ، وَخَيْرَ الثَّوَابِ ، وَثَبِّتْنِي ، وَثَقِّلْ مَوَازِينِي ، وَحَقِّقْ إِيمَانِي ، وَارْفَعْ دَرَجَتِي ، وَتَقَبَّلْ صَلَاتِي ، وَاغْفِرْ خَطِيئَاتِي ، وَأَسْأَلُكَ الدَّرَجَاتِ العُلَى مِنَ الجَنَّةِ . آمين .''',
    transliteration: r'''Allāhumma innī as'aluka khayra al-mas'alah, wa khayra ad-du'ā', wa khayra an-najāḥ, wa khayra ath-thawāb, wa thabbitnī, wa thaqqil mawāzīnī, wa ḥaqqiq īmānī, wa-rfa' darajatī, wa taqabbal ṣalātī, wa-ghfir khaṭī'ātī, wa as'aluka ad-darajāti al-'ulā mina al-jannah. Āmīn.''',
    translationEn: r'''O Allah, I ask You for the best of asking, the best of supplication, the best of success, and the best of reward. Make me steadfast, make heavy my scales, make true my faith, raise my rank, accept my prayer, forgive my sins, and I ask You for the highest ranks of Paradise. Amin.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''dua_tarfaa_dhikri''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء رفع الذكر ووضع الوزر''',
    titleEn: r'''Dua for Elevated Remembrance and Lifted Burden''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَسْأَلُكَ أَنْ تَرْفَعَ ذِكْرِي ، وَتَضَعَ وِزْرِي ، وَتُطَهِّرَ قَلْبِي ، وَتُحَصِّنَ فَرْجِي ، وَتَغْفِرَ لِي ذَنبِي ، وَأَسْأَلُكَ الدَّرَجَاتِ العُلَى مِنَ الجَنَّةِ . آمين .''',
    transliteration: r'''Allāhumma innī as'aluka an tarfa'a dhikrī, wa taḍa'a wizrī, wa tuṭahhira qalbī, wa tuḥaṣṣina farjī, wa taghfira lī dhanbī, wa as'aluka ad-darajāti al-'ulā mina al-jannah. Āmīn.''',
    translationEn: r'''O Allah, I ask You to raise my remembrance, lift my burden, purify my heart, guard my chastity, and forgive me my sin, and I ask You for the highest ranks of Paradise. Amin.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
