    titleEn: r'''O Director of Hearts and Sights''',
    arabicText: r'''اللَّهُمَّ مُصَرِّفَ القُلُوبِ وَالأَبْصَارِ ، صَرِّفْ قُلُوبَنَا عَلَى طَاعَتِكَ .''',
    transliteration: r'''Allāhumma Muṣarrifa al-qulūbi wa-l-abṣār, ṣarrif qulūbanā 'alā ṭā'atik.''',
    translationEn: r'''O Allah, Director of hearts and sights, direct our hearts to Your obedience.''',
