  AdhkarEntry(
    id: r'''dua_zidna_wala_tanqusna''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم زدنا ولا تنقصنا''',
    titleEn: r'''Dua for Increase and Honor''',
    arabicText: r'''اللَّهُمَّ زِدْنَا وَلَا تَنقُصْنَا ، وَأَكْرِمْنَا وَلَا تُهِنَّا ، وَأَعْطِنَا وَلَا تَحْرِمْنَا ، وَآثِرْنَا وَلَا تُؤْثِرْ عَلَينَا .''',
    transliteration: r'''Allāhumma zidnā wa lā tanquṣnā, wa akrimnā wa lā tuhinnā, wa a'ṭinā wa lā taḥrimnā, wa āthirnā wa lā tu'thir 'alaynā.''',
    translationEn: r'''O Allah, increase us and do not diminish us, honor us and do not humiliate us, give us and do not deprive us, and favor us and do not favor others over us.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
