    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم أعنا على ذكرك وشكرك''',
    titleEn: r'''Dua for Help in Remembrance and Gratitude''',
    arabicText: r'''اللَّهُمَّ أَعِنَّا عَلَى ذِكْرِكَ وَشُكْرِكَ ، وَحُسْنِ عِبَادَتِكَ .''',
    transliteration: r'''Allāhumma a'innā 'alā dhikrika wa shukrik, wa ḥusni 'ibādatik.''',
