  AdhkarEntry(
    id: r'''dua_asaluka_alafw_walafiyah''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء العفو والعافية''',
    titleEn: r'''Dua for Pardon and Well-Being''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَسْأَلُكَ العَفْوَ وَالعَافِيَةَ ، وَالمُعَافَاةَ الدَّائِمَةَ ، فِي الدِّينِ وَالدُّنْيَا وَالآخِرَةِ .''',
    transliteration: r'''Allāhumma innī as'aluka al-'afwa wa-l-'āfiyah, wa-l-mu'āfāta ad-dā'imah, fī ad-dīni wa-d-dunyā wa-l-ākhirah.''',
    translationEn: r'''O Allah, I ask You for pardon and well-being, and lasting well-being, in religion, this world, and the Hereafter.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
