    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''dua_afuwwun_tuhibb_alafw''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم إنك عفو تحب العفو''',
    titleEn: r'''Dua of Laylat al-Qadr for Pardon''',
    arabicText: r'''اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ العَفْوَ ، فَاعْفُ عَنِّي .''',
    transliteration: r'''Allāhumma innaka 'Afuwwun tuḥibbu al-'afwa, fa-'fu 'annī.''',
    translationEn: r'''O Allah, You are Pardoning and You love to pardon, so pardon me.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
