  AdhkarEntry(
    id: r'''closing_dua_and_response''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''هذا الدعاء وعليك الإجابة''',
    titleEn: r'''This Is the Supplication, the Answer Is Yours''',
    arabicText: r'''اللَّهُمَّ هذَا الدُّعَاءُ، وعَلَيْكَ الإِجَابَةُ، وهذَا الجَهْدُ وعَلَيْكَ التُّكْلانُ، ولاَ حَوْلَ ولا قُوَّةَ إلَّا بِكَ.''',
    transliteration: r'''Allāhumma hādhā ad-duʿāʾu, wa ʿalayka al-ijābatu, wa hādhā al-jahdu wa ʿalayka at-tuklānu, wa lā ḥawla wa lā quwwata illā bika.''',
    translationEn: r'''O Allah, this is the supplication, and upon You is its answering; this is the [utmost] effort, and upon You is the reliance. There is no might and no power except with You.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''salawat_ala_muhammad''',
    category: AdhkarCategory.generalDhikr,
