  AdhkarEntry(
    id: r'''refuge_from_evil_of_self''',
    category: AdhkarCategory.protection,
    titleAr: r'''التعوذ من شر النفس''',
    titleEn: r'''Seeking Refuge from the Evil of the Self''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، ومِنْ شَرِّ كُلِّ دَابَّةٍ أَنْتَ آخِذٌ بِنَاصِيَتِهَا، إِنَّ رَبِّي عَلَى صِرَاطٍ مُسْتَقِيمٍ.''',
    transliteration: r'''Allāhumma innī aʿūdhu bika min sharri nafsī, wa min sharri kulli dābbatin anta ākhidhun bināṣiyatihā, inna Rabbī ʿalā ṣirāṭin mustaqīm.''',
    translationEn: r'''O Allah, I seek refuge in You from the evil of myself, and from the evil of every creature whose forelock You hold. Indeed, my Lord is upon a straight path.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''dua_fariq_al_hamm''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء فارج الهم وكاشف الغم''',
    titleEn: r'''O Reliever of Distress and Remover of Grief''',
    arabicText: r'''اللَّهُمَّ فَارِجَ الهَمِّ، وَكَاشِفَ الغَمِّ، مُجِيبَ دَعْوَةِ المُضْطَرِّينَ، رَحْمَانَ الدُّنْيَا والآخِرَةِ وَرَحِيمَهُمَا، ارْحَمْنِي رَحْمَةً تُغْنِينِي بِهَا عَنْ رَحْمَةِ مَنْ سِوَاكَ.''',
    transliteration: r'''Allāhumma fārija al-hammi, wa kāshifa al-ghammi, mujība daʿwati al-muḍṭarrīna, Raḥmāna ad-dunyā wal-ākhirati wa Raḥīmahumā, irḥamnī raḥmatan tughnīnī bihā ʿan raḥmati man siwāka.''',
    translationEn: r'''O Allah, Reliever of distress, Remover of grief, Answerer of the call of those in desperate need, the Most Merciful of this world and the Hereafter and the Most Merciful of both, have mercy upon me with a mercy that makes me independent of the mercy of anyone besides You.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''morning_protection_dhikr''',
    category: AdhkarCategory.protection,
    titleAr: r'''أصبحنا بالله وبعزته وسلطانه''',
    titleEn: r'''We Have Entered the Morning Under Allah's Protection''',
    arabicText: r'''أَصْبَحْنَا بِاللَّهِ الَّذِي لَيْسَ شَيْءٌ مِنْهُ مُمْتَنِعٌ، وَبِعِزَّةِ اللَّهِ الَّتِي لا تُرَامُ وَلاَ تُضَامُ، وَبِسُلْطَانِ اللَّهِ المَنِيعِ نَحْتَجِبُ، وَبِأَسْمَاءِ اللَّهِ الحُسْنَى كُلِّهَا، عَائِذًا بِاللَّهِ مِنَ الأَبَالِسَةِ، وَمِنْ شَرِّ شَيَاطِينِ الإِنْسِ وَالجِنِّ، وَمِنْ شَرِّ كُلِّ مُعْلِنٍ أَوْ مُسِرٍّ، وَمِنْ شَرِّ مَا يَكْمُنُ بِاللَّيْلِ ويَخْرُجُ بِالنَّهَارِ، أَوْ يَكْمُنُ بِالنَّهَارِ ويَخْرُجُ بِاللَّيْلِ، ومَنْ شَرِّ مَا خَلَقَ وذَرَأَ وبَرَأَ، ومِنْ شَرِّ إِبْلِيسَ وجُنُودِهِ، ومِن شَرِّ كُلِّ دَابَّةٍ أَنْتَ آخِذٌ بِنَاصِيَتِهَا.''',
    transliteration: r'''Aṣbaḥnā billāhi alladhī laysa shayʾun minhu mumtaniʿun, wa bi-ʿizzati Allāhi allatī lā turāmu wa lā tuḍāmu, wa bi-sulṭāni Allāhi al-manīʿi naḥtajibu, wa bi-asmāʾi Allāhi al-ḥusnā kullihā, ʿāʾidhan billāhi mina al-abālisati, wa min sharri shayāṭīni al-insi wal-jinni, wa min sharri kulli muʿlinin aw musirrin, wa min sharri mā yakmunu bil-layli wa yakhruju bin-nahāri, aw yakmunu bin-nahāri wa yakhruju bil-layli, wa min sharri mā khalaqa wa dharaʾa wa baraʾa, wa min sharri Iblīsa wa junūdihi, wa min sharri kulli dābbatin anta ākhidhun bināṣiyatihā.''',
    translationEn: r'''We have entered the morning by [the protection of] Allah, from Whom nothing can be withheld; by the might of Allah which cannot be overcome or wronged; by the impregnable authority of Allah do we shelter ourselves; and by all of Allah's Most Beautiful Names — seeking refuge in Allah from the devils, and from the evil of the devils among mankind and the jinn, and from the evil of everyone who does evil openly or secretly, and from the evil of that which lurks by night and comes forth by day, or lurks by day and comes forth by night, and from the evil of what He created, spread forth, and originated, and from the evil of Iblis and his hosts, and from the evil of every creature whose forelock You hold.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''refuge_of_musa_isa_ibrahim''',
    category: AdhkarCategory.protection,
    titleAr: r'''تعوذ موسى وعيسى وإبراهيم''',
    titleEn: r'''The Refuge Sought by Musa, 'Isa, and Ibrahim''',
    arabicText: r'''أَعُوذُ بِاللَّهِ مِمَّا اسْتَعَاذَ بِهِ مُوسَى وعِيسَى وإِبْرَاهِيمُ الَّذِي وَفَّى، ومِن شَرِّ مَا خَلَقَ وذَرَأَ وبَرَأَ، ومِن شَرِّ إِبْلِيسَ وجُنُودِهِ ومِنْ شَرِّ مَا يُتَّقَى.''',
    transliteration: r'''Aʿūdhu billāhi mimmā istaʿādha bihi Mūsā wa ʿĪsā wa Ibrāhīmu alladhī waffā, wa min sharri mā khalaqa wa dharaʾa wa baraʾa, wa min sharri Iblīsa wa junūdihi, wa min sharri mā yuttaqā.''',
    translationEn: r'''I seek refuge in Allah with that which Musa, 'Isa, and Ibrahim — who fulfilled [his covenant] — sought refuge, and from the evil of what He created, spread forth, and originated, and from the evil of Iblis and his hosts, and from the evil of what is to be guarded against.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''dua_khayr_ma_indak''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء أسألك خير ما عندك''',
    titleEn: r'''Asking for the Best of What You Possess''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ مَا عِنْدَكَ، وأَفِضْ عَلَيَّ مِنْ فَضْلِكَ، وانْشُرْ عَلَيَّ مِنْ رَحْمَتِكَ، وأَنْزِلْ عَلَيَّ مِنْ بَرَكَاتِكَ.''',
    transliteration: r'''Allāhumma innī asʾaluka khayra mā ʿindaka, wa afiḍ ʿalayya min faḍlika, wanshur ʿalayya min raḥmatika, wa anzil ʿalayya min barakātika.''',
    translationEn: r'''O Allah, I ask You for the best of what You possess; pour upon me from Your bounty, spread over me from Your mercy, and send down upon me from Your blessings.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''laka_al_hamdu_kulluhu_wal_mulk''',
    category: AdhkarCategory.generalDhikr,
    titleAr: r'''لك الحمد كله ولك الملك كله''',
    titleEn: r'''To You Belongs All Praise and All Sovereignty''',
    arabicText: r'''اللَّهُمَّ لَكَ الحَمْدُ كُلُّهُ، ولَكَ المُلْكُ كُلُّهُ، وبِيَدِكَ الخَيْرُ كُلُّهُ، وإِلَيْكَ يَرْجِعُ الأَمْرُ كُلُّهُ، عَلاَنِيَتُهُ وَسِرُّهُ، فَأَهْلاً أَنْتَ أَنْ تُحْمَدَ، إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ.''',
    transliteration: r'''Allāhumma laka al-ḥamdu kulluhu, wa laka al-mulku kulluhu, wa bi-yadika al-khayru kulluhu, wa ilayka yarjiʿu al-amru kulluhu, ʿalāniyatuhu wa sirruhu, fa-ahlan anta an tuḥmada, innaka ʿalā kulli shayʾin qadīr.''',
    translationEn: r'''O Allah, to You belongs all praise, to You belongs all sovereignty, in Your hand is all good, and to You all affairs return, both open and hidden. You are indeed worthy to be praised; verily You are able to do all things.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''dua_forgive_past_sins''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم اغفر لي ما مضى من ذنوبي''',
    titleEn: r'''Forgive My Past Sins and Preserve My Remaining Life''',
    arabicText: r'''اللَّهُمَّ اغْفِرْ لِي جَمِيعَ مَا مَضَى مِنْ ذُنُوبِي، واعْصِمْنِي فِيمَا بَقِيَ مِنْ عُمْرِي، وارْزُقْنِي عَمَلاً زَاكِيًا تَرْضَى بِهِ عَنِّي.''',
    transliteration: r'''Allāhumma-ghfir lī jamīʿa mā maḍā min dhunūbī, wa-ʿṣimnī fīmā baqiya min ʿumrī, wa-rzuqnī ʿamalan zākiyan tarḍā bihi ʿannī.''',
    translationEn: r'''O Allah, forgive me all the sins I have committed in the past, protect me in what remains of my life, and grant me pure deeds with which You are pleased with me.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''dua_daif_faqawwini_fi_ridak''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''ضعيف فقوني في رضاك''',
    titleEn: r'''Strengthen Me in Your Good Pleasure''',
    arabicText: r'''اللَّهُمَّ إِنِّي ضَعِيفٌ فَقَوِّنِي في رِضَاكَ، وخُذْ إلى الخَيْرِ بِنَاصِيَتِي، واجْعَلِ الإِسْلامَ مُنْتَهَى رَجَائِي.''',
    transliteration: r'''Allāhumma innī ḍaʿīfun fa-qawwinī fī riḍāka, wa khudh ilā al-khayri bināṣiyatī, wajʿali al-Islāma muntahā rajāʾī.''',
    translationEn: r'''O Allah, I am weak, so strengthen me in Your good pleasure; take my forelock towards good, and make Islam the utmost limit of my hope.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''dua_daif_dhalil_faqir''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''ضعيف فقوني ذليل فأعزني فقير فأغنني''',
    titleEn: r'''Weak, Lowly, and Poor — Aid Me''',
    arabicText: r'''اللَّهُمَّ إِنِّي ضَعِيفٌ فَقَوِّني، وإِنِّي ذَلِيلٌ فَأَعِزَّني، وإِنِّي فَقِيرٌ فَأَغْنِني.''',
    transliteration: r'''Allāhumma innī ḍaʿīfun fa-qawwinī, wa innī dhalīlun fa-aʿizzanī, wa innī faqīrun fa-aghninī.''',
    translationEn: r'''O Allah, I am weak, so strengthen me; I am lowly, so honor me; and I am poor, so enrich me.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''la_qabida_lima_basatta''',
    category: AdhkarCategory.generalDhikr,
    titleAr: r'''لا قابض لما بسطت ولا باسط لما قبضت''',
    titleEn: r'''None Can Withhold What You Give''',
    arabicText: r'''اللَّهُمَّ لَكَ الحَمْدُ كُلُّهُ، لَا قَابِضَ لِمَا بَسَطْتَ، ولَا بَاسِطَ لِمَا قَبَضْتَ، وَلا هَادِيَ لِمَنْ أَضْلَلْتَ، ولامُضِلَّ لِمَنْ هَدَيْتَ، وَلاَ مُعْطِيَ لِمَا مَنَعْتَ، ولا مانِعَ لِمَا أَعْطَيْتَ، ولا مُقَرِّبَ لِمَا بَاعَدْتَ، ولا مُبَاعِدَ لِمَا قَرَّبْتَ.''',
    transliteration: r'''Allāhumma laka al-ḥamdu kulluhu, lā qābiḍa limā basaṭta, wa lā bāsiṭa limā qabaḍta, wa lā hādiya liman aḍlalta, wa lā muḍilla liman hadayta, wa lā muʿṭiya limā manaʿta, wa lā māniʿa limā aʿṭayta, wa lā muqarriba limā bāʿadta, wa lā mubāʿida limā qarrabta.''',
    translationEn: r'''O Allah, to You belongs all praise. None can withhold what You have spread forth, and none can spread forth what You have withheld; none can guide whom You have led astray, and none can lead astray whom You have guided; none can give what You have withheld, and none can withhold what You have given; none can bring near what You have made distant, and none can make distant what You have brought near.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''dua_ibsut_alayna_barakat''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم ابسط علينا من بركاتك''',
    titleEn: r'''Extend Upon Us Your Blessings and Provision''',
    arabicText: r'''اللَّهُمَّ ابْسُطْ عَلَيْنَا مِنْ بَرَكَاتِكَ وَرَحْمَتِكَ وَرِزْقِكَ.''',
    transliteration: r'''Allāhumma-bsuṭ ʿalaynā min barakātika wa raḥmatika wa rizqika.''',
    translationEn: r'''O Allah, extend over us Your blessings, Your mercy, and Your provision.''',
