    category: AdhkarCategory.dailyDuas,
    titleAr: r'''النعيم يوم العيلة والأمن يوم الخوف''',
    titleEn: r'''Bliss on the Day of Poverty, Safety on the Day of Fear''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَسْأَلُكَ النَّعِيمَ يَوْمَ العَيْلَةِ، والأَمْنَ يَوْمَ الخَوْفِ.''',
    transliteration: r'''Allāhumma innī asʾaluka an-naʿīma yawma al-ʿaylati, wal-amna yawma al-khawf.''',
    translationEn: r'''O Allah, I ask You for bliss on the day of poverty, and for safety on the day of fear.''',
