  AdhkarEntry(
    id: r'''audh_min_sharri_ma_atayta_wa_manata''',
    category: AdhkarCategory.protection,
    titleAr: r'''عائذ من شر ما أعطيتنا وما منعتنا''',
    titleEn: r'''Refuge from the Evil of What Is Given or Withheld''',
    arabicText: r'''اللَّهُمَّ إِنِّي عَائِذٌ بِكَ مِنْ شَرِّ مَا أَعْطَيْتَنَا، وَمِنْ شَرِّ مَا مَنَعْتَنَا.''',
    transliteration: r'''Allāhumma innī ʿāʾidhun bika min sharri mā aʿṭaytanā, wa min sharri mā manaʿtanā.''',
    translationEn: r'''O Allah, I take refuge with You from the evil of what You have given us, and from the evil of what You have withheld from us.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
