  AdhkarEntry(
    id: r'''dua_habbib_ilayna_al_iman''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''حبب إلينا الإيمان وزينه في قلوبنا''',
    titleEn: r'''Make Faith Beloved to Us''',
    arabicText: r'''اللَّهُمَّ حَبِّبْ إِلَيْنَا الإِيمَانَ، وزَيِّنْهُ في قُلُوبِنَا، وكَرِّهْ إِلَيْنَا الكُفْرَ والفُسُوقَ والعِصْيَانَ، واجْعَلْنَا مِنَ الرَّاشِدِينَ.''',
    transliteration: r'''Allāhumma ḥabbib ilaynā al-īmāna, wa zayyinhu fī qulūbinā, wa karrih ilaynā al-kufra wal-fusūqa wal-ʿiṣyāna, wajʿalnā mina ar-rāshidīn.''',
    translationEn: r'''O Allah, make faith beloved to us and beautify it in our hearts, and make disbelief, defiance, and disobedience hateful to us, and make us among the rightly guided.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''dua_ahyina_muslimin_wa_tawaffana_muslimin''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''أحيني مسلما وتوفني مسلما''',
    titleEn: r'''Let Us Live and Die as Muslims''',
    arabicText: r'''اللَّهُمَّ أَحْيِنَا مُسْلِمِينَ، وتَوَفَّنَا مُسْلِمِينَ، غَيْرَ خَزَايَا وَلاَ مَفْتُونِينَ.''',
    transliteration: r'''Allāhumma aḥyinā muslimīna, wa tawaffanā muslimīna, ghayra khazāyā wa lā maftūnīn.''',
    translationEn: r'''O Allah, let us live as Muslims, and let us die as Muslims, without disgrace and without being subjected to trial.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
