  ),
  AdhkarEntry(
    id: r'''dua_qatil_al_kafara_yukadhdhibun_rusulak''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم قاتل الكفرة الذين يكذبون رسلك''',
    titleEn: r'''Against Those Who Deny the Messengers''',
    arabicText: r'''اللَّهُمَّ قَاتِلِ الكَفَرَةَ الَّذِينَ يُكَذِّبُونَ رُسُلَكَ، ويَصُدُّونَ عَنْ سَبِيلِكَ، واجْعَلْ عَلَيْهِمْ رِجْزَكَ وعَذَابَكَ.''',
    transliteration: r'''Allāhumma qātili al-kafarata alladhīna yukadhdhibūna rusulaka, wa yaṣuddūna ʿan sabīlika, wajʿal ʿalayhim rijzaka wa ʿadhābaka.''',
    translationEn: r'''O Allah, fight the disbelievers who deny Your messengers and turn [people] away from Your path, and send down upon them Your torment and Your punishment.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''dua_qatil_al_kafara_ahl_al_kitab''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم قاتل الكفرة الذين أوتوا الكتاب''',
    titleEn: r'''Against the Disbelieving People of the Book''',
    arabicText: r'''اللَّهُمَّ قَاتِلِ الكَفَرَةَ الَّذِينَ أُوتُوا الكِتَابَ، إِلَهَ الحَقِّ.''',
    transliteration: r'''Allāhumma qātili al-kafarata alladhīna ūtū al-kitāba, ilāha al-ḥaqq.''',
    translationEn: r'''O Allah, fight the disbelievers who were given the Scripture, O God of Truth.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''audh_min_at_tan_wat_taun_wal_waba''',
    category: AdhkarCategory.protection,
    titleAr: r'''التعوذ من الطعن والطاعون والوباء''',
    titleEn: r'''Refuge from Being Stabbed, Plague, and Pestilence''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الطَّعْنِ والطَّاعُونِ والوَبَاءِ، وعَظِيمِ البَلَاءِ، في النَّفْسِ والأَهْلِ، والمَالِ والوَلَدِ. اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ؛ مِمَّا نَخَافُ ونَحْذَرُ. اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، عَدَدَ ذُنُوبِنَا حَتَّى تُغْفَرْ.''',
    transliteration: r'''Allāhumma innī aʿūdhu bika mina aṭ-ṭaʿni waṭ-ṭāʿūni wal-wabāʾi, wa ʿaẓīmi al-balāʾi, fī an-nafsi wal-ahli, wal-māli wal-waladi. Allāhu akbar, Allāhu akbar, Allāhu akbar; mimmā nakhāfu wa naḥdharu. Allāhu akbar, Allāhu akbar, Allāhu akbar, ʿadada dhunūbinā ḥattā tughfar.''',
    translationEn: r'''O Allah, I seek refuge in You from being stabbed, from plague, and from pestilence, and from great affliction — in myself, my family, my wealth, and my children. Allah is Greater, Allah is Greater, Allah is Greater — than all we fear and guard against. Allah is Greater, Allah is Greater, Allah is Greater — the number of our sins, until they are forgiven.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 3,
    repetitionNote: r'''"اللَّهُ أَكْبَرُ" (Allāhu akbar) is repeated three times in each of the two places it occurs in this du'a.''',
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''dua_kama_baathta_nabiyyaka''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم كما بعثت فينا نبيك محمدا''',
    titleEn: r'''Supplication for Flourishing, Safe Homes''',
    arabicText: r'''اللَّهُمَّ كما بَعَثْتَ فِينَا نَبِيَّكَ مُحَمَّدًا ﷺ فَاعْمُرْ لَنَا مَنَازِلَنَا، وَلَا تُؤَاخِذْنَا بِسُوءِ فِعْلِنَا، وَلَا تُهْلِكْنَا بِخَطَايَانَا يَا أَرْحَمَ الرَّاحِمِينَ. سَلَامٌ قَوْلًا مِنْ رَبٍّ رَحِيمٍ.''',
    transliteration: r'''Allāhumma kamā baʿathta fīnā nabiyyaka Muḥammadan (ṣallā Allāhu ʿalayhi wa sallam), fa-ʿmur lanā manāzilanā, wa lā tuʾākhidhnā bi-sūʾi fiʿlinā, wa lā tuhliknā bi-khaṭāyānā yā arḥama ar-rāḥimīn. Salāmun qawlan min Rabbin Raḥīm.''',
    translationEn: r'''O Allah, just as You sent among us Your Prophet Muhammad (peace and blessings be upon him), so make our dwellings flourish for us, do not take us to task for our evil deeds, and do not destroy us for our sins, O Most Merciful of the merciful. "Peace" — a word from a Merciful Lord.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''hassantu_nafsi_wa_ahli_wa_mali''',
    category: AdhkarCategory.protection,
    titleAr: r'''حصنت نفسي وأهلي ومالي وولدي''',
    titleEn: r'''Fortifying Oneself, Family, and Wealth with Allah''',
    arabicText: r'''حَصَّنْتُ نَفْسِي وأَهْلِي وَمَالِي وَوَلَدِي بِاللَّهِ الحَيِّ القَيُّومِ الَّذِي لَا يَمُوتُ أَبَدًا، وَرَفَعَ اللَّهُ عَنَّا السُّوءَ وَالأَذَى بِأَلْفِ أَلْفِ أَلْفِ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ العَلِيِّ العَظِيمِ.''',
    transliteration: r'''Ḥaṣṣantu nafsī wa ahlī wa mālī wa waladī billāhi al-ḥayyi al-qayyūmi alladhī lā yamūtu abadan, wa rafaʿa Allāhu ʿannā as-sūʾa wal-adhā bi-alfi alfi alfi lā ḥawla wa lā quwwata illā billāhi al-ʿaliyyi al-ʿaẓīm.''',
    translationEn: r'''I have fortified myself, my family, my wealth, and my children with Allah, the Ever-Living, the Sustainer, Who never dies, and Allah has lifted evil and harm from us by a thousand thousand thousand [recitations of] "There is no might nor power except with Allah, the Most High, the Most Great."''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''allahumma_audhu_min_al_tan_wa_al_taun''',
    category: AdhkarCategory.protection,
    titleAr: r'''التعوذ من الطاعون والبلاء''',
    titleEn: r'''Refuge from Plague and Affliction''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الطَّعْنِ والطَّاعُونِ ، ومِن هُجُومِ البَلاَءِ ، ومِن مَوتِ الفُجْأَةِ ، ومِنْ سَعْرَةِ الحُمَّى ، ومِنْ سُوءِ القَضَاءِ ، ومِنْ شَرِّ البَلاَءِ .''',
    transliteration: r'''Allāhumma innī a'ūdhu bika mina aṭ-ṭa'ni wa aṭ-ṭā'ūni, wa min hujūmi al-balā'i, wa min mawti al-fuj'ati, wa min sa'rati al-ḥummā, wa min sū'i al-qaḍā'i, wa min sharri al-balā'.''',
    translationEn: r'''O Allah, I seek refuge in You from the stab wound and the plague, from the sudden onset of tribulation, from sudden death, from the ravages of fever, from an evil decree, and from the evil of tribulation.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
