    category: AdhkarCategory.protection,
    titleAr: r'''صرف عذاب جهنم''',
    titleEn: r'''Averting the Punishment of Hell''',
    arabicText: r'''رَبَّنَا اصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ إِنَّ عَذابَها كَانَ غَرَامًا .''',
    transliteration: r'''Rabbanā iṣrif 'annā 'adhāba Jahannama inna 'adhābahā kāna gharāmā.''',
    translationEn: r'''Our Lord, avert from us the punishment of Hell; indeed, its punishment is ever inescapable.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
