  AdhkarEntry(
    id: r'''rabbana_zalamna_anfusana''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''ربنا ظلمنا أنفسنا''',
    titleEn: r'''Our Lord, We Have Wronged Ourselves''',
    arabicText: r'''رَبَّنَا ظَلَمْنَا أَنْفُسَنَا ، وَإِنْ لَمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الخَاسِرِينَ ، بِرَحْمَتِكَ يَا رَبَّ العَالَمِينَ ،''',
    transliteration: r'''Rabbanā ẓalamnā anfusanā, wa in lam taghfir lanā wa tarḥamnā lanakūnanna mina al-khāsirīn, bi-raḥmatika yā Rabba al-'ālamīn.''',
    translationEn: r'''Our Lord, we have wronged ourselves, and if You do not forgive us and have mercy upon us, we will surely be among the losers — by Your mercy, O Lord of the Worlds.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
