  AdhkarEntry(
    id: r'''allahumma_ajjil_li_awliyaika_al_faraj''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء طول العمر والعافية''',
    titleEn: r'''Supplication for Long Life and Well-being''',
    arabicText: r'''اللَّهُمَّ عَجِّل لأَوْلِيَائكَ الفَرَجَ والعَافِيَةَ ، وزِدْ لي في حَياتي ، فإنَّكَ أَنتَ اللَّه الذي يَهَبُ عَيشَ الأَبَد لأَهْلِ الآخِرَةِ فَهَبْ لي عُمْرًا طَويلًا مَديدًا ، وعَيشًا مَزيدًا في عَافِيَتِكَ ورِضَاكَ ؛ فإنَّكَ وَليُّ ذلك ، والقَادِرُ عَلَيهِ في الدُّنيا والآخِرَة .''',
    transliteration: r'''Allāhumma 'ajjil li-awliyā'ika al-faraja wal-'āfiyah, wa zid lī fī ḥayātī, fa-innaka anta Allāhu alladhī yahabu 'aysha al-abadi li-ahli al-ākhirah, fa-hab lī 'umran ṭawīlan madīdan, wa 'ayshan mazīdan fī 'āfiyatika wa riḍāka; fa-innaka waliyyu dhālika, wal-qādiru 'alayhi fid-dunyā wal-ākhirah.''',
    translationEn: r'''O Allah, hasten relief and well-being for Your allies, and increase my life; for You are Allah who grants eternal life to the people of the Hereafter, so grant me a long, extended lifespan, and an increased life in Your well-being and pleasure; for You are the Guardian of that, and the One capable of it in this world and the Hereafter.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''audhu_bi_kalimat_allah_al_tammat''',
    category: AdhkarCategory.protection,
    titleAr: r'''التعوذ بكلمات الله التامات''',
    titleEn: r'''Refuge in Allah's Perfect Words''',
    arabicText: r'''أَعوذُ بِكَلِمَاتِ اللَّه التَّامَّاتِ مِن غَضَبِهِ وأَليمِ عِقَابِهِ ، وشَرِّ عِبَادِهِ ، ومِن شَرِّ هَمَزَاتِ الشَّيَاطِين ، وأَن يَحْضُرُونِ .''',
    transliteration: r'''A'ūdhu bi-kalimāti Allāhi at-tāmmāti min ghaḍabihi wa alīmi 'iqābihi, wa sharri 'ibādihi, wa min sharri hamazāti ash-shayāṭīni, wa an yaḥḍurūn.''',
    translationEn: r'''I seek refuge in the perfect words of Allah from His anger and the pain of His punishment, from the evil of His servants, from the evil whisperings of the devils, and from their presence with me.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''allahumma_audhu_bi_wajhika_al_karim''',
    category: AdhkarCategory.protection,
    titleAr: r'''التعوذ بوجه الله الكريم''',
    titleEn: r'''Refuge in Allah's Noble Face''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَعُوذُ بِوَجْهِكَ الكَريمِ ، وكَلِمَاتِكَ التَّامَّةِ مِن شَرِّ مَا أَنتَ آخِذٌ بِنَاصِيَتِهِ .''',
    transliteration: r'''Allāhumma innī a'ūdhu bi-wajhika al-karīmi, wa kalimātika at-tāmmati min sharri mā anta ākhidhun bi-nāṣiyatih.''',
    translationEn: r'''O Allah, I seek refuge in Your noble Face and Your perfect words from the evil of everything whose forelock is in Your grasp.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
