  AdhkarEntry(
    id: r'''allahumma_la_yuhzam_junduka''',
    category: AdhkarCategory.generalDhikr,
    titleAr: r'''لا يهزم جندك''',
    titleEn: r'''Your Army Is Never Defeated''',
    arabicText: r'''اللَّهُمَّ لا يُهْزَمُ جُندُكَ ، ولَا يُخْلَفُ وَعْدُكَ ، سُبْحَانَكَ وبِحَمْدِكَ .''',
    transliteration: r'''Allāhumma lā yuhzamu junduka, wa lā yukhlafu wa'duka, subḥānaka wa biḥamdik.''',
    translationEn: r'''O Allah, Your army is never defeated, and Your promise is never broken; glory be to You and praise.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
