  ),
  AdhkarEntry(
    id: r'''tahassantu_billah''',
    category: AdhkarCategory.protection,
    titleAr: r'''التحصن بالله''',
    titleEn: r'''Fortifying Oneself with Allah''',
    arabicText: r'''تَحَصَّنْتُ بِاللَّه الذِي لاَ إِلَهَ إِلَّا هُوَ ، إِلَهِي وإِلَهُ كُلِّ شَيءٍ ، واعتصمتُ بِرَبِّي وَرَبِّ كُلِّ شَيءٍ ، وتَوَكَّلْتُ عَلَى الحَيِّ الذي لا يَمُوتُ ، واستَدْفَعْتُ الشَّرَّ كُلَّهُ بِلاَ حَوْلَ ولا قُوَّةَ إِلَّا بِاللَّه العَلِيِّ العَظِيمِ .''',
    transliteration: r'''Taḥaṣṣantu billāhi alladhī lā ilāha illā huwa, ilāhī wa ilāhu kulli shay', wa'taṣamtu bi-Rabbī wa Rabbi kulli shay', wa tawakkaltu 'alā al-Ḥayyi alladhī lā yamūtu, wastadfa'tu ash-sharra kullahu bi-lā ḥawla wa lā quwwata illā billāhi al-'Aliyyi al-'Aẓīm.''',
    translationEn: r'''I have fortified myself with Allah, besides whom there is no god, my God and the God of all things; I have held fast to my Lord and the Lord of all things; I have relied upon the Ever-Living who does not die; and I have repelled all evil with "there is no power and no strength except with Allah, the Most High, the Most Great."''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''hasbiya_allah_wa_nima_al_wakil''',
    category: AdhkarCategory.generalDhikr,
    titleAr: r'''حسبي الله ونعم الوكيل''',
    titleEn: r'''Allah Is Sufficient for Me''',
    arabicText: r'''حَسْبِيَ اللَّه ونِعْمَ الوَكِيلُ ، حَسْبِيَ الرَّبُّ مِنَ العِبَادِ ، حَسْبِيَ الخَالِقُ مِنَ المَخْلُوقِينَ ، حَسْبِي الرَّازِقُ مِنَ المَرْزُوقِينَ ، حَسْبِيَ اللَّه وكَفَى ، سَمِعَ اللَّه لِمَن دَعَا ، لَيسَ وَرَاءَ اللَّه مُنْتَهَى ، لا إِلَهَ إِلَّا هُوَ عَلَيهِ تَوَكَّلْتُ ، وهُوَ رَبُّ العَرْشِ العَظِيمِ .''',
    transliteration: r'''Ḥasbiya Allāhu wa ni'ma al-Wakīl, ḥasbiya ar-Rabbu mina al-'ibād, ḥasbiya al-Khāliqu mina al-makhlūqīn, ḥasbiya ar-Rāziqu mina al-marzūqīn, ḥasbiya Allāhu wa kafā, sami'a Allāhu li-man da'ā, laysa warā'a Allāhi muntahā, lā ilāha illā huwa 'alayhi tawakkaltu, wa huwa Rabbu al-'Arshi al-'Aẓīm.''',
    translationEn: r'''Allah is sufficient for me, and He is the best Disposer of affairs; the Lord is sufficient for me among all servants; the Creator is sufficient for me among all creatures; the Provider is sufficient for me among all the provided; Allah is sufficient for me, and He suffices; Allah hears whoever calls upon Him; there is nothing beyond Allah; there is no god but He, upon Him I rely, and He is the Lord of the Mighty Throne.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''allahumma_ashku_ilayka_daf_quwwati''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء الطائف''',
    titleEn: r'''The Du'a of Ta'if (Complaint of Weakness)''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَشْكُو إِلَيكَ ضَعْفَ قُوَّتِي ، وقِلَّةَ حِيلَتِي ، وهَوَانِي عَلَى النَّاسِ ، بِرَحْمَتِكَ يَا رَبَّ العَالَمِينَ ، أَنتَ رَبُّ المُسْتَضْعَفِينَ وأَنتَ رَبِّي ، إِلَى مَن تَكِلُنِي ؟ إِلَى بَعِيدٍ يَتَجَهَّمُنِي ، أَو إِلَى عَدُوٍّ مَلَّكْتَهُ أَمْرِي ؟ إِن لَم يَكُن بِكَ غَضَبٌ عَلَيَّ فَلاَ أُبَالِي ، ولَكِنَّ عَافِيَتَكَ أَوْسَعُ لِي مِن دُنُوبِي . أَسأَلُكَ بِنُورِ وَجْهِكَ الذِي أَشْرَقَتْ لَهُ الظُّلُمَاتُ ، وَصَلَحَ عَلَيهِ أَمرُ الدُّنيا والآخِرَةِ ، مِن أَن يَحُلَّ بِي سَخَطُكَ ، أَو يَنْزِلَ عَلَيَّ عَذَابُكَ . لَكَ العُتْبَى حَتَّى تَرضَى . وَلاَ حَوْلَ وَلاَ قُوَّةَ إِلَّا بِكَ .''',
    transliteration: r'''Allāhumma innī ashkū ilayka ḍa'fa qūwatī, wa qillata ḥīlatī, wa hawānī 'alan-nās, bi-raḥmatika yā Rabba al-'ālamīn, anta Rabbu al-mustaḍ'afīna wa anta Rabbī, ilā man takilunī? ilā ba'īdin yatajahhamunī, aw ilā 'aduwwin mallaktahu amrī? in lam yakun bika ghaḍabun 'alayya falā ubālī, wa lākinna 'āfiyataka awsa'u lī min dhunūbī. As'aluka bi-nūri wajhika alladhī ashraqat lahu aẓ-ẓulumāt, wa ṣalaḥa 'alayhi amru ad-dunyā wal-ākhirah, min an yaḥulla bī sakhaṭuka, aw yanzila 'alayya 'adhābuk. Laka al-'utbā ḥattā tarḍā. Wa lā ḥawla wa lā quwwata illā bik.''',
    translationEn: r'''O Allah, to You I complain of my weakness, my lack of resources, and my insignificance before people. O Most Merciful, You are the Lord of the oppressed, and You are my Lord. To whom do You entrust me? To a distant one who will frown at me, or to an enemy to whom You have given power over my affairs? If You are not angry with me, I do not care, but Your relief is more expansive for me. I ask You by the light of Your Face, by which the darknesses are illuminated and by which the affairs of this world and the next are set right, that Your anger not descend upon me, nor Your wrath alight upon me. Yours is the right to be satisfied until You are pleased, and there is no power and no strength except with You.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''allahumma_allimni_ma_yanfauni''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء طلب العلم النافع''',
    titleEn: r'''Supplication for Beneficial Knowledge''',
    arabicText: r'''اللَّهُمَّ عَلِّمْني ما يَنْفَعُني ، وانْفَعْني بِمَا عَلَّمْتَني ، وَزِدْني عِلْمًا .''',
    transliteration: r'''Allāhumma 'allimnī mā yanfa'unī, wanfa'nī bimā 'allamtanī, wa zidnī 'ilmā.''',
    translationEn: r'''O Allah, teach me what benefits me, benefit me by what You have taught me, and increase me in knowledge.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''allahumma_ya_muallima_ibrahim''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''يا معلم إبراهيم''',
    titleEn: r'''O Teacher of Abraham, Teach Me''',
    arabicText: r'''اللَّهُمَّ يا مُعَلِّمَ إِبراهيم عَلِّمني ، ويا مُفَهِّمَ سُلَيمَان فَهِّمني .''',
    transliteration: r'''Allāhumma yā Mu'allima Ibrāhīma 'allimnī, wa yā Mufahhima Sulaymāna fahhimnī.''',
    translationEn: r'''O Allah, O Teacher of Abraham, teach me; O Giver of understanding to Solomon, grant me understanding.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''allahumma_ijal_li_wa_lil_muslimin_faraja''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء الفرج من الهم''',
    titleEn: r'''Supplication for Relief from Distress''',
    arabicText: r'''اللَّهُمَّ اجْعَلْ لي وللمُسلِمينَ مِن كُلِّ هَمٍّ فَرَجًا ، ومِن كُلِّ ضِيقٍ مَخرَجًا ، ومِن كُلِّ بَلاَءٍ عَافِيَةً .''',
    transliteration: r'''Allāhumma ij'al lī wa lil-muslimīna min kulli hammin farajan, wa min kulli ḍīqin makhrajan, wa min kulli balā'in 'āfiyah.''',
    translationEn: r'''O Allah, grant me and the Muslims relief from every distress, a way out from every hardship, and well-being from every trial.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
