    titleEn: r'''Placing Allah Against the Enemies' Onslaught''',
    arabicText: r'''اللَّهُمَّ إِنَّا نَدرَأُ بِكَ في نُحُورِهِمْ ، ونَعُوذُ بِكَ مِن شُرُورِهِمْ .''',
    transliteration: r'''Allāhumma innā nadra'u bika fī nuḥūrihim, wa na'ūdhu bika min shurūrihim.''',
    translationEn: r'''O Allah, we place You before us against their throats, and we seek refuge in You from their evils.''',
