  AdhkarEntry(
    id: r'''allahumma_ighfir_li_wa_liwalidayya''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء المغفرة للوالدين والمسلمين''',
    titleEn: r'''Forgiveness for Parents and All Muslims''',
    arabicText: r'''اللَّهُمَّ اغفِر لي ولِوَالِدَيَّ وللمُسلِمينَ والمُسلِمَاتِ والمُؤمِنينَ والمُؤمِنَاتِ ، الأَحيَاءِ مِنهُم والأَموَاتِ ، إِنَّكَ قَريبٌ مُجيبُ الدَّعَوَاتِ يَا رَبَّ العَالَمينَ .''',
    transliteration: r'''Allāhumma ighfir lī wa liwālidayya wa lil-muslimīna wal-muslimāti wal-mu'minīna wal-mu'mināt, al-aḥyā'i minhum wal-amwāt, innaka qarībun mujību ad-da'awāti yā Rabba al-'ālamīn.''',
    translationEn: r'''O Allah, forgive me, my parents, the Muslim men and women, and the believing men and women, the living among them and the dead; indeed You are Near, the Answerer of prayers, O Lord of the Worlds.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''allahumma_tahhir_qalbi_min_al_nifaq''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء تطهير القلب من النفاق''',
    titleEn: r'''Purifying the Heart from Hypocrisy''',
    arabicText: r'''اللَّهُمَّ طَهِّر قَلبي مِنَ النِّفَاقِ ، وعَمَلي مِنَ الرِّيَاءِ ، ولِسَاني مِنَ الكَذِبِ ، وعَيني مِنَ الخِيَانَةِ ، إِنَّكَ تَعلَمُ خَائِنَةَ الأَعينِ وما تُخفِي الصُّدُورُ .''',
    transliteration: r'''Allāhumma ṭahhir qalbī mina an-nifāq, wa 'amalī mina ar-riyā', wa lisānī mina al-kadhib, wa 'aynī mina al-khiyānah, innaka ta'lamu khā'inata al-a'yuni wa mā tukhfī aṣ-ṣudūr.''',
    translationEn: r'''O Allah, purify my heart of hypocrisy, my deeds of ostentation, my tongue of lying, and my eye of treachery; indeed You know the treachery of the eyes and what the breasts conceal.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''allahumma_asaluka_nafsan_mutmainnah''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء النفس المطمئنة''',
    titleEn: r'''Supplication for a Tranquil Soul''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَسأَلُكَ نَفسًا مُطمَئِنَّةً تُؤمِنُ بِلِقَائِكَ ، وتَقنَعُ بِعَطَائِكَ ، وتَرضَى بِقَضَائِكَ .''',
    transliteration: r'''Allāhumma innī as'aluka nafsan muṭma'innatan tu'minu bi-liqā'ika, wa taqna'u bi-'aṭā'ika, wa tarḍā bi-qaḍā'ik.''',
    translationEn: r'''O Allah, I ask You for a tranquil soul that believes in meeting You, is content with Your giving, and is pleased with Your decree.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''allahumma_innaka_talamu_sirri_wa_alaniyati''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اقبل معذرتي وأعطني سؤلي''',
    titleEn: r'''Supplication Knowing One's Secret and Need''',
    arabicText: r'''اللَّهُمَّ إِنَّكَ تَعلَمُ سِرِّي وعَلاَنِيَتي ، فَاقبَل مَعذِرَتي ، وتَعلَمُ حَاجَتي ، فَأَعطِني سُؤلي .''',
    transliteration: r'''Allāhumma innaka ta'lamu sirrī wa 'alāniyatī, faqbal ma'dhiratī, wa ta'lamu ḥājatī, fa-a'ṭinī su'lī.''',
    translationEn: r'''O Allah, You know my secret and my open affairs, so accept my excuse; You know my need, so grant me my request.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
