  ),
  AdhkarEntry(
    id: r'''allahumma_asaluka_imanan_yubashiru_qalbi''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء اليقين الصادق''',
    titleEn: r'''Supplication for True Faith and Certainty''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَسأَلُكَ إِيمَانًا يُبَاشِرُ قَلبي ، ويَقينًا صَادِقًا ، حَتَّى أَعلَمَ أَنَّهُ لَن يُصيبَني إِلَّا ما كَتَبتَ لي ، وأَنَّ ما أَصَابَني لَم يَكُن لِيُخطِئَني ، وَمَا أَخطَأَني لَم يَكُن لِيُصيبَني .''',
    transliteration: r'''Allāhumma innī as'aluka īmānan yubāshiru qalbī, wa yaqīnan ṣādiqan, ḥattā a'lama annahu lan yuṣībanī illā mā katabta lī, wa anna mā aṣābanī lam yakun liyukhṭi'anī, wa mā akhṭa'anī lam yakun liyuṣībanī.''',
    translationEn: r'''O Allah, I ask You for a faith that takes hold of my heart, and a true certainty, so that I may know that nothing will befall me except what You have decreed for me, and that whatever has befallen me was never going to miss me, and whatever has missed me was never going to befall me.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
