    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء الإيمان والنور والرزق''',
    titleEn: r'''Supplication for Faith, Light, and Lawful Provision''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَسأَلُكَ إِيمَانًا أَهتَدي بِه ، ونُورًا أَقتَدي بِه ، ورِزقًا حَلاَلًا أَكتَفِي بِه .''',
    transliteration: r'''Allāhumma innī as'aluka īmānan ahtadī bih, wa nūran aqtadī bih, wa rizqan ḥalālan aktafī bih.''',
    translationEn: r'''O Allah, I ask You for faith by which I am guided, a light by which I am led, and lawful provision that suffices me.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
