  AdhkarEntry(
    id: r'''allahumma_ijalni_uhibbuka_bi_qalbi_kullih''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء محبة الله''',
    titleEn: r'''Supplication for Love of Allah''',
    arabicText: r'''اللَّهُمَّ اجعَلني أُحِبُّكَ بِقَلبي كُلِّه ، وأَرضِيكَ بِجَهدي كُلِّه .''',
    transliteration: r'''Allāhumma ij'alnī uḥibbuka bi-qalbī kullih, wa arḍīka bi-jahdī kullih.''',
    translationEn: r'''O Allah, make me love You with the whole of my heart, and please You with all of my effort.''',
