    titleEn: r'''All My Love for You''',
    arabicText: r'''اللَّهُمَّ اجعَل حُبِّي لَكَ كُلَّهُ وسَعيي كُلَّهُ في مَرضَاتِكَ .''',
    transliteration: r'''Allāhumma ij'al ḥubbī laka kullahu wa sa'yī kullahu fī marḍātik.''',
