  AdhkarEntry(
    id: r'''allahumma_ma_zawayta_anni_mimma_uhibb''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''ما زويت عني فاجعله قوة''',
    titleEn: r'''Turning What Is Withheld into Strength''',
    arabicText: r'''اللَّهُمَّ ما زَوَيتَ عَنِّي مِمَّا أُحِبُّ ، فَاجعَلهُ قُوَّةً لي فيمَا تُحِبُّ ، واجعَلني لَكَ كَمَا تُحِبُّ .''',
    transliteration: r'''Allāhumma mā zawayta 'annī mimmā uḥibbu, fa-ij'alhu qūwatan lī fīmā tuḥibbu, waj'alnī laka kamā tuḥibb.''',
    translationEn: r'''O Allah, whatever You have withheld from me of what I love, make it a strength for me in what You love, and make me for You as You love.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''allahumma_ihfazni_bil_islam''',
    category: AdhkarCategory.protection,
    titleAr: r'''دعاء الحفظ بالإسلام''',
    titleEn: r'''Protection Through Islam''',
    arabicText: r'''اللَّهُمَّ احفَظني بِالإِسلاَمِ قَائِمًا وقَاعِدًا وَرَاقِدًا ، وَلاَ تُشمِت بي عَدُوًّا وَلاَ حَاسِدًا .''',
    transliteration: r'''Allāhumma iḥfaẓnī bil-Islāmi qā'iman wa qā'idan wa rāqidā, wa lā tushmit bī 'aduwwan wa lā ḥāsidā.''',
    translationEn: r'''O Allah, protect me with Islam while standing, sitting, and lying down, and do not let an enemy or an envier gloat over me.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''allahumma_bi_ilmika_al_ghayb''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''بعلمك الغيب أحيني وتوفني''',
    titleEn: r'''By Your Knowledge of the Unseen''',
    arabicText: r'''اللَّهُمَّ بِعِلمِكَ الغَيبَ ، وقُدرَتِكَ عَلَى الخَلقِ أَحيِني ما زَالَتِ الحَيَاةُ خَيرًا لي ، وتَوَفَّني إِذَا كَانَتِ الوَفَاةُ خَيرًا لي .''',
    transliteration: r'''Allāhumma bi-'ilmika al-ghayba, wa qudratika 'alā al-khalqi aḥyinī mā zālati al-ḥayātu khayran lī, wa tawaffanī idhā kānati al-wafātu khayran lī.''',
    translationEn: r'''O Allah, by Your knowledge of the unseen, and Your power over creation, keep me alive as long as life is good for me, and take my life when death is better for me.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''allahumma_asaluka_khashyataka_fi_al_ghayb_wa_al_shahadah''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء خشية الله في الغيب والشهادة''',
    titleEn: r'''Supplication for Fear of Allah, Always''',
    arabicText: r'''اللَّهُمَّ إِنِّي أَسأَلُكَ خَشيَتَكَ في الغَيبِ والشَّهَادَةِ ، وَكَلِمَةَ الحَقِّ في الغَضَبِ والرِّضَى ، والقَصدَ في الفَقرِ والغِنَى ، وَأَسأَلُكَ نَعيمًا لاَ يَنفَدُ ، وقُرَّةَ عَينٍ لاَ تَنقَطِعُ .''',
    transliteration: r'''Allāhumma innī as'aluka khashyataka fil-ghaybi wash-shahādah, wa kalimata al-ḥaqqi fil-ghaḍabi war-riḍā, wal-qaṣda fil-faqri wal-ghinā, wa as'aluka na'īman lā yanfadu, wa qurrata 'aynin lā tanqaṭi'.''',
    translationEn: r'''O Allah, I ask You for fear of You in private and in public, for a word of truth in anger and in pleasure, for moderation in poverty and in wealth, and I ask You for bliss that never ends, and for comfort of the eye that never ceases.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''subhan_allah_mila_al_mizan''',
    category: AdhkarCategory.generalDhikr,
    titleAr: r'''سبحان الله ملء الميزان''',
    titleEn: r'''Glory to Allah, Filling the Scale''',
    arabicText: r'''سُبحَانَ اللَّه مِلْءَ الميزَانِ ، ومُنتَهَى العِلمِ ، ومَبلَغَ الرِّضَى ، وَزِنَةَ العَرشِ . وَلاَ إِلَهَ إِلَّا اللَّه مِلْءَ الميزَانِ ، ومُنتَهَى العِلمِ ، ومَبلَغَ الرِّضَى ، وَزِنَةَ العَرشِ ، واللَّهُ أَكبَرُ مِلْءَ الميزَانِ ، ومُنتَهَى العِلمِ ، ومَبلَغَ الرِّضَى ، وَزِنَةَ العَرشِ .''',
    transliteration: r'''Subḥāna Allāhi mil'a al-mīzāni, wa muntahā al-'ilmi, wa mablagha ar-riḍā, wa zinata al-'arsh. Wa lā ilāha illā Allāhu mil'a al-mīzāni, wa muntahā al-'ilmi, wa mablagha ar-riḍā, wa zinata al-'arsh. Wallāhu akbaru mil'a al-mīzāni, wa muntahā al-'ilmi, wa mablagha ar-riḍā, wa zinata al-'arsh.''',
    translationEn: r'''Glory be to Allah, filling the scale, reaching the utmost extent of knowledge, attaining the fullness of pleasure, and weighing as much as the Throne. And there is no god but Allah, filling the scale, reaching the utmost extent of knowledge, attaining the fullness of pleasure, and weighing as much as the Throne. And Allah is greatest, filling the scale, reaching the utmost extent of knowledge, attaining the fullness of pleasure, and weighing as much as the Throne.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 3,
    repetitionNote: r'''the tasbih formula ("مِلْءَ الميزَانِ ، ومُنتَهَى العِلمِ ، ومَبلَغَ الرِّضَى ، وَزِنَةَ العَرشِ") is explicitly repeated three times, once each after سبحان الله / ولا إله إلا الله / والله أكبر''',
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''allahumma_kama_latafta_biazamatik''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم كما لطفت بعظمتك''',
    titleEn: r'''O Allah, By Your Gentleness in Greatness''',
    arabicText: r'''اللَّهُمَّ كَمَا لَطَفتَ بِعَظَمَتِكَ دُونَ اللُّطَفَاءِ ، وعَلَوتَ بِعَظَمَتِكَ عَلَى العُظَمَاءِ ، وعَلِمتَ مَا تَحتَ أَرضِكَ كَعِلمِكَ بِمَا فَوقَ عَرشِكَ ، وكَانَت وَسَاوِسُ الصُّدُورِ كَالعَلاَنِيَةِ عِندَكَ ، وعَلاَنِيَةُ القَولِ كَالسِّرِّ في عِلمِكَ ، وانقَادَ كُلُّ شَيءٍ لِعَظَمَتِكَ ، وخَضَعَ كُلُّ سُلطَانٍ لِسُلطَانِكَ ، وصَارَ أَمرُ الدُّنيا والآخِرَةِ كُلُّهُ بِيَدَيكَ ، اجعَل لي مِن كُلِّ هَمٍّ وَغَمٍّ أَصبَحتُ فيهِ فَرَجًا ومَخرَجًا .''',
    transliteration: r'''Allāhumma kamā laṭafta bi-'aẓamatika dūna al-luṭafā', wa 'alawta bi-'aẓamatika 'alā al-'uẓamā', wa 'alimta mā taḥta arḍika ka-'ilmika bimā fawqa 'arshik, wa kānat wasāwisu aṣ-ṣudūri kal-'alāniyati 'indak, wa 'alāniyatu al-qawli kas-sirri fī 'ilmik, wan-qāda kullu shay'in li-'aẓamatik, wa khaḍa'a kullu sulṭānin li-sulṭānik, wa ṣāra amru ad-dunyā wal-ākhirati kulluhu bi-yadayk, ij'al lī min kulli hammin wa ghammin aṣbaḥtu fīhi farajan wa makhrajā.''',
    translationEn: r'''O Allah, just as You are gentle in Your greatness beyond all the gentle, and exalted in Your greatness above all the great, and You know what is beneath Your earth as You know what is above Your Throne, and the whisperings of hearts are to You as the open word, and the open word is to Your knowledge as the secret, and everything submits to Your greatness, and every authority yields to Your authority, and the affairs of this world and the next are entirely in Your hands — grant me, from every anxiety and sorrow in which I find myself, relief and a way out.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''allahumma_inna_afwaka_an_dhunubi''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم إن عفوك عن ذنوبي''',
    titleEn: r'''O Allah, Your Pardon for My Sins''',
    arabicText: r'''اللَّهُمَّ إِنَّ عَفوَكَ عَن ذُنُوبي ، وتَجَاوُزَكَ عَن خَطِيئَتي ، أَطمَعَني أَن أَسأَلَكَ مَا لاَ أَستَوجِبُهُ مِمَّا قَصَّرتُ فيهِ ، أَدعُوكَ آمِنًا ، وَأَسأَلُكَ مُستَأنِسًا . وإِنَّكَ لَلمُحسِنُ إِلَيَّ ، وإِنِّي لَلمُسيءُ إِلَى نَفسِي ، فيما بَيني وبَينَكَ ، تَتَوَدَّدُ إِلَيَّ بِالنِّعَمِ ، وَأَتَبَغَّضُ إِلَيكَ بِالمَعَاصِي ، ولَكِنَّ الثِّقَةَ بِكَ حَمَلَتني عَلَى الجَرَاءَةِ عَلَيكَ ، فَعُدْ بِفَضلِكَ وإِحسَانِكَ عَلَيَّ ؛ إِنَّكَ أَنتَ التَّوَّابُ الرَّحيمُ . لاَ إِلَهَ غَيرُكَ ، والبَديعُ لَيسَ قَبلَكَ شَيءٌ ، والدَّائِمُ غَيرُ الغَافِلِ ، والذِي لاَ يَمُوتُ ، وخَالِقُ مَا يُرَى وَمَا لاَ يُرَى ، وكُلَّ يَومٍ في شَأنٍ ، وَسِعَتَ اللَّهُمَّ كُلَّ شَيءٍ رَحمَةً وعِلمًا ، يَا رَحمَانُ يَا رَحيمُ ، يَا حَليمُ يا كَريمُ ، يَا أَحَدُ يَا صَمَدُ ، يَا حَيُّ يَا مُحيِي ، يَا حَيُّ يَا قَيُّومُ ، لاَ إِلَهَ إِلَّا أَنتَ يَا رَبَّنَا ، إِنَّا عَبيدُكَ وفي سَبيلِكَ ، اجعَل لَنَا السَّبيلَ إِلَى كُلِّ خَيرٍ .''',
    transliteration: r'''Allāhumma inna 'afwaka 'an dhunūbī, wa tajāwuzaka 'an khaṭī'atī, aṭma'anī an as'aluka mā lā astawjibuhu mimmā qaṣṣartu fīh, ad'ūka āminan, wa as'aluka musta'nisā. Wa innaka lal-muḥsinu ilayya, wa innī lal-musī'u ilā nafsī, fīmā baynī wa baynak, tatawaddadu ilayya bin-ni'am, wa atabaghghaḍu ilayka bil-ma'āṣī, wa lākinna ath-thiqata bika ḥamalatnī 'alā al-jarā'ati 'alayk, fa-'ud bi-faḍlika wa iḥsānika 'alayya; innaka anta at-Tawwābu ar-Raḥīm. Lā ilāha ghayruk, wal-Badī'u laysa qablaka shay', wad-Dā'imu ghayru al-ghāfil, wal-ladhī lā yamūt, wa Khāliqu mā yurā wa mā lā yurā, wa kulla yawmin fī sha'n, wasi'ta Allāhumma kulla shay'in raḥmatan wa 'ilmā, yā Raḥmānu yā Raḥīm, yā Ḥalīmu yā Karīm, yā Aḥadu yā Ṣamad, yā Ḥayyu yā Muḥyī, yā Ḥayyu yā Qayyūm, lā ilāha illā anta yā Rabbanā, innā 'abīduka wa fī sabīlik, ij'al lanā as-sabīla ilā kulli khayr.''',
    translationEn: r'''O Allah, indeed Your pardon for my sins, and Your overlooking my faults, has emboldened me to ask You for what I do not deserve because of my shortcomings. I call upon You feeling secure, and I ask You feeling at ease, for indeed You are the One who does good to me, while I am the one who wrongs myself; between me and You, You show me affection through Your blessings, while I show hostility toward You through disobedience — yet trust in You has carried me to boldness before You. So return upon me with Your favor and kindness, for indeed You are the Ever-Relenting, the Merciful. There is no god besides You, the Originator before whom there was nothing, the Everlasting who is never heedless, who never dies, the Creator of what is seen and unseen; every day You are engaged in some affair. O Allah, Your mercy and knowledge encompass all things. O Most Gracious, O Most Merciful, O Most Forbearing, O Most Generous, O the One, O the Self-Sufficient Master, O Ever-Living, O Giver of life, O Ever-Living, O Sustainer of all — there is no god but You, O our Lord. We are Your servants, and in Your path; make for us the way to every good.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''allahumma_habbib_alayya_ibadaka''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''دعاء محبة الناس''',
    titleEn: r'''Supplication for the Love of People''',
    arabicText: r'''اللَّهُمَّ حَبِّب عَلَيَّ عِبَادَكَ وإِمَاءَكَ ، وَأَغنِني عَن شِرَارِ عِبَادِكَ يا أَرحَمَ الرَّاحِمِينَ .''',
    transliteration: r'''Allāhumma ḥabbib 'alayya 'ibādaka wa imā'ak, wa aghninī 'an shirāri 'ibādika yā Arḥama ar-Rāḥimīn.''',
    translationEn: r'''O Allah, make Your male and female servants love me, and make me independent of the wicked among Your servants, O Most Merciful of the merciful.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''ya_wadud_ya_dha_al_arsh_al_majid''',
    category: AdhkarCategory.protection,
    titleAr: r'''يا مغيث أغثني''',
    titleEn: r'''O Helper, Help Me''',
    arabicText: r'''يَا وَدُودُ ، يَا ذَا العَرشِ المَجيدِ ، يَا فَعَّالًا لِمَا يُريدُ ، أَسأَلُكَ بِعِزَّكَ الذِي لاَ يُرَامُ ، وبِمُلكِكَ الذِي لاَ يُضَامُ ، وبِنُورِكَ الذِي مَلَأَ أَركَانَ عَرشِكَ ، أَن تَكفِيَني شَرَّ كَذَا وَكَذَا ، يَامُغيثُ أَغِثني ، يَامُغيثُ أَغِثني ، يَامُغيثُ أَغِثني .''',
    transliteration: r'''Yā Wadūd, yā Dhā al-'Arshi al-Majīd, yā Fa''ālan limā yurīd, as'aluka bi-'izzika alladhī lā yurām, wa bi-mulkika alladhī lā yuḍām, wa bi-nūrika alladhī mala'a arkāna 'arshik, an takfiyanī sharra kadhā wa kadhā, yā Mughīthu aghithnī, yā Mughīthu aghithnī, yā Mughīthu aghithnī.''',
    translationEn: r'''O Most Loving, O Possessor of the Glorious Throne, O Doer of what He wills, I ask You by Your might that cannot be overcome, by Your dominion that cannot be wronged, and by Your light that fills the corners of Your Throne, that You spare me the evil of such-and-such. O Helper, help me; O Helper, help me; O Helper, help me.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 3,
    repetitionNote: r'''"يا مغيث أغثني" is explicitly repeated three times consecutively in the printed text''',
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''bismillah_al_rahman_al_rahim_an_yamini''',
    category: AdhkarCategory.protection,
    titleAr: r'''بسم الله من كل جانب''',
    titleEn: r'''Basmalah for Protection from Every Side''',
    arabicText: r'''بِسمِ اللَّه الرَّحمَنِ الرَّحيمِ عَن يَميني ، بِسمِ اللَّه الرَّحمَنِ الرَّحيمِ عَن شِمَالي ، بِسمِ اللَّه الرَّحمَنِ الرَّحيمِ بَينَ يَدَيَّ ، بِسمِ اللَّه الرَّحمَنِ الرَّحيمِ مِن خَلفِي ، بِسمِ اللَّه الرَّحمَنِ الرَّحيمِ مِن فَوقِي ، بِسمِ اللَّه الرَّحمَنِ الرَّحيمِ مِن جَميعِ جَوَانِبِي ، بِسمِ اللَّه الرَّحمَنِ الرَّحيمِ قَابِضٌ عَلَيَّ نَاصِيَتي .''',
    transliteration: r'''Bismillāhi ar-Raḥmāni ar-Raḥīmi 'an yamīnī, bismillāhi ar-Raḥmāni ar-Raḥīmi 'an shimālī, bismillāhi ar-Raḥmāni ar-Raḥīmi bayna yadayya, bismillāhi ar-Raḥmāni ar-Raḥīmi min khalfī, bismillāhi ar-Raḥmāni ar-Raḥīmi min fawqī, bismillāhi ar-Raḥmāni ar-Raḥīmi min jamī'i jawānibī, bismillāhi ar-Raḥmāni ar-Raḥīmi qābiḍun 'alayya nāṣiyatī.''',
    translationEn: r'''In the name of Allah, the Most Gracious, the Most Merciful, on my right; in the name of Allah, the Most Gracious, the Most Merciful, on my left; in the name of Allah, the Most Gracious, the Most Merciful, before me; in the name of Allah, the Most Gracious, the Most Merciful, behind me; in the name of Allah, the Most Gracious, the Most Merciful, above me; in the name of Allah, the Most Gracious, the Most Merciful, on all my sides; in the name of Allah, the Most Gracious, the Most Merciful, holding my forelock.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: r'''"بسم الله الرحمن الرحيم" is repeated at the start of each of the seven directional clauses — a fixed protective formula, not a simple numeric repeat instruction''',
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''audhu_bi_izzat_allah_wa_azamatih''',
    category: AdhkarCategory.protection,
    titleAr: r'''أعوذ بعزة الله وعظمته''',
    titleEn: r'''Refuge in the Might and Greatness of Allah''',
    arabicText: r'''أَعُوذُ بِعِزَّةِ اللَّه وعَظَمَتِهِ ، وبِعِزَّةِ اللَّه وقُدرَتِهِ ، وبِعِزَّةِ اللَّه وسُلطَانِهِ ، وبِعِزِّ جَلاَلِ اللَّهِ ، وبِعِزِّ اللَّه مِن شَرِّ مَا خَلَقَ وذَرَأَ وبَرَأَ ، ومِن شَرِّ مَا تَحتَ الثَّرَى ، ومِن شَرِّ كُلِّ دَابَّةٍ رَبِّي آخِذٌ بِنَاصِيَتِهَا ، إِنَّ رَبِّي عَلَى صِرَاطٍ مُستَقيمٍ ، وَلاَ حَولَ وَلاَ قُوَّةَ إِلَّا بِاللَّه العَلِيِّ العَظيمِ ، مَلجَأً كُلِّ هَارِبٍ ، ومَأوَى كُلِّ خَائِفٍ .''',
    transliteration: r'''A'ūdhu bi-'izzati Allāhi wa 'aẓamatih, wa bi-'izzati Allāhi wa qudratih, wa bi-'izzati Allāhi wa sulṭānih, wa bi-'izzi jalāli Allāh, wa bi-'izzi Allāhi min sharri mā khalaqa wa dhara'a wa bara'a, wa min sharri mā taḥta ath-tharā, wa min sharri kulli dābbatin Rabbī ākhidhun bi-nāṣiyatihā, inna Rabbī 'alā ṣirāṭin mustaqīm, wa lā ḥawla wa lā quwwata illā billāhi al-'Aliyyi al-'Aẓīm, malja'an kulli hārib, wa ma'wā kulli khā'if.''',
    translationEn: r'''I seek refuge in the might of Allah and His greatness, in the might of Allah and His power, in the might of Allah and His authority, in the might of Allah's majesty, and in the might of Allah from the evil of what He has created, formed, and brought into being, from the evil of what is beneath the soil, and from the evil of every creature whose forelock my Lord holds — indeed my Lord is upon a straight path — and there is no power and no strength except with Allah, the Most High, the Most Great, the refuge of every fugitive, and the shelter of every fearful one.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''la_hawla_wa_la_quwwata_aqi_biha_nafsi''',
    category: AdhkarCategory.generalDhikr,
    titleAr: r'''أقي بها نفسي وديني''',
    titleEn: r'''Protecting Self, Faith, Family, and Wealth''',
    arabicText: r'''لاَ حَولَ وَلاَ قُوَّةَ إِلَّا بِالل

ARABIC: لاَ حَولَ وَلاَ قُوَّةَ إِلَّا بِاللَّه العَلِيِّ العَظيمِ أَقِي بِهَا نَفسِي وَديني وَأَهلي ومَالي وجَميعَ نِعَمِ إِلَهي ومَولاَيَ وسَيِّدي عِندِي .''',
    transliteration: r'''Lā ḥawla wa lā quwwata illā billāhi al-'Aliyyi al-'Aẓīm, aqī bihā nafsī wa dīnī wa ahlī wa mālī wa jamī'a ni'ami ilāhī wa mawlāya wa sayyidī 'indī.''',
    translationEn: r'''There is no power and no strength except with Allah, the Most High, the Most Great — with it I protect myself, my religion, my family, my wealth, and all the blessings of my God, my Master, and my Lord that are with me.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''la_hawla_wa_la_quwwata_anju_biha_min_iblis''',
    category: AdhkarCategory.generalDhikr,
    titleAr: r'''النجاة من إبليس وجنوده''',
    titleEn: r'''Deliverance from Iblis and His Forces''',
    arabicText: r'''لاَحَولَ ولا قُوَّةَ إِلَّا بِاللَّه العَلِيِّ العَظيمِ ، أَنجُو بِهَا مِن إِبليسَ وخَيلِهِ ورَجلِهِ وشَيَاطينِهِ ومَرَدَتِهِ وأَلوَانِهِ ، وجَميعِ الإِنسِ والجِنِّ وشُرورِهِمْ .''',
    transliteration: r'''Lā ḥawla wa lā quwwata illā billāhi al-'Aliyyi al-'Aẓīm, anjū bihā min Iblīsa wa khaylihi wa rajlihi wa shayāṭīnihi wa maradatihi wa alwānih, wa jamī'i al-insi wal-jinni wa shurūrihim.''',
    translationEn: r'''There is no power and no strength except with Allah, the Most High, the Most Great — with it I am saved from Iblis, his cavalry and his infantry, his devils, his rebellious ones and his various kinds, and from all mankind and jinn and their evils.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''la_hawla_wa_la_quwwata_amtaniu_biha_min_zulm''',
    category: AdhkarCategory.generalDhikr,
    titleAr: r'''الامتناع من ظلم الظالم''',
    titleEn: r'''Warding Off the Wrong of Oppressors''',
    arabicText: r'''لاَ حَولَ وَلاَ قُوَّةَ إِلَّا بِاللَّه العَلِيِّ العَظيمِ أَمتَنِعُ بِهَا مِن ظُلمِ مَن أَرَادَ ظُلمِي مِن جَميعِ خَلقِ اللَّه .''',
    transliteration: r'''Lā ḥawla wa lā quwwata illā billāhi al-'Aliyyi al-'Aẓīm, amtani'u bihā min ẓulmi man arāda ẓulmī min jamī'i khalqi Allāh.''',
    translationEn: r'''There is no power and no strength except with Allah, the Most High, the Most Great — with it I protect myself from the wrong of whoever intends to wrong me among all of Allah's creation.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''la_hawla_wa_la_quwwata_ataasu_biha_juhd''',
    category: AdhkarCategory.generalDhikr,
    titleAr: r'''إتعاس من بغى علي''',
    titleEn: r'''Confounding the Transgressor's Effort''',
    arabicText: r'''لاَ حَولَ وَلاَ قُوَّةَ إِلَّا بِاللَّه العَلِيِّ العَظيمِ ، أَتَعَسُ بِهَا جُهدَ مَن بَغَى عَلَيَّ مِن جَميعِ خَلقِ اللَّه .''',
    transliteration: r'''Lā ḥawla wa lā quwwata illā billāhi al-'Aliyyi al-'Aẓīm, ata'asu bihā juhda man baghā 'alayya min jamī'i khalqi Allāh.''',
    translationEn: r'''There is no power and no strength except with Allah, the Most High, the Most Great — with it I make wretched the effort of whoever transgresses against me among all of Allah's creation.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''la_hawla_wa_la_quwwata_akuffu_biha_udwan''',
    category: AdhkarCategory.generalDhikr,
    titleAr: r'''كف عدوان المعتدي''',
    titleEn: r'''Restraining the Aggressor's Aggression''',
    arabicText: r'''لاَ حَولَ وَلاَ قُوَّةَ إِلَّا بِاللَّه العَلِيِّ العَظيمِ ، أَكُفُّ بِهَا عُدوَانَ مَن اعتَدَى عَلَيَّ مِن جَميعِ خَلقِ اللَّه .''',
