  AdhkarEntry(
    id: r'''fatahu_bab_alsabr''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم اجعلنا من الذين فتحوا باب الصبر''',
    titleEn: r'''Those Who Opened the Door of Patience''',
    arabicText: r'''اللَّهُمَّ اجْعَلْنا مِنَ الَّذين فَتَحُوا بابَ الصَّبْرِ ، وأَرْدَمُوا خَنَادِقَ الجَزَعِ ، وجَازُوا شَدِيدَ العِقَابِ ، وعَبَرُوا جِسْرَ الهَوَى .''',
    transliteration: r'''Allāhumma ij'alnā mina alladhīna fataḥū bāba aṣ-ṣabr, wa ardamū khanādiqa al-jaza', wa jāzū shadīda al-'iqāb, wa 'abarū jisra al-hawā.''',
    translationEn: r'''O Allah, make us among those who opened the door of patience, filled in the trenches of despair, crossed over the severity of punishment, and passed over the bridge of desire.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''asharat_ilayhim_a'lam_alhidaya''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم اجعلنا من الذين أشارت إليهم أعلام الهداية''',
    titleEn: r'''Guided by the Signposts of Guidance''',
    arabicText: r'''اللَّهُمَّ اجْعَلْنَا مِنَ الذين أَشَارَتْ إليهم أَعْلامُ الهِدَايَة ، وَوَضَحَتْ لَهُمْ طَريقُ النَّجَاةِ ، وسَلَكُوا سَبِيلَ الإخْلاصِ واليَقِـين .''',
    transliteration: r'''Allāhumma ij'alnā mina alladhīna ashārat ilayhim a'lāmu al-hidāyah, wa waḍaḥat lahum ṭarīqu an-najāh, wa salakū sabīla al-ikhlāṣi wal-yaqīn.''',
    translationEn: r'''O Allah, make us among those to whom the signposts of guidance pointed, for whom the path of salvation became clear, and who followed the way of sincerity and certainty.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''arrifni_bika_wabinafsi''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم عرفني بك وبنفسي''',
    titleEn: r'''Grant Me Knowledge of You and Myself''',
    arabicText: r'''اللَّهُمَّ عَرِّفْنِي بِكَ وبِنَفْسِي ، واجْعَلْنِي مِنْ أَعْرَفِ عِبَادِكَ بِكَ وَبِنَفْسِهِ .''',
    transliteration: r'''Allāhumma 'arrifnī bika wa bi-nafsī, wa ij'alnī min a'rafi 'ibādika bika wa bi-nafsih.''',
    translationEn: r'''O Allah, make me know You and know myself, and make me among the most knowing of Your servants of You and of himself.''',
