  AdhkarEntry(
    id: r'''inna_nafsi_ammaratun_bissu''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''إن نفسي أمارة بالسوء''',
    titleEn: r'''My Soul Commands Me to Evil''',
    arabicText: r'''اللَّهُمَّ إنَّ نَفْسِي أَمَّارَةٌ بالسُّوءِ ، والشَّيْطَانُ يُوقِعُني كُلَّ سَاعَةَ في خَطِيئَةٍ من الكَبَائِرِ ، فضلاً عن الصَّغَائِرِ ، وإنِّي أُريدُ نَزْعَ نَفْسِي من نَزْغِهِ ، ولا أستطيع حَتَّى تُوَفِّقَنِي ، فَإنَّ بِيدِكَ الخَيْرَ ، والشَّرُّ لَيْسَ إلَيكَ ، فاغْفِرْ لي وتُبْ عَلَيَّ ، ولا تُزِغْ قَلْبِي بَعْدَ إذْ هَدَيْتَنِي ، وامنَحْني عِلمًا بالكِتَابِ والسُّنَّة ، وإنْ لَمْ تَرْحَمْنِي وتَغْفِرْ لِي أَكُنْ من الخَاسِرِينَ ، فاهْدني سَوَاءَ السَّبِيلِ ، واغْفِرْ لي مَغْفِرَةً تَامَّةً ، واعْفُ عَنِّي ، فإنَّكَ عَفُوٌّ تُحِبُّ العَفْوَ ، وارْزُقْنِي العَافِيَةَ فِي الدِّين والدُّنْيَا والآخِرَةِ وما ذَلك عَليكَ بِعَزِيزٍ ، يا أَرْحَمَ الرَّاحِمِينَ ، يالَطِيفُ يالَطِيفُ ، الْطُفْ بي بِلُطْفِكَ الخَفِيِّ يا لَطِيفُ ، بالقُدْرَةِ التي استَوَيْتَ بها عَلى العَرْشِ ، فَلَم يَعْلَمْ أَحَدٌ كَيفِيَّةَ استوائِكَ عَليه ، اكْفِنِي شَرَّ كُلِّ شِرِّير ، يا مَنْ كَانَ قَبلَ أَنْ يَكونَ شَيءٌ ، وهو المُكَوِّنُ لِكُلِّ شَيءٍ ، ومن يكون بَعْدَ ما لا يكون شَيءٌ ، أَسأَلُكَ بَلَحْظَةٍ من لَحَظَاتِكَ الحَافِظَاتِ الغَافِرَاتِ ، الرَّاحمات المُنجيات ، يا ذَا الجَلالِ والإكْرَام ، يا ذَا الطَّوْلِ والإنعام ، لا إلَه إلَّا أنتَ رَبَّ العَالمين ، أَرْحَمَ الرَّاحمين ، الحَنَّانَ المَنَّانَ ، بَديعَ السَّمَاوَاتِ والأرض ، رَبَّ العَرْشِ العَظيم .''',
    transliteration: r'''Allāhumma inna nafsī ammāratun bis-sū', wash-shayṭānu yūqi'unī kulla sā'atin fī khaṭī'atin mina al-kabā'ir, faḍlan 'ani aṣ-ṣaghā'ir, wa innī urīdu naz'a nafsī min nazghihi, wa lā astaṭī'u ḥattā tuwaffiqanī, fa-inna bi-yadika al-khayr, wash-sharru laysa ilayk, faghfir lī wa tub 'alayya, wa lā tuzigh qalbī ba'da idh hadaytanī, wa imnaḥnī 'ilman bil-kitābi was-sunnah, wa in lam tarḥamnī wa taghfir lī akun mina al-khāsirīn, fahdinī sawā'a as-sabīl, waghfir lī maghfiratan tāmmah, wa'fu 'annī, fa-innaka 'afuwwun tuḥibbu al-'afw, wa arzuqnī al-'āfiyata fīd-dīni wad-dunyā wal-ākhirah, wa mā dhālika 'alayka bi-'azīz, yā arḥama ar-rāḥimīn, yā laṭīfu yā laṭīf, ulṭuf bī bi-luṭfika al-khafiyyi yā laṭīf, bil-qudrati allatī istawayta bihā 'alā al-'arsh, falam ya'lam aḥadun kayfiyyata istiwā'ika 'alayh, ikfinī sharra kulli shirrīr, yā man kāna qabla an yakūna shay'un, wa huwa al-mukawwinu li-kulli shay', wa man yakūnu ba'da mā lā yakūnu shay', as'aluka bi-laḥẓatin min laḥaẓātika al-ḥāfiẓāti al-ghāfirāt, ar-rāḥimāti al-munjiyāt, yā dhāl-jalāli wal-ikrām, yā dhāṭ-ṭawli wal-in'ām, lā ilāha illā anta rabba al-'ālamīn, arḥama ar-rāḥimīn, al-ḥannāna al-mannān, badī'a as-samāwāti wal-arḍ, rabba al-'arshi al-'aẓīm.''',
    translationEn: r'''O Allah, indeed my soul commands to evil, and Satan casts me every hour into a sin from among the grave sins, let alone the minor ones. I wish to pull my soul away from his incitement, but I am unable until You grant me success, for in Your Hand is good, and evil is not attributed to You. So forgive me and accept my repentance, and do not let my heart swerve after You have guided me. Grant me knowledge of the Book and the Sunnah, and if You do not have mercy on me and forgive me, I will be among the losers. So guide me to the straight path, forgive me with a complete forgiveness, and pardon me, for You are Ever-Pardoning and love to pardon. Grant me well-being in religion, this world, and the Hereafter — that is not difficult for You. O Most Merciful of the merciful, O Gentle One, O Gentle One, be gentle with me with Your hidden gentleness, O Gentle One, by the power with which You rose over the Throne — no one knows the manner of Your rising over it — spare me the evil of every evildoer, O You who existed before anything came to be, and He is the Originator of all things, and who will remain after all things cease to be. I ask You by one of Your moments — the moments that protect, forgive, show mercy, and save — O Possessor of Majesty and Honor, O Possessor of Bounty and Favor, there is no god but You, Lord of the worlds, Most Merciful of the merciful, the Compassionate, the Bestower of favor, Originator of the heavens and earth, Lord of the Mighty Throne.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: r'''"يالَطِيفُ" appears repeated twice consecutively in the text as printed''',
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''allahumma_inni_abduka_ibnu_abdika''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم إني عبدك ابن عبدك ابن أمتك''',
    titleEn: r'''The Supplication of Ibn Mas'ud''',
    arabicText: r'''اللَّهُمَّ إنِّي عَبْدُكَ ، ابنُ عَبْدِكَ ، ابنُ أَمَتِكَ ، نَاصِيتي بِيَدِكَ ، مَاضٍ فِيَّ حُكْمُكَ ، عَدْلٌ فِيَّ قَضَاؤُكَ ، أَسأَلُكَ بِكُلِّ اسمٍ هُوَ لَكَ سَمَّيْتَ بِهِ نَفْسَكَ ، أو أَنْزَلْتَهُ في كِتَابِكَ ، أو عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ ، أو استَأْثَرْتَ بِه في عِلْمِ الغَيْبِ عِنْدَكَ أَنْ تَجْعَلَ القرآنَ العَظيمَ نورَ صَدْرِي ، ورَبيعَ قَلْبِي ، وجَلاءَ حُزْني ، وذَهابَ هَمِّي .''',
    transliteration: r'''Allāhumma innī 'abduka, ibnu 'abdika, ibnu amatika, nāṣiyatī bi-yadika, māḍin fiyya ḥukmuka, 'adlun fiyya qaḍā'uka, as'aluka bi-kulli ismin huwa laka sammayta bihi nafsak, aw anzaltahu fī kitābik, aw 'allamtahu aḥadan min khalqik, aw ista'tharta bihi fī 'ilmi al-ghaybi 'indak, an taj'ala al-qur'āna al-'aẓīma nūra ṣadrī, wa rabī'a qalbī, wa jalā'a ḥuznī, wa dhahāba hammī.''',
    translationEn: r'''O Allah, I am Your servant, son of Your servant, son of Your maidservant. My forelock is in Your Hand, Your judgment over me proceeds, and Your decree concerning me is just. I ask You by every name that is Yours, by which You have named Yourself, or which You have revealed in Your Book, or taught to any of Your creation, or which You have kept for Yourself in the knowledge of the unseen with You, to make the Mighty Qur'an the light of my chest, the spring of my heart, the banisher of my sorrow, and the reliever of my distress.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''ikhshaka_hatta_kaanni_araka''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم اجعلني أخشاك حتى كأني أراك''',
    titleEn: r'''Fear You As Though I See You''',
    arabicText: r'''اللَّهُمَّ اجْعَلْنِي أَخْشَاكَ حَتَّى كَأَنِّي أَرَاكَ ، وأَسْعِدْني بِتَقْوَاكَ ، ولا تَجْعَلْنِي بِمَعصِيَتِكَ مَطْرُودًا ، ورَضِّني بِقَضَائِكَ ، وبَارِكْ لي في قَدَرِكَ ، وانْصُرْني عَلى مَنْ ظَلَمَنِي ، وأَرِنِي فيه ثَأْرِي ، وأَقِرَّ بذلك عَيْني .''',
    transliteration: r'''Allāhumma ij'alnī akhshāka ḥattā ka'annī arāk, wa as'idnī bi-taqwāk, wa lā taj'alnī bi-ma'ṣiyatika maṭrūdā, wa raḍḍinī bi-qaḍā'ik, wa bārik lī fī qadarik, wa unṣurnī 'alā man ẓalamanī, wa arinī fīhi tha'rī, wa aqirra bidhālika 'aynī.''',
    translationEn: r'''O Allah, make me fear You as though I see You, make me happy through fear of You, and do not make me driven away because of disobedience to You. Make me pleased with Your decree, bless me in what You have decreed for me, help me against whoever has wronged me, show me my retribution against him, and thereby let my eye be comforted.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''astawdiuka_alyawma_nafsi''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم إني أستودعك اليوم نفسي''',
    titleEn: r'''I Entrust to You Myself and My Family''',
    arabicText: r'''اللَّهُمَّ إنِّي أَسْتَوْدِعُكَ اليَوْمَ نَفْسِي ، وأَهْلِي ومَالِي ووَلَدِي ، ومَنْ كانَ مِنِّي في سَبِيل ، الشَّاهِدِ منهُمُ والغائِبِ .''',
    transliteration: r'''Allāhumma innī astawdi'uka al-yawma nafsī, wa ahlī wa mālī wa waladī, wa man kāna minnī fī sabīl, ash-shāhidi minhum wal-ghā'ib.''',
    translationEn: r'''O Allah, I entrust to You today myself, my family, my wealth, my children, and whoever is connected to me in any way — those present among them and those absent.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
