  AdhkarEntry(
    id: r'''ijalna_fi_rahmatika''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم اجعلنا في رحمتك''',
    titleEn: r'''Place Us Within Your Mercy''',
    arabicText: r'''اللَّهُمَّ اجْعَلْنَا في رَحْمَتِكَ ، ولا تَسْلُبْنَا فَضْلَكَ ، إنَّا إلَيكَ رَاغِبُونَ .''',
    transliteration: r'''Allāhumma ij'alnā fī raḥmatik, wa lā taslubnā faḍlak, innā ilayka rāghibūn.''',
    translationEn: r'''O Allah, place us within Your mercy, and do not strip us of Your favor; indeed, we are desirous toward You.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''naudhu_bika_min_wathaa_alsafar''',
    category: AdhkarCategory.protection,
    titleAr: r'''اللهم إنا نعوذ بك من وعثاء السفر''',
    titleEn: r'''Refuge from the Hardship of Travel''',
    arabicText: r'''اللَّهُمَّ إنَّا نَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ ، وكَآبَةِ المُنْقَلَبْ ، وسُوءِ المَنْظَرِ في الأهلِ والمالِ والوَلد . يا مَنْ هُوَ أَقْرَبُ من حَبْلِ الوَريدِ ، يا فَعَّالاً لِمَا يُريدُ ، يا مَنْ يَحُولُ بَيْنَ المَرْءِ وَقَلْبِهِ ، حُلْ بَيْننا وبيْنَ من يُؤذِينَا بِحَوْلِكَ وقُوَّتِكَ . يَاكَافي كُلَّ شيءٍ ، ولا يَكْفِي منه شيءٌ ، اكْفِنَا مَايُهِمُّنَا من أَمْرِ الدُّنْيَا والآخِرَةِ ، يا أَرْحَمَ الرَّاحِمِينَ .''',
    transliteration: r'''Allāhumma innā na'ūdhu bika min wa'thā'i as-safar, wa ka'ābati al-munqalab, wa sū'i al-manẓari fīl-ahli wal-māli wal-walad. Yā man huwa aqrabu min ḥabli al-warīd, yā fa''ālan limā yurīd, yā man yaḥūlu bayna al-mar'i wa qalbih, ḥul baynanā wa bayna man yu'dhīnā bi-ḥawlika wa quwwatik. Yā kāfiya kulli shay', wa lā yakfī minhu shay', ikfinā mā yuhimmunā min amri ad-dunyā wal-ākhirah, yā arḥama ar-rāḥimīn.''',
    translationEn: r'''O Allah, we seek refuge in You from the hardship of travel, the grief of a bad return, and an ill sight in family, wealth, and children. O You who are closer than the jugular vein, O Doer of what He wills, O You who comes between a man and his heart, come between us and whoever harms us, by Your power and might. O Sufficient One for everything, whom nothing suffices for, suffice us in what concerns us of the matters of this world and the Hereafter, O Most Merciful of the merciful.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''waffir_hazzi_min_khayrin''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم وفر حظي من خير''',
    titleEn: r'''Grant Me My Full Share of Good''',
    arabicText: r'''اللَّهُمَّ وَفِّرْ حَظِّي من خَيرٍ تُنْزِلُهُ ، أَوْ إحسانٍ تُفْضِلُهُ ، أَوْ بِرٍّ تَنْشُرُهُ ، أَوْ رِزْقٍ تَبْسُطُهُ ، أَوْ ذَنْبٍ تَغْفِرُهُ ، أَوْ خَطَأً تَسْتُرُهُ . يا إلهي ، يا مَنْ بِيَدِهِ ناصِيَتِي ، يا عَليمًا بِضُرِّي ومَسْكَنَتِي ، ياخَبيرًا بِفَقْرِي وفَاقَتِي ، أَسأَلُكَ يارَبِّ ، بِحَقِّكَ وقُدْسِكَ ، وأَعظَمِ صِفَاتِكَ وأَسْمَائِكَ : أَنْ تَجْعَلَ أَوْقَاتِي بِاللَّيلِ والنَّهارِ بِذِكْرِكَ مَغْمُورًا ، وبِخِدْمَتِكَ مَوْصُولَةً ، وأَعْمَالِي عِنْدَكَ مَقْبُولَةً ، يا مَنْ عَلَيهِ مُعَوَّلِي ، يا مَنْ إلَيْهِ شَكَوْتُ أَحْوَالِي ، قَوِّ عَلَى خِدْمَتِكَ جَوَارِحِي ، واشْدُدْ عَلَى العَزِيمَةِ جَوَانِحِي ، وهَبْ لِيَ الجِدَّ في خَشْيَتِكَ ، والدَّوَامَ على الاتِّصَالِ في خِدْمَتِكَ ، حَتَّى أَخَافَكَ مَخَافَةَ المُوقِنينَ ، وأَجْتَمِعَ في جِوَارِكَ مَعَ المُؤمِنِينَ .''',
    transliteration: r'''Allāhumma waffir ḥaẓẓī min khayrin tunziluh, aw iḥsānin tufḍiluh, aw birrin tanshuruh, aw rizqin tabsuṭuh, aw dhanbin taghfiruh, aw khaṭa'an tasturuh. Yā ilāhī, yā man bi-yadihi nāṣiyatī, yā 'alīman bi-ḍurrī wa maskanatī, yā khabīran bi-faqrī wa fāqatī, as'aluka yā rabbi, bi-ḥaqqika wa qudsika, wa a'ẓami ṣifātika wa asmā'ik: an taj'ala awqātī bil-layli wan-nahāri bi-dhikrika maghmūrā, wa bi-khidmatika mawṣūlah, wa a'mālī 'indaka maqbūlah, yā man 'alayhi mu'awwalī, yā man ilayhi shakawtu aḥwālī, qawwi 'alā khidmatika jawāriḥī, wa ushdud 'alā al-'azīmati jawāniḥī, wa hab liya al-jidda fī khashyatik, wad-dawāma 'alā al-ittiṣāli fī khidmatik, ḥattā akhāfaka makhāfata al-mūqinīn, wa ajtami'a fī jiwārika ma'a al-mu'minīn.''',
    translationEn: r'''O Allah, grant me my full share of any good You send down, any favor You bestow, any righteousness You spread, any provision You extend, any sin You forgive, or any error You conceal. O my God, O You in whose Hand is my forelock, O Knower of my affliction and destitution, O Aware One of my poverty and need, I ask You, my Lord, by Your right, Your holiness, and the greatest of Your attributes and names: make my times, by night and day, immersed in Your remembrance, connected to Your service, and my deeds accepted with You. O You upon whom I rely, O You to whom I complain of my states, strengthen my limbs for Your service, and fortify my resolve for determination. Grant me diligence in fear of You, and constancy in devotion to Your service, until I fear You with the fear of those with certainty, and am gathered in Your neighborhood together with the believers.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''man_aradani_bisuin_faruddahu''',
    category: AdhkarCategory.protection,
    titleAr: r'''اللهم من أرادني بسوء فرده عليه''',
    titleEn: r'''Turn Back Whoever Intends Me Harm''',
    arabicText: r'''اللَّهُمَّ مَنْ أَرَادَني بِسُوءٍ فَرُدَّهُ عَلَيْهِ ، ومَنْ كَادَني فَكِدْهُ ، واجْعَلْني من أَحْسَنِ عِبَادِكَ نَصِيبًا عِنْدَكَ ، وأَقْرَبِهِم مَنْزِلَةً مِنْكَ ، وأَخَصِّهِمْ زُلْفَى لَدَيْكَ ؛ فَإنَّهُ لا يُنَالُ ذَلِكَ إلَّا بِفَضْلِكَ ، وَجُدْ لي بِجُودِكَ ، واعطِفْ عليَّ بِمَجْدِكَ ، واحفَظْني بِرَحمَتِكَ ، واجْعَلْ لِسَانِي بِذِكْرِكَ لَهِجًا ، وقَلْبِي بِحُبِّكَ مُتَيَّمًا ، وَمُنَّ عَلَيَّ بِحُسْنِ إجَابَتِكَ ، وأَقِلْني عَثْرَتي ، واغفِر لي زَلَّتي ؛ فَإنَّكَ أَمَرْتَ عِبَادَكَ بِدُعَائِكَ ، وضَمِنْتَ لَهُمُ الإجَابَةَ ، فَإلَيكَ يا رَبِّ نَصَبْتُ وَجْهِي ، ومَدَدْتُ يَدِي ، فَبِرَحمَتِكَ استَجِبْ دُعَائِي ، وبَلِّغْني مُنَايَ ، ولا تَقْطَعْ رَجَائِي ، واكْفِنِي شَرَّ أَعْدَائِي ، يا سَمِيعَ الدُّعَاءِ ، يا سَابِغَ النِّعَمِ ، يا دَافِعَ النِّقَمِ ، يا نُورَ المُستَوْحِشِينَ في الظُّلمِ ، يا أَرْحَمَ الرَّاحِمِينَ .''',
    transliteration: r'''Allāhumma man arādanī bi-sū'in faruddahu 'alayh, wa man kādanī fakidh, wa ij'alnī min aḥsani 'ibādika naṣīban 'indak, wa aqrabihim manzilatan minka, wa akhaṣṣihim zulfā ladayk; fa-innahu lā yunālu dhālika illā bi-faḍlik, wa jud lī bi-jūdik, wa i'ṭif 'alayya bi-majdik, wa iḥfaẓnī bi-raḥmatik, wa ij'al lisānī bi-dhikrika lahijā, wa qalbī bi-ḥubbika mutayyamā, wa munna 'alayya bi-ḥusni ijābatik, wa aqilnī 'athratī, waghfir lī zallatī; fa-innaka amarta 'ibādaka bi-du'ā'ik, wa ḍamanta lahumu al-ijābah, fa-ilayka yā rabbi naṣabtu wajhī, wa madadtu yadī, fa-bi-raḥmatika istajib du'ā'ī, wa balligh-nī munāya, wa lā taqṭa' rajā'ī, wakfinī sharra a'dā'ī, yā samī'a ad-du'ā', yā sābigha an-ni'am, yā dāfi'a an-niqam, yā nūra al-mustawḥishīna fī aẓ-ẓulm, yā arḥama ar-rāḥimīn.''',
    translationEn: r'''O Allah, whoever intends me harm, turn it back upon him; whoever schemes against me, scheme against him. Make me one of Your servants with the best portion with You, the nearest of them in station to You, and the most especially close to You, for that is attained only through Your favor. Be generous to me with Your generosity, be kind to me through Your glory, protect me with Your mercy, make my tongue constantly occupied with Your remembrance, and my heart devoted to Your love. Grant me the excellence of Your response, overlook my stumbling, and forgive my slip, for You have commanded Your servants to call upon You and have guaranteed them a response. So to You, my Lord, I have turned my face, and extended my hand; by Your mercy answer my supplication, bring me to my hope, do not cut off my expectation, and spare me the evil of my enemies. O Hearer of supplication, O Bestower of abundant blessings, O Repeller of afflictions, O Light of those made desolate in darkness, O Most Merciful of the merciful.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''abrau_ilayka_min_hawli_waquwwati''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم إني أبرأ إليك من حولي وقوتي''',
    titleEn: r'''I Disown My Own Power and Might''',
    arabicText: r'''اللَّهُمَّ إنِّي أَبْرَأُ إلَيكَ مِنْ حَوْلِي وقُوَّتِي ، وأَلـجَأُ إلى حَوْلِكَ وقُوَّتِكَ . أَحْمَدُكَ إذ أَوْجَدْتَني من العَدَمِ ، وفَضَّلْتَني عَلَى كَثِيرٍ من الأُمَمِ ، وجَعَلْتَ في يَدَيّ زِمَامَ خَلْقِكَ ، واستَخْلَفْتَنِي عَلَى أَرضِكَ .''',
    transliteration: r'''Allāhumma innī abra'u ilayka min ḥawlī wa quwwatī, wa alja'u ilā ḥawlika wa quwwatik. Aḥmaduka idh awjadtanī min al-'adam, wa faḍḍaltanī 'alā kathīrin mina al-umam, wa ja'alta fī yadayya zimāma khalqik, wa istakhlaftanī 'alā arḍik.''',
    translationEn: r'''O Allah, I disown before You my own power and strength, and I take refuge in Your power and strength. I praise You for having brought me into being out of nothing, for having favored me over many nations, for having placed in my hands the reins over Your creation, and for having made me a successor upon Your earth.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''fakhudh_biyadi_filmadaiq''',
    category: AdhkarCategory.protection,
    titleAr: r'''اللهم فخذ بيدي في المضائق''',
    titleEn: r'''Take My Hand Through Hardships''',
    arabicText: r'''اللَّهُمَّ فَخُذْ بِيَدي في المَضَائِقِ ، واكْشِفْ لي وُجُوهَ الحَقَائِقِ ، وَوَفِّقْني لِمَا تُحِبُّ ، واعصِمْني من الزَّلَلِ ، ولا تَسلُبْ عَنِّي سِتْرَ إحسَانِكَ ، وقِنِي مَصَارِعَ السُّوءِ ، واكْفِني كَيدَ الحَاسِدِ ، وشَمَاتَةَ الأَضْدَادِ ، والطُف بي في سَائِرِ مُتَصَرَّفَاتِي ، واكْفِني من جَمِيعِ جِهَاتِي ، يا أَرْحَمَ الرَّاحِمِينَ .''',
    transliteration: r'''Allāhumma fakhudh bi-yadī fīl-maḍā'iq, wakshif lī wujūha al-ḥaqā'iq, wa waffiqnī limā tuḥibb, wa i'ṣimnī mina az-zalal, wa lā taslub 'annī sitra iḥsānik, wa qinī maṣāri'a as-sū', wakfinī kayda al-ḥāsid, wa shamātata al-aḍdād, waṭluf bī fī sā'iri mutaṣarrafātī, wakfinī min jamī'i jihātī, yā arḥama ar-rāḥimīn.''',
    translationEn: r'''O Allah, take me by the hand through hardships, unveil for me the aspects of truth, grant me success in what You love, and protect me from error. Do not strip from me the cover of Your kindness, protect me from evil downfalls, spare me the scheming of the envious and the gloating of adversaries, be gentle with me in all my affairs, and suffice me from every direction, O Most Merciful of the merciful.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''innaka_tasmau_kalami''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''إنك تسمع كلامي وترى مكاني''',
    titleEn: r'''You Hear My Words and See My Place''',
    arabicText: r'''اللَّهُمَّ إنَّكَ تَسْمَعُ كَلامِي ، وتَرَى مَكَانِي ، وتَعْلَمُ سِرِّي وعَلانِيَتي ، وَلا يَخْفى عَلَيكَ شَيءٌ من أَمْري ، وأَنَا البَائِسُ الفَقِيرُ ، والمُستَغِيثُ المُستَجِيرُ ، والوَجِلُ المُشْفِقُ المُقِرُّ المُعْتَرِفُ إلَيكَ بِذَنْبِهِ ، أَسأَلُكَ مَسأَلَةَ المِسكِينِ ، وأَبْتَهِلُ إلَيكَ ابتِهَالَ المُذْنِبِ الذَّليلِ ، وأَدْعُوكَ دُعَاءَ الخَائِفِ الضَّرِيرِ ، دُعَاءَ مَنْ خَضَعَتْ لَكَ رَقَبَتُهُ ، وذَلَّ لَكَ جِسْمُهُ ، وَرَغِمَ لَكَ أَنْفُهُ .''',
    transliteration: r'''Allāhumma innaka tasma'u kalāmī, wa tarā makānī, wa ta'lamu sirrī wa 'alāniyatī, wa lā yakhfā 'alayka shay'un min amrī, wa ana al-bā'isu al-faqīr, wal-mustaghīthu al-mustajīr, wal-wajilu al-mushfiqu al-muqirru al-mu'tarifu ilayka bi-dhanbih, as'aluka mas'alata al-miskīn, wa abtahilu ilayka ibtihāla al-mudhnibi adh-dhalīl, wa ad'ūka du'ā'a al-khā'ifi aḍ-ḍarīr, du'ā'a man khaḍa'at laka raqabatuh, wa dhalla laka jismuh, wa raghima laka anfuh.''',
    translationEn: r'''O Allah, indeed You hear my speech, see my place, and know my secret and my open affairs, and nothing of my condition is hidden from You. I am the wretched, the poor, the one crying out for help and seeking shelter, the fearful, the anxious, the one who confesses and admits his sin before You. I ask You with the asking of the destitute, and I implore You with the imploring of the humbled sinner, and I call upon You with the call of the terrified, blind man — the call of one whose neck has bowed to You, whose body has been humbled before You, and whose nose has been rubbed in the dust before You.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''kun_li_muayyidan_wanasiran''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم كن لي مؤيدًا وناصرًا''',
    titleEn: r'''Be My Supporter and Helper''',
    arabicText: r'''اللَّهُمَّ كُنْ لي مُؤَيِّدًا ونَاصِرًا ، وكُنْ بِي رَؤُوفًا رَحِيمًا ، ياخَيْرَ المَسؤُولِين .''',
    transliteration: r'''Allāhumma kun lī mu'ayyidan wa nāṣirā, wa kun bī ra'ūfan raḥīmā, yā khayra al-mas'ūlīn.''',
    translationEn: r'''O Allah, be for me a supporter and a helper, and be toward me kind and merciful, O Best of those who are asked.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''ilayka_ashku_dafa_quwwati''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''إليك أشكو ضعف قوتي''',
    titleEn: r'''To You I Complain of My Weakness''',
    arabicText: r'''إلَيكَ أَشْكُو ضَعْفَ قُوَّتِي ، وقِلَّةَ حِيلَتي . يا أَرحَمَ الرَّاحِمينَ بِقُدْرَتِكَ عَلَيَّ ، ولا تَكِلْني إلى نَفْسِي طَرْفَةَ عَينٍ ، يا حَيُّ يا قَيُّومُ بِرَحمَتِكَ أَستَغِيثُ ( ثلاثًا ) .''',
    transliteration: r'''Ilayka ashkū ḍa'fa quwwatī, wa qillata ḥīlatī. Yā arḥama ar-rāḥimīna bi-qudratika 'alayya, wa lā takilnī ilā nafsī ṭarfata 'ayn, yā ḥayyu yā qayyūmu bi-raḥmatika astaghīth. (three times)''',
    translationEn: r'''To You I complain of my weakness and lack of resourcefulness. O Most Merciful of the merciful, by Your power over me, do not leave me to myself for even the blink of an eye. O Ever-Living, O Sustainer, by Your mercy I seek relief. (three times)''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 3,
    repetitionNote: r'''"( ثلاثًا )" explicitly noted after the closing phrase "يا حي يا قيوم برحمتك أستغيث"''',
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''asaluka_biizzika_wadhulli''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''أسألك بعزك وذلي''',
    titleEn: r'''I Ask You by Your Might and My Lowliness''',
    arabicText: r'''أَسأَلُكَ بِعِزِّكَ وذُلِّي إلَّا رَحِمْتَني ، وأَسأَلُكَ بِقُوَّتِكَ وضَعْفِي ، وبِغَنَائِكَ عَنِّي وفَقْرِي إلَيكَ ، هَذه نَاصِيَتِي الخَاطِئَةُ بَينَ يَدَيْكَ ، عَبيدُكَ سِوَايَ كَثيرٌ ، ولَيسَ لي سَيِّدٌ سِوَاكَ ، لا مَلْجَأً ولا مَنْجَى مِنْكَ إلَّا إلَيكَ ، أَسأَلُكَ مَسأَلَةَ المِسكِينِ ، وأَبتَهِلُ إلَيكَ ابتِهَالَ الخَاضِعِ الذَّلِيلِ ، وأَدْعُوكَ دُعَاءَ الخَائِفِ الضَّرِيرِ ، سُؤَالَ مَنْ خَضَعَتْ لَكَ رَقَبَتُهُ ، ورَغِمَ لَكَ أَنْفُهُ ، وفَاضَتْ لَكَ عَينَاهُ ، وذَلَّ لَكَ قَلْبُهُ .''',
    transliteration: r'''As'aluka bi-'izzika wa dhullī illā raḥimtanī, wa as'aluka bi-quwwatika wa ḍa'fī, wa bi-ghanā'ika 'annī wa faqrī ilayk, hādhihi nāṣiyatī al-khāṭi'atu bayna yadayk, 'abīduka siwāya kathīr, wa laysa lī sayyidun siwāk, lā malja'a wa lā manjā minka illā ilayk, as'aluka mas'alata al-miskīn, wa abtahilu ilayka ibtihāla al-khāḍi'i adh-dhalīl, wa ad'ūka du'ā'a al-khā'ifi aḍ-ḍarīr, su'āla man khaḍa'at laka raqabatuh, wa raghima laka anfuh, wa fāḍat laka 'aynāh, wa dhalla laka qalbuh.''',
    translationEn: r'''I ask You by Your might and my lowliness, that You show me mercy; I ask You by Your strength and my weakness, and by Your independence from me and my poverty toward You. This is my sinning forelock before You; Your servants besides me are many, but I have no master besides You. There is no refuge and no escape from You except to You. I ask You with the asking of the destitute, and I implore You with the imploring of the humbled and lowly one, and I call upon You with the call of the terrified, blind man — the asking of one whose neck has bowed to You, whose nose has been rubbed in the dust before You, whose eyes have overflowed with tears for You, and whose heart has been humbled before You.''',
    sourceReference: r'''الورد المصفى — quoted from Ibn al-Qayyim, Madarij al-Salikin''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''albisni_alafiyah''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم ألبسني العافية''',
    titleEn: r'''Clothe Me in Well-Being''',
    arabicText: r'''اللَّهُمَّ أَلْبِسْني العَافِيَةَ حَتَّى تُهَنِّيني بالمَعِيشَةِ ، واختِمْ لي بالمَغفِرَةِ حَتَّى لا تَضُرَّني الذُّنُوبُ ، واكفِني كُلَّ هَوْلٍ دُونَ الجَنَّةِ حَتَّى تُبَلِّغَنِيها ، بِرَحمَتِكَ يا أَرحَمَ الرَّاحِمِينَ .''',
    transliteration: r'''Allāhumma albisnī al-'āfiyata ḥattā tuhanni'anī bil-ma'īshah, wakhtim lī bil-maghfirati ḥattā lā taḍurranī adh-dhunūb, wakfinī kulla hawlin dūna al-jannati ḥattā tuballighanīhā, bi-raḥmatika yā arḥama ar-rāḥimīn.''',
    translationEn: r'''O Allah, clothe me in well-being until You make my life pleasant for me, seal my end with forgiveness so that sins do not harm me, and spare me every terror short of Paradise until You deliver me to it, by Your mercy, O Most Merciful of the merciful.''',
    sourceReference: r'''الورد المصفى — attributed to 'Umar ibn 'Abd al-'Aziz''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''atini_min_alduniya_ma_taqini''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم أعطني من الدنيا ما تقيني به فتنتها''',
    titleEn: r'''Give Me What Protects Me from Worldly Trial''',
    arabicText: r'''اللَّهُمَّ أَعطِني مِنَ الدُّنْيَا مَا تَقِيني بِهِ فِتْنَتَها ، وتُغْنِيني بِهِ عَنْ أَهلِهَا ، ويَكُونُ بَلاغًا لي إلى مَا هُوَ خَيرٌ منها ؛ فَإنَّهُ لا حَولَ ولا قُوَّةَ إلَّا بِكَ .''',
    transliteration: r'''Allāhumma a'ṭinī mina ad-dunyā mā taqīnī bihi fitnatahā, wa tughnīnī bihi 'an ahlihā, wa yakūnu balāghan lī ilā mā huwa khayrun minhā; fa-innahu lā ḥawla wa lā quwwata illā bik.''',
    translationEn: r'''O Allah, give me from this world that which protects me from its trial, that which makes me independent of its people, and that which becomes a means of reaching what is better than it; for there is no power and no strength except with You.''',
    sourceReference: r'''الورد المصفى — attributed to 'Umar ibن 'Abd al-'Aziz''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''qannini_bima_razaqtani''',
    category: AdhkarCategory.dailyDuas,
    titleAr: r'''اللهم قنعني بما رزقتني''',
    titleEn: r'''Make Me Content with My Provision''',
    arabicText: r'''اللَّهُمَّ قَنِّعْني بِمَا رَزَقْتَني ، وبَارِكْ لي فيه ، واخلُفْ عَلَيَّ كُلَّ غَائِبَةٍ لي بِخَيرٍ .''',
    transliteration: r'''Allāhumma qanni'nī bimā razaqtanī, wa bārik lī fīh, wakhluf 'alayya kulla ghā'ibatin lī bi-khayr.''',
    translationEn: r'''O Allah, make me content with what You have provided me, bless it for me, and replace for me every absent thing of mine with something good.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''subhanallah_wabihamdihi_adada_khalqihi''',
    category: AdhkarCategory.generalDhikr,
    titleAr: r'''سبحان الله وبحمده عدد خلقه''',
    titleEn: r'''Glory Be to Allah, By the Number of His Creation''',
    arabicText: r'''سُبْحَانَ اللَّه وبِحَمْدِهِ ، عَدَدَ خَلْقِهِ ، ورِضَى نَفْسِهِ ، وزِنَةَ عَرْشِهِ ، ومِدَادَ كَلِمَاتِهِ .''',
    transliteration: r'''Subḥāna Allāhi wa bi-ḥamdih, 'adada khalqih, wa riḍā nafsih, wa zinata 'arshih, wa midāda kalimātih.''',
    translationEn: r'''Glory be to Allah and praise be to Him, by the number of His creation, by the pleasure of His Self, by the weight of His Throne, and by the extent of His Words.''',
    sourceReference: r'''الورد المصفى — Prophetic supplication (hadith of Juwayriyah, radiya Allahu 'anha)''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
