  AdhkarEntry(
    id: r'''subhanallah_adada_ma_khalaqa_fissama''',
    category: AdhkarCategory.generalDhikr,
    titleAr: r'''سبحان الله عدد ما خلق في السماء والأرض''',
    titleEn: r'''Glory Be to Allah by the Count of All He Created''',
    arabicText: r'''سُبْحَانَ اللَّه ، عَدَدَ مَا خَلَقَ في السَّمَاءِ ، وعَدَدَ مَا خَلَقَ في الأَرْضِ ، وسبحانَ اللَّه عَدَدَ ما بَيْنَ ذَلك ، وسبحانَ اللَّه عَدَدَ ما هُوَ خَالِقٌ . واللَّه أَكْبَرُ مِثْلَ ذلك . والحمدُ للَّه مِثْلَ ذلك . ولا حول ولا قُوَّة إلَّا باللَّه مِثْلَ ذلك .''',
    transliteration: r'''Subḥāna Allāh, 'adada mā khalaqa fīs-samā', wa 'adada mā khalaqa fīl-arḍ, wa subḥāna Allāhi 'adada mā bayna dhālik, wa subḥāna Allāhi 'adada mā huwa khāliq. Wallāhu akbaru mithla dhālik. Wal-ḥamdu lillāhi mithla dhālik. Wa lā ḥawla wa lā quwwata illā billāhi mithla dhālik.''',
    translationEn: r'''Glory be to Allah, by the number of what He created in the heaven, and by the number of what He created on the earth; and glory be to Allah, by the number of what is between that; and glory be to Allah, by the number of what is yet to be created. And Allah is greatest, the like of that. And praise be to Allah, the like of that. And there is no power and no strength except with Allah, the like of that.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''subhanallah_adada_khalqihi_milaa_ma_khalaqa''',
    category: AdhkarCategory.generalDhikr,
    titleAr: r'''سبحان الله عدد خلقه ملء ما خلق''',
    titleEn: r'''Glory Be to Allah, Filling All He Created''',
    arabicText: r'''سُبْحَانَ اللَّه عَدَدَ خَلْقِهِ ، سبحانَ اللَّه مِلْءَ ما خَلَقَ ، سُبْحَانَ اللَّه عَدَدَ ما خَلَقَ ، سُبْحَانَ اللَّه عَدَدَ ما في السماء والأرض ، سُبْحَانَ اللَّه عَدَدَ ما في الأَرْضِ والسَّمَاءِ ، وسُبْحَانَ اللَّه عَدَدَ ما أَحْصَى كِتَابُهُ ، وسبحانَ اللَّه عَدَدَ كلِّ شَيءٍ ، وسُبْحَانَ اللَّه مِلْءَ كُلِّ شَيءٍ . والحمدُ للَّه مِثْلَ ذَلِكَ .''',
    transliteration: r'''Subḥāna Allāhi 'adada khalqih, subḥāna Allāhi mil'a mā khalaq, subḥāna Allāhi 'adada mā khalaq, subḥāna Allāhi 'adada mā fīs-samā'i wal-arḍ, subḥāna Allāhi 'adada mā fīl-arḍi was-samā', wa subḥāna Allāhi 'adada mā aḥṣā kitābuh, wa subḥāna Allāhi 'adada kulli shay', wa subḥāna Allāhi mil'a kulli shay'. Wal-ḥamdu lillāhi mithla dhālik.''',
    translationEn: r'''Glory be to Allah, by the number of His creation; glory be to Allah, filling what He created; glory be to Allah, by the number of what He created; glory be to Allah, by the number of what is in the heaven and the earth; glory be to Allah, by the number of what is in the earth and the heaven; and glory be to Allah, by the number of what His Book has recorded; and glory be to Allah, by the number of everything; and glory be to Allah, filling everything. And praise be to Allah, the like of that.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''subhanallah_adada_ma_ahsahu_la_ilaha_illallah''',
    category: AdhkarCategory.generalDhikr,
    titleAr: r'''سبحان الله عدد ما أحصاه''',
    titleEn: r'''Glory Be to Allah, By the Count of All He Has Enumerated''',
    arabicText: r'''سُبْحَانَ اللَّه عَدَدَ ما أَحْصَاهُ . لا إلَهَ إلَّا اللَّهُ عَدَدَ كَلِمَاتِهِ ، لا إلَه إلا اللَّه عَدَدَ خَلْقِهِ ، لا إلَه إلا اللَّهُ زِنَةَ عَرْشِهِ ، لا إلَه إلَّا اللَّه مِلْءَ سَمَاوَاتِهِ ، لا إلَهَ إلَّا اللَّه مِلْءَ أَرْضِهِ ، لا إلَه إلَّا اللَّه مِثْلَ ذلك . واللَّه أَكْبَرُ مِثْلَ ذلك . والحمدُ للَّه مِثْلَ ذلكَ .''',
    transliteration: r'''Subḥāna Allāhi 'adada mā aḥṣāh. Lā ilāha illā Allāhu 'adada kalimātih, lā ilāha illā Allāhu 'adada khalqih, lā ilāha illā Allāhu zinata 'arshih, lā ilāha illā Allāhu mil'a samāwātih, lā ilāha illā Allāhu mil'a arḍih, lā ilāha illā Allāhu mithla dhālik. Wallāhu akbaru mithla dhālik. Wal-ḥamdu lillāhi mithla dhālik.''',
    translationEn: r'''Glory be to Allah, by the number of what He has enumerated. There is no god but Allah, by the number of His Words; there is no god but Allah, by the number of His creation; there is no god but Allah, by the weight of His Throne; there is no god but Allah, filling His heavens; there is no god but Allah, filling His earth; there is no god but Allah, the like of that. And Allah is greatest, the like of that. And praise be to Allah, the like of that.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''subhanallahi_milaa_albarr''',
    category: AdhkarCategory.generalDhikr,
    titleAr: r'''سبحان الله ملء البر والبحر''',
    titleEn: r'''Glory Be to Allah, Filling Land and Sea''',
    arabicText: r'''سُبْحَانَ اللَّهِ مِلْءَ البَرِّ ، سُبْحَانَ اللَّه مِلْءَ البَحْرِ ، سُبْحَانَ اللَّه مِلْءَ السَّمَاوَاتِ والأرض .''',
    transliteration: r'''Subḥāna Allāhi mil'a al-barr, subḥāna Allāhi mil'a al-baḥr, subḥāna Allāhi mil'a as-samāwāti wal-arḍ.''',
    translationEn: r'''Glory be to Allah, filling the land; glory be to Allah, filling the sea; glory be to Allah, filling the heavens and the earth.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''subhanallah_walhamdulillah_wallahu_akbar_adada_ma_khalaqa''',
    category: AdhkarCategory.generalDhikr,
    titleAr: r'''سبحان الله والحمد لله والله أكبر عدد ما خلق''',
    titleEn: r'''The Comprehensive Tasbih of Endless Praise''',
    arabicText: r'''سُبْحَانَ اللَّه ، والحمدُ للَّه ، واللَّه أَكْبَرُ ، ولا حَوْلَ ولا قُوَّةَ إلَّا باللَّهِ ، عَدَدَ ما خَلَقَ ، وعَدَدَ مَا هُوَ خَالِقٌ ، وزِنَةَ ما خَلَقَ ، وزِنَةَ مَا هُوَ خَالِقٌ ، ومِلْءَ ما خَلَقَ ، ومِلْءَ ما هُوَ خَالِقٌ ، ومِلْءَ سَمَاوَاتِهِ ، ومِلْءَ أَرْضِهِ ، ومِثْلَ ذلك ، وأَضْعَافَ ذَلِكَ ، وعَدَدَ خَلْقِهِ ، وزِنَةَ عَرْشِهِ ، ومُنْتَهَى رَحْمَتِهِ ، ومِدَادَ كَلِمَاتِهِ ، ومَبْلَغَ رِضَاهُ ، وَحَتَّى يَرْضَى ، وإذا يَرْضَى ، وعَدَدَ ما ذَكَرَهُ به خَلْقُهُ ، في جَمِيعِ ما مَضَى ، وعَدَدَ ما هُمْ ذَاكِروه فيما بَقِيَ في كُلِّ سَنَةٍ وشَهْرٍ وجُمُعَةٍ ويومٍ ولَيلةٍ وسَاعَةٍ من السَّاعَاتِ ، وتَنَسُّم وتَنَفُّس من الأَبَدِ إلى الأَبَدِ ، أَبَدِ الدُّنْيَا والآخِرَةِ ، أَبَدَ ذلك ، لا يَنْقَطِعُ أَوَّلَاهُ ، ولا يَنْفَدُ أُخْرَاهُ .''',
    transliteration: r'''Subḥāna Allāh, wal-ḥamdu lillāh, wallāhu akbar, wa lā ḥawla wa lā quwwata illā billāh, 'adada mā khalaq, wa 'adada mā huwa khāliq, wa zinata mā khalaq, wa zinata mā huwa khāliq, wa mil'a mā khalaq, wa mil'a mā huwa khāliq, wa mil'a samāwātih, wa mil'a arḍih, wa mithla dhālik, wa aḍ'āfa dhālik, wa 'adada khalqih, wa zinata 'arshih, wa muntahā raḥmatih, wa midāda kalimātih, wa mablagha riḍāh, wa ḥattā yarḍā, wa idhā yarḍā, wa 'adada mā dhakarahu bihi khalquh, fī jamī'i mā maḍā, wa 'adada mā hum dhākirūhu fīmā baqiya fī kulli sanatin wa shahrin wa jum'atin wa yawmin wa laylatin wa sā'atin mina as-sā'āt, wa tanassumin wa tanaffusin mina al-abadi ilā al-abad, abadi ad-dunyā wal-ākhirah, abada dhālik, lā yanqaṭi'u awwalāh, wa lā yanfadu ukhrāh.''',
    translationEn: r'''Glory be to Allah, and praise be to Allah, and Allah is greatest, and there is no power and no strength except with Allah — by the number of what He has created, and by the number of what He is yet to create; by the weight of what He has created, and by the weight of what He is yet to create; filling what He has created, and filling what He is yet to create; filling His heavens and filling His earth; and the like of that, and multiples of that; by the number of His creation, the weight of His Throne, the utmost extent of His mercy, the extent of His Words, the fullness of His pleasure — until He is pleased, and whenever He is pleased; by the number of times His creation has remembered Him with it throughout all that has passed, and by the number of times they will remember Him with it in what remains, in every year, month, week, day, night, and hour of the hours, and every breath drawn in and let out, from eternity to eternity, the eternity of this world and the Hereafter, the eternity of that — its beginning never ceasing, and its end never running out.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''asaluka_min_khayrin_ma_salaka_abduka''',
    category: AdhkarCategory.protection,
    titleAr: r'''اللهم إني أسألك من خير ما سألك منه عبدك ورسولك''',
    titleEn: r'''I Ask You for the Good Your Servant and Messenger Asked''',
    arabicText: r'''اللَّهُمَّ إنِّي أَسأَلُكَ من خَيرٍ ما سأَلَكَ منه عَبْدُكَ ورَسُولُكَ محمدٌ ﷺ ، وأَعُوذُ بِكَ مِنْ شَرِّ ما استَعَاذَكَ منه عَبْدُكَ ونَبِيُّكَ .''',
    transliteration: r'''Allāhumma innī as'aluka min khayrin mā sa'alaka minhu 'abduka wa rasūluka Muḥammadun ﷺ, wa a'ūdhu bika min sharri mā ista'ādhaka minhu 'abduka wa nabiyyuk.''',
    translationEn: r'''O Allah, I ask You for the good that Your servant and Messenger Muhammad ﷺ asked You for, and I seek refuge in You from the evil that Your servant and Prophet sought refuge in You from.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
  AdhkarEntry(
    id: r'''asaluka_aljannata_wama_qarraba_ilayha''',
    category: AdhkarCategory.protection,
    titleAr: r'''اللهم إني أسألك الجنة وما قرب إليها''',
    titleEn: r'''I Ask You for Paradise and What Draws Near It''',
    arabicText: r'''اللَّهُمَّ إنِّي أَسأَلُكَ الجَنَّةَ وما قَرَّبَ إليها من قَوْلٍ وعَمَلٍ ، وأَعُوذُ بِكَ مِنَ النَّارِ وما قَرَّبَ إليها من قَوْلٍ وعَمَلٍ ، وأَسأَلُكَ ما قَضَيْتَ لي من قَضَاءٍ أَنْ تَجْعَلَ عَاقِبَتَهُ لي رُشْدًا .''',
    transliteration: r'''Allāhumma innī as'aluka al-jannata wa mā qarraba ilayhā min qawlin wa 'amal, wa a'ūdhu bika mina an-nāri wa mā qarraba ilayhā min qawlin wa 'amal, wa as'aluka mā qaḍayta lī min qaḍā'in an taj'ala 'āqibatahu lī rushdā.''',
    translationEn: r'''O Allah, I ask You for Paradise and whatever word or deed draws near to it, and I seek refuge in You from the Fire and whatever word or deed draws near to it. And I ask You that whatever decree You decree for me, You make its outcome for me guidance.''',
    sourceReference: r'''الورد المصفى (Al-Wird al-Musaffa), compiled by 'Abd al-'Aziz al-Faisal Al Sa'ud — Prophetic supplication''',
    repetitionCount: 1,
    repetitionNote: null,
    audioAvailable: true,
    createdAt: _importedAt,
  ),
