    category: AdhkarCategory.protection,
    titleAr: r'''اللهم إني أسألك الجنة ونعيمها''',
    titleEn: r'''I Ask You for Paradise and Its Bliss''',
    arabicText: r'''اللَّهُمَّ إنِّي أَسأَلُكَ الجَنَّةَ وَنَعِيمَهَا وَإسْتَبْرَقَها ، وأَعُوذُ بِكَ مِنَ النَّارِ وسَلاسِلِهَا وأَغْلالِهَا .''',
    transliteration: r'''Allāhumma innī as'aluka al-jannata wa na'īmahā wa istabraqahā, wa a'ūdhu bika mina an-nāri wa salāsilihā wa aghlālihā.''',
    translationEn: r'''O Allah, I ask You for Paradise, its bliss, and its rich silk brocade, and I seek refuge in You from the Fire, its chains, and its shackles.''',
